{"command": "cd /tmp/t && python3 - <<'PY'
import json
from fractions import Fraction
data=json.load(open("/tmp/t/multdata.json"))
def plain(s): return ('.' not in s) and ('e' not in s) and ('E' not in s)
def fits_i64(s):
    if not plain(s): return None
    v=int(s); return v if -2**63<=v<2**63 else None
def fits_u64(s):
    if not plain(s): return None
    v=int(s); return v if 0<=v<2**64 else None
def exact(m,i): return (Fraction(i)/Fraction(m)).denominator==1
def f64mod(m,i): return float(i)%float(m)==0
TH=2**53
def alg(m,i):
    a=fits_i64(i); b=fits_i64(m)
    if a is not None and b is not None: return a%b==0
    a=fits_u64(i); b=fits_u64(m)
    if a is not None and b is not None: return a%b==0
    if not plain(m): return exact(m,i)
    if not plain(i):
        # instance non-plain
        if b is not None and abs(b)<=TH: return f64mod(m,i)
        return exact(m,i)
    return exact(m,i)
bad=[(k,v) for k,v in data.items() if v != (1 if alg(*k.split("|")) else 0)]
print("mismatches:", len(bad), "of", len(data))
for k,v in bad[:20]:
    m,i=k.split("|")
    print(f"mult={m:36s} inst={i:26s} bin={v} alg={alg(m,i)} exact={int(exact(m,i))} f64mod={int(f64mod(m,i))}")
PY"}

