{"command": "cd /workspace && cat > src/num.rs <<'RSEOF'
//! Exact decimal arithmetic helpers used for JSON numbers.
//!
//! JSON numbers are handled with `serde_json`'s `arbitrary_precision` feature,
//! which keeps the original textual representation around.  Comparisons and
//! divisibility checks therefore have to be performed on the decimal value
//! itself rather than on a `f64`.

use serde_json::Number;

/// A decimal number: `-digits * 10^exp`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Dec {
    pub neg: bool,
    pub digits: String, // no leading zeros, no dot, empty means zero
    pub exp: i64,
}

impl Dec {
    pub fn zero() -> Self {
        Dec { neg: false, digits: String::new(), exp: 0 }
    }

    pub fn is_zero(&self) -> bool {
        self.digits.is_empty()
    }

    /// Parse from the canonical textual form of a `serde_json::Number`.
    pub fn parse(s: &str) -> Dec {
        let s = s.trim();
        let mut neg = false;
        let mut body = s;
        if let Some(rest) = body.strip_prefix('-') {
            neg = true;
            body = rest;
        } else if let Some(rest) = body.strip_prefix('+') {
            body = rest;
        }
        let mut mantissa = String::new();
        let mut frac_digits: i64 = 0;
        let mut exp: i64 = 0;
        let bytes: Vec<char> = body.chars().collect();
        let mut i = 0;
        let mut seen_dot = false;
        while i < bytes.len() {
            let c = bytes[i];
            match c {
                '0'..='9' => {
                    mantissa.push(c);
                    if seen_dot {
                        frac_digits += 1;
                    }
                }
                '.' => seen_dot = true,
                'e' | 'E' => {
                    // exponent
                    let mut j = i + 1;
                    let mut eneg = false;
                    if j < bytes.len() && (bytes[j] == '+' || bytes[j] == '-') {
                        if bytes[j] == '-' {
                            eneg = true;
                        }
                        j += 1;
                    }
                    let mut ev = 0i64;
                    while j < bytes.len() {
                        if let Some(d) = bytes[j].to_digit(10) {
                            ev = ev.saturating_mul(10).saturating_add(d as i64);
                        }
                        j += 1;
                    }
                    exp = if eneg { -ev } else { ev };
                    break;
                }
                _ => {}
            }
            i += 1;
        }
        exp -= frac_digits;
        // strip leading zeros
        let trimmed = mantissa.trim_start_matches('0');
        let digits = if trimmed.is_empty() { String::new() } else { trimmed.to_string() };
        let mut d = Dec { neg, digits, exp };
        d.normalize();
        d
    }

    pub fn normalize(&mut self) {
        // strip leading zeros
        while self.digits.len() > 1 && self.digits.starts_with('0') {
            self.digits.remove(0);
        }
        if self.digits == "0" {
            self.digits.clear();
        }
        if self.digits.is_empty() {
            self.neg = false;
            self.exp = 0;
            return;
        }
        // strip trailing zeros, increasing the exponent
        let mut strip = 0;
        let bytes = self.digits.as_bytes();
        while strip < bytes.len() && bytes[bytes.len() - 1 - strip] == b'0' {
            strip += 1;
        }
        if strip > 0 {
            let keep = self.digits.len() - strip;
            self.digits.truncate(keep);
            self.exp += strip as i64;
        }
        if self.digits.is_empty() {
            self.neg = false;
            self.exp = 0;
        }
    }

    pub fn is_integer(&self) -> bool {
        if self.is_zero() {
            return true;
        }
        if self.exp >= 0 {
            true
        } else {
            let frac = (-self.exp) as usize;
            if frac >= self.digits.len() {
                // value < 1
                self.digits.bytes().all(|b| b == b'0')
            } else {
                self.digits[self.digits.len() - frac..].bytes().all(|b| b == b'0')
            }
        }
    }

    pub fn is_negative(&self) -> bool {
        self.neg && !self.is_zero()
    }

    pub fn cmp(&self, other: &Dec) -> std::cmp::Ordering {
        use std::cmp::Ordering;
        if self.is_zero() && other.is_zero() {
            return Ordering::Equal;
        }
        let sn = self.is_negative();
        let on = other.is_negative();
        if sn != on {
            return if sn { Ordering::Less } else { Ordering::Greater };
        }
        // both same sign
        let mag = self.cmp_mag(other);
        if sn {
            mag.reverse()
        } else {
            mag
        }
    }

    fn cmp_mag(&self, other: &Dec) -> std::cmp::Ordering {
        use std::cmp::Ordering;
        let ls = int_len(self);
        let lo = int_len(other);
        if ls != lo {
            return ls.cmp(&lo);
        }
        // compare digit by digit
        let a = self.digits.as_bytes();
        let b = other.digits.as_bytes();
        let n = a.len().max(b.len());
        for i in 0..n {
            let da = if i < a.len() { a[i] } else { b'0' };
            let db = if i < b.len() { b[i] } else { b'0' };
            if da != db {
                return da.cmp(&db);
            }
        }
        Ordering::Equal
    }

    pub fn to_f64(&self) -> f64 {
        self.digits.parse::<f64>().map(|m| if self.neg { -m } else { m } * 10f64.powi(self.exp as i32)).unwrap_or(0.0)
    }

    /// Is `self` divisible by `other` (exact)?
    pub fn divisible_by(&self, other: &Dec) -> bool {
        if other.is_zero() {
            return false;
        }
        if self.is_zero() {
            return true;
        }
        // a = A * 10^ea, b = B * 10^eb  (A, B integer digit strings)
        let (a_digits, ea) = (self.digits.clone(), self.exp);
        let (b_digits, eb) = (other.digits.clone(), other.exp);
        if ea >= eb {
            // quotient = A * 10^(ea-eb) / B
            let shifted = format!("{}{}", a_digits, "0".repeat((ea - eb) as usize));
            big_mod_is_zero(&shifted, &b_digits)
        } else {
            // quotient = A / (B * 10^(eb-ea))
            let divisor = format!("{}{}", b_digits, "0".repeat((eb - ea) as usize));
            big_mod_is_zero(&a_digits, &divisor)
        }
    }
}

/// number of digits before the decimal point
fn int_len(d: &Dec) -> i64 {
    let len = d.digits.len() as i64;
    if len == 0 {
        return 1;
    }
    let l = len + d.exp;
    if l <= 0 {
        1
    } else {
        l
    }
}

fn strip_leading_zeros(s: &str) -> String {
    let t = s.trim_start_matches('0');
    if t.is_empty() {
        "0".to_string()
    } else {
        t.to_string()
    }
}

fn dec_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    let a = strip_leading_zeros(a);
    let b = strip_leading_zeros(b);
    if a.len() != b.len() {
        return a.len().cmp(&b.len());
    }
    a.cmp(&b)
}

fn mul_small(b: &str, d: u32) -> String {
    if d == 0 {
        return "0".to_string();
    }
    let mut out = Vec::new();
    let mut carry = 0u32;
    for c in b.bytes().rev() {
        let v = (c - b'0') as u32 * d + carry;
        out.push((v % 10) as u8 + b'0');
        carry = v / 10;
    }
    while carry > 0 {
        out.push((carry % 10) as u8 + b'0');
        carry /= 10;
    }
    out.reverse();
    strip_leading_zeros(&String::from_utf8(out).unwrap())
}

fn dec_sub(a: &str, b: &str) -> String {
    // a >= b
    let ab: Vec<u8> = a.bytes().collect();
    let bb: Vec<u8> = b.bytes().collect();
    let mut out = Vec::new();
    let mut i = ab.len();
    let mut j = bb.len();
    let mut borrow = 0i32;
    while i > 0 || j > 0 {
        let da = if i > 0 { (ab[i - 1] - b'0') as i32 } else { 0 };
        let db = if j > 0 { (bb[j - 1] - b'0') as i32 } else { 0 };
        let mut v = da - db - borrow;
        if v < 0 {
            v += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        out.push((v as u8) + b'0');
        if i > 0 {
            i -= 1;
        }
        if j > 0 {
            j -= 1;
        }
    }
    while out.len() > 1 && *out.last().unwrap() == b'0' {
        out.pop();
    }
    out.reverse();
    String::from_utf8(out).unwrap()
}

/// remainder of `a / b` where both are non-negative decimal integers
fn big_mod(a: &str, b: &str) -> String {
    if dec_cmp(a, b) == std::cmp::Ordering::Less {
        return strip_leading_zeros(a);
    }
    let mut r = String::from("0");
    for ch in a.chars() {
        if r == "0" {
            r.clear();
        }
        r.push(ch);
        r = strip_leading_zeros(&r);
        if dec_cmp(&r, b) != std::cmp::Ordering::Less {
            let mut d = 1u32;
            while d < 9 && dec_cmp(&mul_small(b, d + 1), &r) != std::cmp::Ordering::Greater {
                d += 1;
            }
            r = dec_sub(&r, &mul_small(b, d));
        }
    }
    strip_leading_zeros(&r)
}

fn big_mod_is_zero(a: &str, b: &str) -> bool {
    big_mod(a, b) == "0"
}

/// Is the number (given by its canonical textual form) an integer?
pub fn number_is_integer(n: &Number) -> bool {
    Dec::parse(&n.to_string()).is_integer()
}

/// Is the textual form "plain", i.e. without a fractional part or exponent?
pub fn number_is_plain(n: &Number) -> bool {
    let s = n.to_string();
    !s.contains('.') && !s.contains('e') && !s.contains('E')
}
RSEOF
sed -i 's/PartialEq, Eq]/PartialEq]/' src/num.rs
echo written"}

