//! Small helpers working on `serde_json::Value`s.

use crate::num::{number_is_integer, number_is_plain, Dec};
use serde_json::{Map, Number, Value};

pub fn is_number(v: &Value) -> bool {
    matches!(v, Value::Number(_))
}

/// JSON type name as used by the `type` keyword.
pub fn type_name(v: &Value, integer_as_integer: bool) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(n) => {
            if integer_as_integer && number_is_integer(n) {
                "integer"
            } else {
                "number"
            }
        }
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

/// Compact JSON serialisation (matching `serde_json::to_string`).
pub fn to_string_compact(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_else(|_| "null".to_string())
}

/// Structural equality where numbers compare numerically.
pub fn value_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Number(x), Value::Number(y)) => num_eq(x, y),
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| value_eq(p, q))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter().all(|(k, v)| y.get(k).map(|w| value_eq(v, w)).unwrap_or(false))
        }
        _ => false,
    }
}

pub fn num_eq(a: &Number, b: &Number) -> bool {
    if a.to_string() == b.to_string() {
        return true;
    }
    let da = Dec::parse(&a.to_string());
    let db = Dec::parse(&b.to_string());
    da.cmp(&db) == std::cmp::Ordering::Equal
}

/// Is the value a valid JSON Schema (boolean or object)?
pub fn is_schema(v: &Value) -> bool {
    matches!(v, Value::Bool(_) | Value::Object(_))
}

pub fn as_object(v: &Value) -> Option<&Map<String, Value>> {
    v.as_object()
}

/// Format a list of items as `, `-joined compact JSON.
pub fn join_json(items: &[Value], sep: &str) -> String {
    items.iter().map(to_string_compact).collect::<Vec<_>>().join(sep)
}
