pub fn validate_date(s: &str) -> bool {
    if s.len() != 10 {
        return false;
    }
    let b = s.as_bytes();
    if b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    if !b[..4].iter().all(|c| c.is_ascii_digit()) || !b[5..7].iter().all(|c| c.is_ascii_digit()) || !b[8..10].iter().all(|c| c.is_ascii_digit()) {
        return false;
    }
    let year: i64 = s[0..4].parse().unwrap();
    let month: u32 = s[5..7].parse().unwrap();
    let day: u32 = s[8..10].parse().unwrap();
    if month < 1 || month > 12 {
        return false;
    }
    if day < 1 || day > days_in_month(year, month) {
        return false;
    }
    true
}

pub fn validate_time(s: &str) -> bool {
    // time-offset = "Z" / ("+"/"-" HH:MM)
    // partial-time = HH:MM:SS(.fraction)?
    let idx = s.find(|c| c == 'Z' || c == 'z' || c == '+' || c == '-');
    let idx = match idx {
        Some(i) => i,
        None => return false,
    };
    let (part, off) = s.split_at(idx);
    let (hms, frac) = match part.find('.') {
        Some(i) => (&part[..i], &part[i..]),
        None => (part, ""),
    };
    let (h, m, sec) = match parse_time_part(hms) {
        Some(v) => v,
        None => return false,
    };
    if h > 23 || m > 59 || sec > 60 {
        return false;
    }
    if !frac.is_empty() {
        if frac.len() < 2 || !frac[1..].bytes().all(|c| c.is_ascii_digit()) {
            return false;
        }
    }
    valid_offset(off)
}

pub fn validate_date_time(s: &str) -> bool {
    // full-date "T" full-time
    let sep = s.find(|c| c == 'T' || c == 't');
    let idx = match sep {
        Some(i) => i,
        None => return false,
    };
    let (d, t) = s.split_at(idx);
    if !validate_date(d) {
        return false;
    }
    let t = &t[1..];
    validate_time(t)
}

pub fn validate_duration(s: &str) -> bool {
    // duration = "P" [n "Y"] [n "M"] [n "W"] [n "D"] ["T" [n "H"] [n "M"] [n "S"]]
    let bytes: Vec<char> = s.chars().collect();
    if bytes.is_empty() || bytes[0] != 'P' {
        return false;
    }
    let mut i = 1;
    let mut seen = false;
    let mut in_time = false;
    while i < bytes.len() {
        if bytes[i] == 'T' {
            if in_time {
                return false;
            }
            in_time = true;
            i += 1;
            continue;
        }
        // number
        let start = i;
        let mut int_part = String::new();
        let mut frac = String::new();
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            int_part.push(bytes[i]);
            i += 1;
        }
        if int_part.is_empty() {
            return false;
        }
        if i < bytes.len() && bytes[i] == '.' {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                frac.push(bytes[i]);
                i += 1;
            }
            if frac.is_empty() {
                return false;
            }
        }
        if i >= bytes.len() {
            return false;
        }
        let unit = bytes[i];
        i += 1;
        match unit {
            'Y' | 'M' | 'W' | 'D' => {
                if !frac.is_empty() {
                    return false;
                }
                if in_time {
                    return false;
                }
            }
            'H' | 'S' => {
                if !in_time {
                    return false;
                }
            }
            'M' => {
                if !in_time && !frac.is_empty() {
                    return false;
                }
            }
            _ => return false,
        }
        seen = true;
    }
    seen
}

pub fn validate_email(s: &str) -> bool {
    let parts: Vec<&str> = s.split('@').collect();
    if parts.len() != 2 {
        return false;
    }
    let (local, domain) = (parts[0], parts[1]);
    if local.is_empty() || domain.is_empty() {
        return false;
    }
    if local.contains(' ') || domain.contains(' ') {
        return false;
    }
    for label in domain.split('.') {
        if label.is_empty() {
            return false;
        }
    }
    if local.starts_with('.') || local.ends_with('.') || local.contains("..") {
        return false;
    }
    true
}

fn valid_hostname(s: &str) -> bool {
    if s.is_empty() || s.len() > 253 {
        return false;
    }
    for label in s.split('.') {
        if label.is_empty() || label.len() > 63 {
            return false;
        }
        let b = label.as_bytes();
        if b[0] == b'-' || b[label.len() - 1] == b'-' {
            return false;
        }
        if !b.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'-') {
            return false;
        }
    }
    true
}

pub fn validate_hostname(s: &str) -> bool {
    valid_hostname(s)
}

pub fn validate_idn_hostname(s: &str) -> bool {
    // Rough approximation of IDNA2008: every label must be valid, either as an
    // ASCII hostname or as a punycode label ("xn--" prefixed).
    if s.is_empty() {
        return false;
    }
    for label in s.split('.') {
        if label.is_empty() {
            return false;
        }
        if label.starts_with("xn--") {
            if label.len() <= 4 {
                return false;
            }
            if !label[4..].bytes().all(|c| c.is_ascii_alphanumeric() || c == b'-') {
                return false;
            }
        } else if label.is_ascii() {
            if label.len() > 63 {
                return false;
            }
            let b = label.as_bytes();
            if b[0] == b'-' || b[label.len() - 1] == b'-' {
                return false;
            }
            if !b.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'-') {
                return false;
            }
        } else {
            // non-ASCII label: allowed if it contains letter/digit characters
            if !label.chars().any(|c| c.is_alphanumeric()) {
                return false;
            }
        }
    }
    true
}

pub fn validate_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    for p in parts {
        if p.is_empty() || p.len() > 3 {
            return false;
        }
        if !p.bytes().all(|c| c.is_ascii_digit()) {
            return false;
        }
        if p.len() > 1 && p.starts_with('0') {
            return false;
        }
        let v: u32 = match p.parse() {
            Ok(v) => v,
            Err(_) => return false,
        };
        if v > 255 {
            return false;
        }
    }
    true
}

