pub fn validate_json_pointer(s: &str) -> bool {
    if !s.starts_with('/') {
        return false;
    }
    // any character is allowed except unescaped "~"
    let bytes: Vec<char> = s.chars().collect();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == '~' {
            if i + 1 >= bytes.len() || (bytes[i + 1] != '0' && bytes[i + 1] != '1') {
                return false;
            }
            i += 2;
        } else {
            i += 1;
        }
    }
    true
}

pub fn validate_relative_json_pointer(s: &str) -> bool {
    // non-negative-integer [ "#" json-pointer ] | non-negative-integer json-pointer
    let bytes: Vec<char> = s.chars().collect();
    if bytes.is_empty() {
        return false;
    }
    let mut i = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    if i == 0 {
        return false;
    }
    let rest: String = bytes[i..].iter().collect();
    if rest.is_empty() {
        return true;
    }
    if let Some(r) = rest.strip_prefix('#') {
        if r.is_empty() {
            return true;
        }
        return validate_json_pointer(r);
    }
    if rest.starts_with('/') {
        return validate_json_pointer(&rest);
    }
    false
}

pub fn validate_uuid(s: &str) -> bool {
    let b: Vec<char> = s.chars().collect();
    if b.len() != 36 {
        return false;
    }
    let dash_positions = [8usize, 13, 18, 23];
    for (i, c) in b.iter().enumerate() {
        if dash_positions.contains(&i) {
            if *c != '-' {
                return false;
            }
        } else if !c.is_ascii_hexdigit() {
            return false;
        }
    }
    true
}

pub fn validate_uri_template(s: &str) -> bool {
    // RFC 6570 level 4 (simplified): expressions {..} with var names
    let bytes: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            '{' => {
                i += 1;
                let start = i;
                let mut depth_ok = false;
                while i < bytes.len() {
                    if bytes[i] == '}' {
                        depth_ok = true;
                        break;
                    }
                    i += 1;
                }
                if !depth_ok {
                    return false;
                }
                let expr: String = bytes[start..i].iter().collect();
                if !valid_template_expr(&expr) {
                    return false;
                }
                i += 1;
            }
            '%' => {
                if i + 2 >= bytes.len() {
                    return false;
                }
                if !bytes[i + 1].is_ascii_hexdigit() || !bytes[i + 2].is_ascii_hexdigit() {
                    return false;
                }
                i += 3;
            }
            c if is_uri_char(c) => i += 1,
            _ => return false,
        }
    }
    true
}

fn is_uri_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || "-._~:/?#[]@!$&'()*+,;=".contains(c)
}

fn valid_template_expr(e: &str) -> bool {
    if e.is_empty() {
        return false;
    }
    let mut ops = "+#./;?&".chars();
    let mut body = e;
    if let Some(first) = e.chars().next() {
        if ops.any(|o| o == first) {
            body = &e[1..];
        }
    }
    if body.is_empty() {
        return false;
    }
    for part in body.split(',') {
        if part.is_empty() {
            return false;
        }
        let mut p = part;
        if let Some(idx) = p.find(':') {
            let (a, b) = (&p[..idx], &p[idx + 1..]);
            if a.is_empty() || b.is_empty() || !b.bytes().all(|c| c.is_ascii_digit()) {
                return false;
            }
            p = a;
        }
        if p.ends_with('*') {
            p = &p[..p.len() - 1];
        }
        if p.is_empty() {
            return false;
        }
        if !p.chars().next().unwrap().is_ascii_alphanumeric() && p.chars().next().unwrap() != '_' {
            return false;
        }
        if !p.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.') {
            return false;
        }
    }
    true
}

