        if i < bytes.len() && bytes[i] == '.' {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                frac.push(bytes[i]);
                i += 1;
            }
            if frac.is_empty() {
                return false;
            }
        }
        if i >= bytes.len() {
            return false;
        }
        let unit = bytes[i];
        i += 1;
        match unit {
            'Y' | 'M' | 'W' | 'D' => {
                if !frac.is_empty() {
                    return false;
                }
                if in_time {
                    return false;
                }
            }
            'H' | 'S' => {
                if !in_time {
                    return false;
                }
            }
            'M' => {
                if !in_time && !frac.is_empty() {
                    return false;
                }
            }
            _ => return false,
        }
        seen = true;
    }
    seen
}

pub fn validate_email(s: &str) -> bool {
    let parts: Vec<&str> = s.split('@').collect();
    if parts.len() != 2 {
        return false;
    }
    let (local, domain) = (parts[0], parts[1]);
    if local.is_empty() || domain.is_empty() {
        return false;
    }
    if local.contains(' ') || domain.contains(' ') {
        return false;
    }
    for label in domain.split('.') {
        if label.is_empty() {
            return false;
        }
    }
    if local.starts_with('.') || local.ends_with('.') || local.contains("..") {
        return false;
    }
    true
}

fn valid_hostname(s: &str) -> bool {
    if s.is_empty() || s.len() > 253 {
        return false;
    }
    for label in s.split('.') {
        if label.is_empty() || label.len() > 63 {
            return false;
        }
        let b = label.as_bytes();
        if b[0] == b'-' || b[label.len() - 1] == b'-' {
            return false;
        }
        if !b.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'-') {
            return false;
        }
    }
    true
}

pub fn validate_hostname(s: &str) -> bool {
    valid_hostname(s)
}

pub fn validate_idn_hostname(s: &str) -> bool {
    // Rough approximation of IDNA2008: every label must be valid, either as an
    // ASCII hostname or as a punycode label ("xn--" prefixed).
    if s.is_empty() {
        return false;
    }
    for label in s.split('.') {
        if label.is_empty() {
            return false;
        }
        if label.starts_with("xn--") {
            if label.len() <= 4 {
                return false;
            }
            if !label[4..].bytes().all(|c| c.is_ascii_alphanumeric() || c == b'-') {
                return false;
            }
        } else if label.is_ascii() {
            if label.len() > 63 {
                return false;
            }
            let b = label.as_bytes();
            if b[0] == b'-' || b[label.len() - 1] == b'-' {
                return false;
            }
            if !b.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'-') {
                return false;
            }
        } else {
            // non-ASCII label: allowed if it contains letter/digit characters
            if !label.chars().any(|c| c.is_alphanumeric()) {
                return false;
            }
        }
    }
    true
}

pub fn validate_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    for p in parts {
        if p.is_empty() || p.len() > 3 {
            return false;
        }
        if !p.bytes().all(|c| c.is_ascii_digit()) {
            return false;
        }
        if p.len() > 1 && p.starts_with('0') {
            return false;
        }
        let v: u32 = match p.parse() {
            Ok(v) => v,
            Err(_) => return false,
        };
        if v > 255 {
            return false;
        }
    }
    true
}

pub fn validate_ipv6(s: &str) -> bool {
    // Full IPv6 parsing, including "::" abbreviation and embedded IPv4.
    let s = s;
    if s.is_empty() {
        return false;
    }
    // handle zone id
    let s = match s.find('%') {
        Some(i) => &s[..i],
        None => s,
    };
    let (head, tail) = match s.find("::") {
        Some(i) => (&s[..i], Some(&s[i + 2..])),
        None => (s, None),
    };
    if s.matches("::").count() > 1 {
        return false;
    }
    let mut groups: Vec<&str> = Vec::new();
    let mut embedded: Option<&str> = None;
    let mut process = |part: &str, groups: &mut Vec<&str>| -> bool {
        if part.is_empty() {
            return true;
        }
        let parts: Vec<&str> = part.split(':').collect();
        for (i, p) in parts.iter().enumerate() {
            if p.contains('.') {
                if i != parts.len() - 1 {
                    return false;
                }
                if !validate_ipv4(p) {
                    return false;
                }
                groups.push(p);
                return true;
            }
            if p.is_empty() {
                return false;
            }
            if p.len() > 4 {
                return false;
            }
            if !p.bytes().all(|c| c.is_ascii_hexdigit()) {
                return false;
            }
            groups.push(p);
        }
        true
    };
    if !process(head, &mut groups) {
        return false;
    }
    if let Some(t) = tail {
        let mut g2: Vec<&str> = Vec::new();
        if !process(t, &mut g2) {
            return false;
        }
        if head.is_empty() && t.is_empty() {
            // "::"
        } else if head.is_empty() || t.is_empty() {
            // fine
        }
        groups.extend(g2);
        if groups.len() > 7 {
            return false;
        }
        true
    } else {
        groups.len() == 8
    }
}

pub fn validate_json_pointer(s: &str) -> bool {
    if !s.starts_with('/') {
        return false;
    }
    // any character is allowed except unescaped "~"
    let bytes: Vec<char> = s.chars().collect();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == '~' {
            if i + 1 >= bytes.len() || (bytes[i + 1] != '0' && bytes[i + 1] != '1') {
                return false;
            }
            i += 2;
        } else {
            i += 1;
        }
    }
    true
}

pub fn validate_relative_json_pointer(s: &str) -> bool {
    // non-negative-integer [ "#" json-pointer ] | non-negative-integer json-pointer
    let bytes: Vec<char> = s.chars().collect();
    if bytes.is_empty() {
        return false;
    }
    let mut i = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    if i == 0 {
        return false;
    }
    let rest: String = bytes[i..].iter().collect();
    if rest.is_empty() {
        return true;
    }
    if let Some(r) = rest.strip_prefix('#') {
        if r.is_empty() {
            return true;
        }
        return validate_json_pointer(r);
    }
    if rest.starts_with('/') {
        return validate_json_pointer(&rest);
    }
    false
}

pub fn validate_uuid(s: &str) -> bool {
    let b: Vec<char> = s.chars().collect();
    if b.len() != 36 {
        return false;
    }
    let dash_positions = [8usize, 13, 18, 23];
    for (i, c) in b.iter().enumerate() {
        if dash_positions.contains(&i) {
            if *c != '-' {
                return false;
            }
        } else if !c.is_ascii_hexdigit() {
            return false;
        }
    }
    true
}

pub fn validate_uri_template(s: &str) -> bool {
    // RFC 6570 level 4 (simplified): expressions {..} with var names
    let bytes: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            '{' => {
                i += 1;
                let start = i;
                let mut depth_ok = false;
                while i < bytes.len() {
                    if bytes[i] == '}' {
                        depth_ok = true;
                        break;
                    }
                    i += 1;
                }
                if !depth_ok {
                    return false;
                }
                let expr: String = bytes[start..i].iter().collect();
                if !valid_template_expr(&expr) {
                    return false;
                }
                i += 1;
            }
            '%' => {
                if i + 2 >= bytes.len() {
                    return false;
                }
                if !bytes[i + 1].is_ascii_hexdigit() || !bytes[i + 2].is_ascii_hexdigit() {
                    return false;
                }
                i += 3;
            }
            c if is_uri_char(c) => i += 1,
            _ => return false,
        }
    }
    true
}

fn is_uri_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || "-._~:/?#[]@!$&'()*+,;=".contains(c)
}

fn valid_template_expr(e: &str) -> bool {
    if e.is_empty() {
        return false;
    }
    let mut ops = "+#./;?&".chars();
    let mut body = e;
    if let Some(first) = e.chars().next() {
        if ops.any(|o| o == first) {
            body = &e[1..];
        }
    }
    if body.is_empty() {
        return false;
    }
    for part in body.split(',') {
        if part.is_empty() {
            return false;
        }
        let mut p = part;
        if let Some(idx) = p.find(':') {
            let (a, b) = (&p[..idx], &p[idx + 1..]);
            if a.is_empty() || b.is_empty() || !b.bytes().all(|c| c.is_ascii_digit()) {
                return false;
            }
            p = a;
        }
        if p.ends_with('*') {
            p = &p[..p.len() - 1];
        }
        if p.is_empty() {
            return false;
        }
        if !p.chars().next().unwrap().is_ascii_alphanumeric() && p.chars().next().unwrap() != '_' {
            return false;
        }
        if !p.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.') {
            return false;
        }
    }
    true
}

pub fn validate_regex(s: &str) -> bool {
    Regex::new(s).is_ok()
}

pub fn validate_iri(s: &str) -> bool {
    // Only the ASCII subset is a valid IRI for our purposes: non-ASCII is
    // not allowed (iri allows unicode, but the reference implementation is
    // stricter here).
    if s.chars().any(|c| !c.is_ascii()) {
        return false;
    }
    crate::uri::validate_uri_reference(s).is_ok()
}

pub fn validate_iri_reference(s: &str) -> bool {
    true
}

pub fn validate_uri(s: &str) -> bool {
    true
}

pub fn validate_uri_reference(s: &str) -> bool {
    true
}

/// Validate `value` against the format named `format`.
/// Returns `false` when the format is known and the value does not match.
pub fn check(format: &str, value: &str) -> Option<bool> {
    let r = match format {
        "date" => validate_date(value),
        "date-time" => validate_date_time(value),
        "time" => validate_time(value),
        "duration" => validate_duration(value),
        "email" => validate_email(value),
        "hostname" => validate_hostname(value),
        "idn-hostname" => validate_idn_hostname(value),
        "ipv4" => validate_ipv4(value),
        "ipv6" => validate_ipv6(value),
        "iri" => validate_iri(value),
        "iri-reference" => validate_iri_reference(value),
        "json-pointer" => validate_json_pointer(value),
        "regex" => validate_regex(value),
        "relative-json-pointer" => validate_relative_json_pointer(value),
        "uri" => validate_uri(value),
        "uri-reference" => validate_uri_reference(value),
        "uri-template" => validate_uri_template(value),
        "uuid" => validate_uuid(value),
        _ => return None,
    };
    Some(r)
}
