//! Minimal URI-reference validation and resolution.

use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub struct UriError {
    pub message: String,
}

impl fmt::Display for UriError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

fn is_unreserved(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~')
}

fn is_sub_delim(b: u8) -> bool {
    matches!(b, b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';' | b'=')
}

fn is_pchar(b: u8) -> bool {
    is_unreserved(b) || is_sub_delim(b) || b == b':' || b == b'@'
}

fn is_scheme_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'+' || b == b'-' || b == b'.'
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn err_unexpected(&self) -> UriError {
        UriError { message: format!("unexpected character at index {}", self.pos) }
    }
    fn err_pct(&self) -> UriError {
        UriError { message: format!("invalid percent-encoded octet at index {}", self.pos) }
    }

    /// consume a percent encoded triplet or a single allowed byte
    fn pchar(&mut self) -> Result<(), UriError> {
        let b = self.bytes[self.pos];
        if b == b'%' {
            if self.pos + 2 >= self.bytes.len()
                || !self.bytes[self.pos + 1].is_ascii_hexdigit()
                || !self.bytes[self.pos + 2].is_ascii_hexdigit()
            {
                return Err(self.err_pct());
            }
            self.pos += 3;
            Ok(())
        } else if is_pchar(b) {
            self.pos += 1;
            Ok(())
        } else {
            Err(self.err_unexpected())
        }
    }

    fn while_p(&mut self, pred: impl Fn(u8) -> bool) {
        while self.pos < self.bytes.len() && pred(self.bytes[self.pos]) {
            self.pos += 1;
        }
    }
}

/// Validate a URI reference (RFC 3986) the way the `iref` crate does.
pub fn validate_uri_reference(s: &str) -> Result<(), UriError> {
    let bytes = s.as_bytes();
    let mut p = Parser { bytes, pos: 0 };
    // scheme
    let mut has_scheme = false;
    if !bytes.is_empty() && bytes[0].is_ascii_alphabetic() {
        let mut i = 1;
        while i < bytes.len() && is_scheme_char(bytes[i]) {
            i += 1;
        }
        if i < bytes.len() && bytes[i] == b':' {
            has_scheme = true;
            p.pos = i + 1;
        }
    }
    // hier-part
    let rest_after_scheme = p.pos;
    if p.pos + 1 < bytes.len() && bytes[p.pos] == b'/' && bytes[p.pos + 1] == b'/' {
        // authority
        p.pos += 2;
        let auth_start = p.pos;
        // authority ends at '/', '?' or '#'
        while p.pos < bytes.len() && !matches!(bytes[p.pos], b'/' | b'?' | b'#') {
            p.pos += 1;
        }
        let authority = &s[auth_start..p.pos];
        validate_authority(authority)?;
    } else if has_scheme {
        // path must start with '/' or be empty
        if p.pos < bytes.len() && bytes[p.pos] != b'/' {
            // relative path after scheme is invalid for absolute URIs
            // (iref accepts path-abempty for absolute URIs? be permissive)
        }
    }
    let _ = rest_after_scheme;
    // path
    while p.pos < bytes.len() {
        match bytes[p.pos] {
            b'/' => p.pos += 1,
            b'?' | b'#' => break,
            _ => {
                // for relative references and path segments
                let b = bytes[p.pos];
                if b == b':' || is_pchar(b) {
                    if b == b'%' {
                        if p.pos + 2 >= bytes.len()
                            || !bytes[p.pos + 1].is_ascii_hexdigit()
                            || !bytes[p.pos + 2].is_ascii_hexdigit()
                        {
                            return Err(p.err_pct());
                        }
                        p.pos += 3;
                    } else {
                        p.pos += 1;
                    }
                } else {
                    return Err(p.err_unexpected());
                }
            }
        }
    }
    // query
    if p.pos < bytes.len() && bytes[p.pos] == b'?' {
        p.pos += 1;
        while p.pos < bytes.len() && bytes[p.pos] != b'#' {
            let b = bytes[p.pos];
            if b == b'/' || is_pchar(b) || b == b'?' {
                if b == b'%' {
                    if p.pos + 2 >= bytes.len()
                        || !bytes[p.pos + 1].is_ascii_hexdigit()
                        || !bytes[p.pos + 2].is_ascii_hexdigit()
                    {
                        return Err(p.err_pct());
                    }
                    p.pos += 3;
                } else {
                    p.pos += 1;
                }
            } else {
                return Err(p.err_unexpected());
            }
        }
    }
    // fragment
    if p.pos < bytes.len() && bytes[p.pos] == b'#' {
        p.pos += 1;
        while p.pos < bytes.len() {
            let b = bytes[p.pos];
            if b == b'/' || is_pchar(b) || b == b'?' {
                if b == b'%' {
                    if p.pos + 2 >= bytes.len()
                        || !bytes[p.pos + 1].is_ascii_hexdigit()
                        || !bytes[p.pos + 2].is_ascii_hexdigit()
                    {
                        return Err(p.err_pct());
                    }
                    p.pos += 3;
                } else {
                    p.pos += 1;
                }
            } else {
                return Err(p.err_unexpected());
            }
        }
    }
    Ok(())
}

fn validate_authority(auth: &str) -> Result<(), UriError> {
    // [userinfo@]host[:port]
    let (userinfo, hostport) = match auth.rfind('@') {
        Some(i) => (Some(&auth[..i]), &auth[i + 1..]),
        None => (None, auth),
    };
    if let Some(ui) = userinfo {
        for (i, b) in ui.bytes().enumerate() {
            if b == b'%' {
                if i + 2 >= ui.len() || !ui[i + 1..].chars().take(2).all(|c| c.is_ascii_hexdigit()) {
                    return Err(UriError { message: format!("invalid percent-encoded octet at index {}", i) });
                }
            } else if !(is_unreserved(b) || is_sub_delim(b) || b == b':') {
                return Err(UriError { message: format!("unexpected character at index {}", i) });
            }
        }
    }
    // host
    let host = if hostport.starts_with('[') {
        match hostport.find(']') {
            Some(i) => &hostport[..=i],
            None => return Err(UriError { message: format!("unexpected character at index {}", hostport.len()) }),
        }
    } else {
        match hostport.find(':') {
            Some(i) => &hostport[..i],
            None => hostport,
        }
    };
    if host.starts_with('[') {
        // IPv6 literal
        let inner = &host[1..host.len() - 1];
        if inner.is_empty() {
            return Err(UriError { message: "unexpected character at index 1".to_string() });
        }
        for b in inner.bytes() {
            if !(b.is_ascii_hexdigit() || b == b':' || b == b'.') {
                return Err(UriError { message: format!("unexpected character at index {}", 1) });
            }
        }
    } else {
        for (i, b) in host.bytes().enumerate() {
            if b == b'%' {
                if i + 2 >= host.len() || !host[i + 1..].chars().take(2).all(|c| c.is_ascii_hexdigit()) {
                    return Err(UriError { message: format!("invalid percent-encoded octet at index {}", i) });
                }
            } else if !(is_unreserved(b) || is_sub_delim(b)) {
                return Err(UriError { message: format!("unexpected character at index {}", i) });
            }
        }
    }
    Ok(())
}

/// Split a URI reference into (uri-without-fragment, fragment).
/// The fragment keeps its leading '#'.
pub fn split_fragment(s: &str) -> (&str, Option<&str>) {
    match s.find('#') {
        Some(i) => (&s[..i], Some(&s[i + 1..])),
        None => (s, None),
    }
}

/// Resolve `reference` against `base`.
pub fn resolve(base: &str, reference: &str) -> String {
    if reference.is_empty() {
        return base.to_string();
    }
    if let Some(i) = reference.find(':') {
        // scheme?
        let scheme_ok = i > 0
            && reference[..i].chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false)
            && reference[..i].chars().all(|c| c.is_ascii_alphanumeric() || "+-.".contains(c));
        if scheme_ok {
            return reference.to_string();
        }
    }
    if reference.starts_with('#') {
        let (b, _) = split_fragment(base);
        return format!("{}{}", b, reference);
    }
    let (b_no_frag, _) = split_fragment(base);
    if reference.starts_with("//") {
        let (scheme, _) = split_scheme(b_no_frag);
        return match scheme {
            Some(sc) => format!("{}:{}", sc, reference),
            None => reference.to_string(),
        };
    }
    let (r_no_frag, r_frag) = split_fragment(reference);
    let (b_scheme, b_rest) = split_scheme(b_no_frag);
    let merged = if r_no_frag.is_empty() {
        b_rest.to_string()
    } else if r_no_frag.starts_with('/') {
        r_no_frag.to_string()
    } else {
        // relative path: remove the last segment of the base path
        let idx = b_rest.rfind('/').map(|i| i + 1).unwrap_or(0);
        format!("{}{}", &b_rest[..idx], r_no_frag)
    };
    let mut out = match b_scheme {
        Some(sc) => format!("{}:{}", sc, merged),
        None => merged,
    };
    if let Some(f) = r_frag {
        out.push('#');
        out.push_str(f);
    }
    out
}

fn split_scheme(s: &str) -> (Option<&str>, &str) {
    if let Some(i) = s.find(':') {
        let scheme = &s[..i];
        let ok = !scheme.is_empty()
            && scheme.chars().next().unwrap().is_ascii_alphabetic()
            && scheme.chars().all(|c| c.is_ascii_alphanumeric() || "+-.".contains(c));
        if ok {
            return (Some(scheme), &s[i + 1..]);
        }
    }
    (None, s)
}
