//! Basic output ("list"/"hierarchical") structures.

use serde_json::{Map, Value};

#[derive(Debug, Clone)]
pub enum ErrVal {
    One(String),
    Many(Vec<String>),
}

impl ErrVal {
    pub fn to_value(&self) -> Value {
        match self {
            ErrVal::One(s) => Value::String(s.clone()),
            ErrVal::Many(v) => Value::Array(v.iter().map(|s| Value::String(s.clone())).collect()),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Unit {
    pub valid: bool,
    pub eval_path: String,
    pub instance_path: String,
    pub schema_location: String,
    pub errors: Vec<(String, ErrVal)>,
    /// annotation attached to this unit (either a single keyword annotation or
    /// a map of annotation-only keywords)
    pub annotations: Option<Value>,
    pub dropped: Option<Value>,
    pub details: Vec<Unit>,
}

impl Unit {
    pub fn to_value(&self) -> Value {
        let mut m = Map::new();
        m.insert("evaluationPath".into(), Value::String(self.eval_path.clone()));
        m.insert("instanceLocation".into(), Value::String(self.instance_path.clone()));
        m.insert("schemaLocation".into(), Value::String(self.schema_location.clone()));
        m.insert("valid".into(), Value::Bool(self.valid));
        if !self.errors.is_empty() {
            let mut e = Map::new();
            for (k, v) in &self.errors {
                e.insert(k.clone(), v.to_value());
            }
            m.insert("errors".into(), Value::Object(e));
        }
        if let Some(a) = &self.annotations {
            m.insert("annotations".into(), a.clone());
        }
        if let Some(d) = &self.dropped {
            m.insert("droppedAnnotations".into(), d.clone());
        }
        if !self.details.is_empty() {
            m.insert("details".into(), Value::Array(self.details.iter().map(|d| d.to_value()).collect()));
        }
        Value::Object(m)
    }

    /// Convert a flat list of units into a hierarchical structure.
    pub fn hierarchical(units: Vec<Unit>) -> Vec<Unit> {
        // group by parent path
        let mut roots: Vec<Unit> = Vec::new();
        for u in units {
            insert_hierarchical(&mut roots, u);
        }
        roots
    }
}

fn parent_of(path: &str) -> Option<&str> {
    if path.is_empty() {
        return None;
    }
    match path.rfind('/') {
        Some(0) => Some(""),
        Some(i) => Some(&path[..i]),
        None => None,
    }
}

fn insert_hierarchical(list: &mut Vec<Unit>, u: Unit) {
    match parent_of(&u.eval_path) {
        None => {
            // merge into an existing root with the same path
            if let Some(existing) = list.iter_mut().find(|e| e.eval_path == u.eval_path) {
                merge_unit(existing, u);
            } else {
                list.push(u);
            }
        }
        Some(p) => {
            // find (or create) the parent
            if let Some(existing) = list.iter_mut().find(|e| e.eval_path == p) {
                merge_child(existing, u);
            } else {
                let mut parent = Unit {
                    valid: true,
                    eval_path: p.to_string(),
                    ..Default::default()
                };
                merge_child(&mut parent, u);
                insert_hierarchical(list, parent);
            }
        }
    }
}

fn merge_unit(target: &mut Unit, mut u: Unit) {
    if target.eval_path != u.eval_path {
        target.details.push(u);
        return;
    }
    if u.errors.is_empty() && u.annotations.is_none() && u.dropped.is_none() {
        target.details.append(&mut u.details);
        return;
    }
    // replace/merge: keep the more informative one
    if target.errors.is_empty() && target.annotations.is_none() && target.dropped.is_none() {
        target.valid = u.valid;
        target.errors = u.errors;
        target.annotations = u.annotations;
        target.dropped = u.dropped;
        target.schema_location = u.schema_location;
        target.instance_path = u.instance_path;
        target.details.append(&mut u.details);
    } else {
        target.details.append(&mut u.details);
    }
}

