//! Basic output ("list"/"hierarchical") structures.

use serde_json::{Map, Value};

#[derive(Debug, Clone)]
pub enum ErrVal {
    One(String),
    Many(Vec<String>),
}

impl ErrVal {
    pub fn to_value(&self) -> Value {
        match self {
            ErrVal::One(s) => Value::String(s.clone()),
            ErrVal::Many(v) => Value::Array(v.iter().map(|s| Value::String(s.clone())).collect()),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Unit {
    pub valid: bool,
    pub eval_path: String,
    pub instance_path: String,
    pub schema_location: String,
    pub errors: Vec<(String, ErrVal)>,
    pub annotations: Option<Value>,
    pub dropped: Option<Value>,
    pub details: Vec<Unit>,
}

impl Unit {
    pub fn to_value(&self) -> Value {
        let mut m = Map::new();
        m.insert("evaluationPath".into(), Value::String(self.eval_path.clone()));
        m.insert("instanceLocation".into(), Value::String(self.instance_path.clone()));
        m.insert("schemaLocation".into(), Value::String(self.schema_location.clone()));
        m.insert("valid".into(), Value::Bool(self.valid));
        if !self.errors.is_empty() {
            let mut e = Map::new();
            for (k, v) in &self.errors {
                e.insert(k.clone(), v.to_value());
            }
            m.insert("errors".into(), Value::Object(e));
        }
        if let Some(a) = &self.annotations {
            m.insert("annotations".into(), a.clone());
        }
        if let Some(d) = &self.dropped {
            m.insert("droppedAnnotations".into(), d.clone());
        }
        if !self.details.is_empty() {
            m.insert("details".into(), Value::Array(self.details.iter().map(|d| d.to_value()).collect()));
        }
        Value::Object(m)
    }
}

fn is_prefix(parent: &str, child: &str) -> bool {
    if parent.is_empty() {
        return true;
    }
    if !child.starts_with(parent) {
        return false;
    }
    let rest = &child[parent.len()..];
    rest.is_empty() || rest.starts_with('/')
}

/// Convert a flat list of units (in traversal order) into a hierarchy.
pub fn hierarchical(units: Vec<Unit>) -> Vec<Unit> {
    let mut roots: Vec<Unit> = Vec::new();
    let mut stack: Vec<Vec<usize>> = Vec::new();
    for u in units {
        while let Some(top) = stack.last() {
            let tp = path_of(&roots, top);
            if is_prefix(&tp, &u.eval_path) {
                break;
            }
            stack.pop();
        }
        let idx = if stack.is_empty() {
            roots.push(u);
            roots.len() - 1
        } else {
            push_at(&mut roots, stack.last().unwrap(), u)
        };
        let mut p = stack.last().cloned().unwrap_or_default();
        p.push(idx);
        stack.push(p);
    }
    roots
}

fn path_of(units: &[Unit], idx: &[usize]) -> String {
    let mut cur = &units[idx[0]];
    for i in &idx[1..] {
        cur = &cur.details[*i];
    }
    cur.eval_path.clone()
}

fn push_at(units: &mut [Unit], idx: &[usize], u: Unit) -> usize {
    if idx.len() == 1 {
        units[idx[0]].details.push(u);
        units[idx[0]].details.len() - 1
    } else {
        push_at(&mut units[idx[0]].details, &idx[1..], u)
    }
}

/// Collect all error messages of a unit tree, in traversal order.
pub fn collect_messages(units: &[Unit]) -> Vec<String> {
    let mut out = Vec::new();
    for u in units {
        for (_, ev) in &u.errors {
            match ev {
                ErrVal::One(s) => out.push(s.clone()),
                ErrVal::Many(v) => out.extend(v.iter().cloned()),
            }
        }
        out.extend(collect_messages(&u.details));
    }
    out
}
