//! A very small HTTP/1.1 client (plain http only).

use std::io::{Read, Write};
use std::net::TcpStream;
use std::time::Duration;

#[derive(Clone, Debug)]
pub struct HttpClient {
    pub connect_timeout: Option<f64>,
    pub timeout: Option<f64>,
    pub insecure: bool,
    pub cacert: Option<String>,
}

impl Default for HttpClient {
    fn default() -> Self {
        HttpClient { connect_timeout: None, timeout: None, insecure: false, cacert: None }
    }
}

impl HttpClient {
    pub fn get(&self, url: &str) -> Result<String, String> {
        let (host, port, path, tls) = parse_url(url).ok_or_else(|| format!("error sending request for url ({})", url))?;
        if tls {
            return Err(format!("error sending request for url ({})", url));
        }
        let addr = format!("{}:{}", host, port);
        let stream = if let Some(t) = self.connect_timeout {
            TcpStream::connect_timeout(
                &addr
                    .to_socket_addrs()
                    .map_err(|e| e.to_string())?
                    .next()
                    .ok_or_else(|| "no address".to_string())?,
                Duration::from_millis((t * 1000.0) as u64),
            )
        } else {
            TcpStream::connect(&addr)
        }
        .map_err(|e| format!("error sending request for url ({}): {}", url, e))?;
        stream
            .set_read_timeout(Some(Duration::from_millis(
                (self.timeout.unwrap_or(30.0) * 1000.0) as u64,
            )))
            .ok();
        let mut stream = stream;
        let req = format!("GET {} HTTP/1.1\r\nHost: {}\r\nAccept: */*\r\nConnection: close\r\n\r\n", path, host);
        stream.write_all(req.as_bytes()).map_err(|e| e.to_string())?;
        let mut buf = Vec::new();
        stream.read_to_end(&mut buf).map_err(|e| e.to_string())?;
        let text = String::from_utf8_lossy(&buf);
        let body = match text.find("\r\n\r\n") {
            Some(i) => text[i + 4..].to_string(),
            None => text.to_string(),
        };
        Ok(body)
    }
}

fn parse_url(url: &str) -> Option<(String, u16, String, bool)> {
    let (scheme, rest) = if let Some(r) = url.strip_prefix("http://") {
        ("http", r)
    } else if let Some(r) = url.strip_prefix("https://") {
        ("https", r)
    } else {
        return None;
    };
    let (hostport, path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, "/"),
    };
    let (host, port) = match hostport.rfind(':') {
        Some(i) if !hostport[i + 1..].is_empty() => (
            hostport[..i].to_string(),
            hostport[i + 1..].parse::<u16>().unwrap_or(80),
        ),
        _ => (hostport.to_string(), if scheme == "https" { 443 } else { 80 }),
    };
    Some((host, port, path.to_string(), scheme == "https"))
}

