    };
    let (host, port) = match hostport.rfind(':') {
        Some(i) if !hostport[i + 1..].is_empty() => (
            hostport[..i].to_string(),
            hostport[i + 1..].parse::<u16>().unwrap_or(80),
        ),
        _ => (hostport.to_string(), if scheme == "https" { 443 } else { 80 }),
    };
    Some((host, port, path.to_string(), scheme == "https"))
}

