}

pub struct RefTarget {
    pub node: Node,
    /// location used for the `$ref` keyword unit
    pub location: String,
}

pub enum Keyword {
    /// annotation only, attached to the parent unit
    Annotation { name: String, value: Value },
    Type(Vec<String>),
    Const(Value),
    Enum(Vec<Value>),
    MultipleOf(Value),
    Maximum { limit: Value, exclusive: bool },
    Minimum { limit: Value, exclusive: bool },
    MaxLength(u64),
    MinLength(u64),
    Pattern { re: Regex, raw: String },
    MaxItems(u64),
    MinItems(u64),
    UniqueItems,
