pub fn compile(
    schema: &Value,
    pointer: &str,
    uri: &str,
    ctx: &mut Ctx,
) -> Result<Node, CompileError> {
    if let Value::Bool(false) = schema {
        return Ok(Node { pointer: pointer.to_string(), uri: uri.to_string(), keywords: vec![], is_false: true });
    }
    let obj = match schema {
        Value::Object(o) => o,
        Value::Bool(true) => Map::new(),
        _ => {
            return Err(CompileError::Schema(format!(
                "{} is not of types \"boolean\", \"object\"",
                to_string_compact(schema)
            )))
        }
    };
    let mut keywords: Vec<Keyword> = Vec::new();
    // iterate in the canonical (sorted) order imposed by the map, but emit in
    // the fixed order used by the reference implementation
    let mut annotations: Vec<(String, Value)> = Vec::new();
    for (k, v) in obj {
        annotations.push((k.clone(), v.clone()));
    }
    let get = |name: &str| obj.get(name);
    // reserved keywords first ($id, $schema, $defs, $anchor, $dynamicAnchor)
    for name in ["$id", "$schema", "$defs", "$anchor", "$dynamicAnchor"] {
        if let Some(v) = obj.get(name) {
            if let Value::String(s) = v {
                if matches!(name, "$id" | "$schema" | "$ref") {
                    if let Err(e) = crate::uri::validate_uri_reference(s) {
                        return Err(CompileError::Schema(format!("Invalid URI reference '{}': {}", s, e)));
                    }
                }
            }
        }
    }
    // $defs must be compiled (so that invalid subschemas are reported)
    if let Some(Value::Object(defs)) = obj.get("$defs") {
        for (k, v) in defs {
            compile(v, &format!("{}/$defs/{}", pointer, escape(k)), uri, ctx).map_err(|e| e)?;
        }
    }
    if let Some(Value::Object(defs)) = obj.get("definitions") {
        for (k, v) in defs {
            compile(v, &format!("{}/definitions/{}", pointer, escape(k)), uri, ctx).map_err(|e| e)?;
        }
    }
    let mut compile_sub = |v: &Value, ptr: String| -> Result<Box<Node>, CompileError> {
        Ok(Box::new(compile(v, &ptr, uri, ctx)?))
    };
    // --- ordered keywords -------------------------------------------------
    if let Some(v) = obj.get("type") {
        let expected = match v {
            Value::String(s) => vec![s.clone()],
            Value::Array(a) => a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect(),
            _ => vec![],
        };
        let mut expected = expected;
        expected.sort();
        keywords.push(Keyword::Type(expected));
    }
    if let Some(v) = obj.get("const") {
        keywords.push(Keyword::Const(v.clone()));
    }
    if let Some(Value::Array(items)) = obj.get("enum") {
        keywords.push(Keyword::Enum(items.clone()));
    }
    for (name, exclusive) in [("minimum", false), ("maximum", false)] {
        if let Some(v) = obj.get(name) {
            keywords.push(if name == "minimum" {
                Keyword::Minimum { limit: v.clone(), exclusive }
            } else {
                Keyword::Maximum { limit: v.clone(), exclusive }
            });
        }
    }
    if let Some(v) = obj.get("exclusiveMinimum") {
        if let Some(b) = v.as_bool() {
            // draft 4 boolean form
            if let Some(m) = obj.get("minimum") {
                keywords.push(Keyword::Minimum { limit: m.clone(), exclusive: true });
            }
        } else if let Some(_) = v.as_number() {
            keywords.push(Keyword::Minimum { limit: v.clone(), exclusive: true });
        }
    }
    if let Some(v) = obj.get("exclusiveMaximum") {
        if let Some(b) = v.as_bool() {
            if let Some(m) = obj.get("maximum") {
                keywords.push(Keyword::Maximum { limit: m.clone(), exclusive: true });
            }
        } else if let Some(_) = v.as_number() {
            keywords.push(Keyword::Maximum { limit: v.clone(), exclusive: true });
        }
    }
    if let Some(v) = obj.get("multipleOf") {
        keywords.push(Keyword::MultipleOf(v.clone()));
    }
    if let Some(v) = obj.get("minLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinLength(n));
        }
    }
    if let Some(v) = obj.get("maxLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxLength(n));
        }
    }
    if let Some(Value::String(p)) = obj.get("pattern") {
        if let Ok(re) = Regex::new(p) {
            keywords.push(Keyword::Pattern { re, raw: p.clone() });
        }
    }
    if let Some(Value::String(f)) = obj.get("format") {
        keywords.push(Keyword::Format(f.clone()));
    }
    if let Some(Value::String(e)) = obj.get("contentEncoding") {
        keywords.push(Keyword::ContentEncoding(e.clone()));
    }
    if let Some(Value::String(m)) = obj.get("contentMediaType") {
        keywords.push(Keyword::ContentMediaType(m.clone()));
    }
    if let Some(v) = obj.get("minItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinItems(n));
        }
    }
    if let Some(v) = obj.get("maxItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxItems(n));
        }
    }
    if obj.get("uniqueItems").and_then(|v| v.as_bool()) == Some(true) {
        keywords.push(Keyword::UniqueItems);
    }
    // items / prefixItems / additionalItems
    let prefix = match obj.get("prefixItems") {
        Some(Value::Array(a)) => {
            let mut v = Vec::new();
            for (i, sub) in a.iter().enumerate() {
                v.push(*compile_sub(sub, format!("{}/prefixItems/{}", pointer, i))?);
            }
            v
        }
        _ => Vec::new(),
    };
    let items_kw = match obj.get("items") {
        Some(Value::Array(a)) if ctx.draft.supports_array_items() => {
            let mut v = Vec::new();
            for (i, sub) in a.iter().enumerate() {
                v.push(*compile_sub(sub, format!("{}/items/{}", pointer, i))?);
            }
            let extra = match obj.get("additionalItems") {
                Some(Value::Bool(false)) => None,
                Some(Value::Bool(true)) => None,
                Some(sub) => Some(*compile_sub(sub, format!("{}/additionalItems", pointer))?),
                None => None,
            };
            Some((v, extra, a.len()))
        }
        Some(sub) if !sub.is_array() => {
            let extra = None;
            let s = compile_sub(sub, format!("{}/items", pointer))?;
            Some((Vec::new(), extra, 0usize))
                .map(|_| (Vec::<Box<Node>>::new(), None, 0usize))
                .map(|(a, b, c)| (a, b, c, Some(s)))
        }
        _ => None,
    };
    if let Some((tuple, extra, tuple_len, single)) = match items_kw {
        Some((a, b, c, d)) => Some((a, b, c, d)),
        None => None,
    } {
        let _ = (tuple, extra, tuple_len, single);
    }
    Ok(Node { pointer: pointer.to_string(), uri: uri.to_string(), keywords, is_false: false })
}

pub fn escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}
