            for (i, sub) in a.iter().enumerate() {
                v.push(Box::new(compile(sub, &format!("{}items/{}", pointer, i), uri, ctx)?));
            }
            prefix_len = v.len();
            keywords.push(Keyword::ItemsTuple(v));
            if let Some(sub) = obj.get("additionalItems") {
                let single = if sub.is_boolean() {
                    if *sub == Value::Bool(true) { None } else { Some(Box::new(Node { pointer: format!("{}additionalItems", pointer), uri: uri_here.clone(), keywords: vec![], is_false: true })) }
                } else {
                    Some(Box::new(compile(sub, &format!("{}additionalItems", pointer), uri, ctx)?))
                };
                keywords.push(Keyword::AdditionalItems { single, rest_from: prefix_len });
            }
        }
        Some(sub) => {
            let fast = if let Value::Object(o) = sub {
                if o.len() == 1 {
                    o.get("type").and_then(|t| t.as_str()).map(|s| s.to_string())
                } else {
                    None
                }
            } else {
                None
            };
            let single = if sub.is_boolean() {
                if *sub == Value::Bool(true) {
                    None
                } else {
                    Some(Box::new(Node { pointer: format!("{}items", pointer), uri: uri_here.clone(), keywords: vec![], is_false: true }))
                }
            } else {
                Some(Box::new(compile(sub, &format!("{}items", pointer), uri, ctx)?))
            };
            keywords.push(Keyword::Items { single, rest_from: prefix_len, fast });
