//! JSON pointer helpers.

use serde_json::Value;

/// Resolve a JSON pointer (e.g. `/a/0`) inside a value.
pub fn get<'a>(root: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() {
        return Some(root);
    }
    if !pointer.starts_with('/') {
        return None;
    }
    let mut cur = root;
    for token in pointer[1..].split('/') {
        let token = token.replace("~1", "/").replace("~0", "~");
        match cur {
            Value::Object(map) => {
                cur = map.get(&token)?;
            }
            Value::Array(arr) => {
                if token.contains('/') || token.contains('~') {
                    return None;
                }
                let idx: usize = if token == "0" {
                    0
                } else if token.starts_with('0') {
                    return None;
                } else {
                    token.parse().ok()?
                };
                cur = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

/// Build a JSON pointer from a list of tokens.
pub fn build(tokens: &[String]) -> String {
    let mut out = String::new();
    for t in tokens {
        out.push('/');
        out.push_str(&t.replace('~', "~0").replace('/', "~1"));
    }
    out
}
