cd /workspace && cat > src/validate.rs <<'RSEOF'
//! Validation of compiled schema nodes.

use crate::jsonval::{to_string_compact, value_eq};
use crate::num::{number_is_integer, number_is_plain, Dec};
use crate::output::{ErrVal, Unit};
use crate::schema::*;
use serde_json::Value;

fn unit(path: String, inst: &str, loc: String, valid: bool) -> Unit {
    Unit {
        valid,
        eval_path: path,
        instance_path: inst.to_string(),
        schema_location: loc,
        errors: vec![],
        annotations: None,
        dropped: None,
        details: vec![],
    }
}

/// Validate a subschema node; returns the node's own unit plus its children.
fn validate_sub(
    node: &Node,
    instance: &Value,
    inst_path: &str,
    ctx: &mut Ctx,
) -> (Unit, Vec<String>, Vec<String>, Vec<usize>) {
    let res = validate_node(node, instance, inst_path, ctx);
    let mut u = unit(node.pointer.clone(), inst_path, format!("{}#{}", node.uri, node.pointer), res.valid);
    u.details = res.units;
    if !res.annotations.is_empty() {
        let mut m = serde_json::Map::new();
        for (k, v) in &res.annotations {
            m.insert(k.clone(), v.clone());
        }
        u.annotations = Some(Value::Object(m));
    }
    (u, res.text, res.props, res.items)
}

pub fn validate_node(node: &Node, instance: &Value, inst_path: &str, ctx: &mut Ctx) -> NodeRes {
    if node.is_false {
        let msg = format!("False schema does not allow {}", to_string_compact(instance));
        let mut u = unit(node.pointer.clone(), inst_path, format!("{}#{}", node.uri, node.pointer), false);
        u.errors.push(("falseSchema".to_string(), ErrVal::One(msg.clone())));
        return NodeRes {
            valid: false,
            units: vec![u],
            annotations: vec![],
            text: vec![msg],
            props: vec![],
            items: vec![],
        };
    }
    let mut units: Vec<Unit> = Vec::new();
    let mut annotations: Vec<(String, serde_json::Value)> = Vec::new();
    let mut text: Vec<String> = Vec::new();
    let mut valid = true;
    let mut props_all: Vec<String> = Vec::new();
    let mut items_all: Vec<usize> = Vec::new();
    let base = node.pointer.clone();
    for kw in &node.keywords {
        match kw {
            Keyword::Annotation { name, value } => annotations.push((name.clone(), value.clone())),
            other => {
                let r = validate_keyword(other, node, instance, inst_path, ctx);
                if !r.valid {
                    valid = false;
                }
                text.extend(r.text.iter().cloned());
                props_all.extend(r.props.iter().cloned());
                items_all.extend(r.items.iter().cloned());
                let suffix = keyword_path(other);
                if let Some(suffix) = suffix {
                    let mut u = unit(format!("{}{}", base, suffix), inst_path, format!("{}#{}{}", node.uri, base, suffix), r.valid);
                    u.errors = r.errors;
                    u.details = r.details;
                    if r.valid {
                        u.annotations = r.annotation;
                    } else {
                        u.dropped = r.annotation;
                    }
                    units.push(u);
                }
            }
        }
    }
    NodeRes { valid, units, annotations, text, props: props_all, items: items_all }
}

/// Returns `None` for keywords that do not create their own output unit.
fn keyword_path(kw: &Keyword) -> Option<String> {
    let name = match kw {
        Keyword::Type(_) => "type",
        Keyword::Const(_) => "const",
        Keyword::Enum(_) => "enum",
        Keyword::MultipleOf(_) => "multipleOf",
        Keyword::Maximum { .. } => "maximum",
        Keyword::Minimum { .. } => "minimum",
        Keyword::MaxLength(_) => "maxLength",
        Keyword::MinLength(_) => "minLength",
        Keyword::Pattern { .. } => "pattern",
        Keyword::MaxItems(_) => "maxItems",
        Keyword::MinItems(_) => "minItems",
        Keyword::UniqueItems => "uniqueItems",
        Keyword::ItemsTuple(_) => "items",
        Keyword::Items { .. } => "items",
        Keyword::PrefixItems(_) => "prefixItems",
        Keyword::AdditionalItems { .. } => "additionalItems",
        Keyword::Contains { .. } => "contains",
        Keyword::UnevaluatedItems(_) => "unevaluatedItems",
        Keyword::MinProperties(_) => "minProperties",
        Keyword::MaxProperties(_) => "maxProperties",
        Keyword::Required(_) => "required",
        Keyword::DependentRequired(_) => "dependentRequired",
        Keyword::Properties(_, _) => "properties",
        Keyword::PatternProperties(_, _) => "patternProperties",
        Keyword::AdditionalProperties { .. } => "additionalProperties",
        Keyword::PropertyNames(_) => "propertyNames",
        Keyword::Dependencies(_) => "dependencies",
        Keyword::DependentSchemas(_) => "dependentSchemas",
        Keyword::UnevaluatedProperties(_) => "unevaluatedProperties",
        Keyword::AllOf(_) => "allOf",
        Keyword::AnyOf(_) => "anyOf",
        Keyword::OneOf(_) => "oneOf",
        Keyword::Not(_) => "not",
        Keyword::IfThenElse { .. } => "if",
        Keyword::Ref(_) => "$ref",
        Keyword::Format(_) => "format",
        Keyword::Annotation { .. } => return None,
    };
    Some(format!("/{}", name))
}

fn plural(n: u64, one: &str, many: &str) -> &'static str {
    if n == 1 {
        "1"
    } else {
        "2"
    }
}

fn kw_name(kw: &Keyword) -> &'static str {
    keyword_path(kw).map(|p| p.trim_start_matches('/').to_string()).unwrap_or_default().leak().as_str()
}

fn validate_keyword(kw: &Keyword, node: &Node, instance: &Value, inst_path: &str, ctx: &mut Ctx) -> KwRes {
    let _ = (kw_name, plural);
    match kw {
        Keyword::Type(expected) => {
            let actual = crate::jsonval::type_name(instance, !ctx.draft.strict_integer());
            if expected.iter().any(|t| type_matches(instance, t, ctx)) {
                KwRes::ok()
            } else {
                let inst = to_string_compact(instance);
                if expected.len() == 1 {
                    KwRes::one("type", format!("{} is not of type \"{}\"", inst, expected[0]))
                } else {
                    let list_text = expected.iter().map(|t| format!("\"{}\"", t)).collect::<Vec<_>>().join(", ");
                    let list_basic = expected.join(", ");
                    KwRes {
                        valid: false,
                        errors: vec![("type".to_string(), ErrVal::One(format!("{} is not of types ({})", inst, list_basic)))],
                        annotation: None,
                        details: vec![],
                        text: vec![format!("{} is not of types {}", inst, list_text)],
                        props: vec![],
                        items: vec![],
                    }
                }
            }
        }
        Keyword::Const(expected) => {
            if value_eq(instance, expected) {
                KwRes::ok()
            } else {
                KwRes::one("const", format!("{} was expected", to_string_compact(expected)))
            }
        }
        Keyword::Enum(values) => {
            if values.iter().any(|v| value_eq(instance, v)) {
                KwRes::ok()
            } else {
                let inst = to_string_compact(instance);
                let list = if values.len() == 1 {
                    to_string_compact(&values[0])
                } else if values.len() == 2 {
                    format!("{} or {}", to_string_compact(&values[0]), to_string_compact(&values[1]))
                } else if values.len() == 3 {
                    format!("{}, {} or {}", to_string_compact(&values[0]), to_string_compact(&values[1]), to_string_compact(&values[2]))
                } else {
                    format!(
                        "{}, {} or {} other candidates",
                        to_string_compact(&values[0]),
                        to_string_compact(&values[1]),
                        values.len() - 2
                    )
                };
                KwRes::one("enum", format!("{} is not one of {}", inst, list))
            }
        }
        Keyword::MultipleOf(m) => {
            if !instance.is_number() {
                return KwRes::ok();
            }
            if is_multiple(instance, m) {
                KwRes::ok()
            } else {
                KwRes::one("multipleOf", format!("{} is not a multiple of {}", to_string_compact(instance), to_string_compact(m)))
            }
        }
        Keyword::Maximum { limit, exclusive } => {
            if !instance.is_number() {
                return KwRes::ok();
            }
            let a = Dec::parse(&num_str(instance));
            let b = Dec::parse(&num_str(limit));
            let ok = if *exclusive { a.cmp(&b) == std::cmp::Ordering::Less } else { a.cmp(&b) != std::cmp::Ordering::Greater };
            if ok {
                KwRes::ok()
            } else if *exclusive {
                KwRes::one("exclusiveMaximum", format!("{} is greater than or equal to the maximum of {}", to_string_compact(instance), to_string_compact(limit)))
            } else {
                KwRes::one("maximum", format!("{} is greater than the maximum of {}", to_string_compact(instance), to_string_compact(limit)))
            }
        }
        Keyword::Minimum { limit, exclusive } => {
            if !instance.is_number() {
                return KwRes::ok();
            }
            let a = Dec::parse(&num_str(instance));
            let b = Dec::parse(&num_str(limit));
            let ok = if *exclusive { a.cmp(&b) == std::cmp::Ordering::Greater } else { a.cmp(&b) != std::cmp::Ordering::Less };
            if ok {
                KwRes::ok()
            } else if *exclusive {
                KwRes::one("exclusiveMinimum", format!("{} is less than or equal to the minimum of {}", to_string_compact(instance), to_string_compact(limit)))
            } else {
                KwRes::one("minimum", format!("{} is less than the minimum of {}", to_string_compact(instance), to_string_compact(limit)))
            }
        }
        Keyword::MaxLength(n) => match instance.as_str() {
            Some(s) => {
                let len = s.chars().count() as u64;
                if len <= *n {
                    KwRes::ok()
                } else {
                    KwRes::one("maxLength", format!("{} is longer than {} character{}", to_string_compact(instance), n, if *n == 1 { "" } else { "s" }))
                }
            }
            None => KwRes::ok(),
        },
        Keyword::MinLength(n) => match instance.as_str() {
            Some(s) => {
                let len = s.chars().count() as u64;
                if len >= *n {
                    KwRes::ok()
                } else {
                    KwRes::one("minLength", format!("{} is shorter than {} character{}", to_string_compact(instance), n, if *n == 1 { "" } else { "s" }))
                }
            }
            None => KwRes::ok(),
        },
        Keyword::Pattern { re, raw } => match instance.as_str() {
            Some(s) => {
                if re.is_match(s) {
                    KwRes::ok()
                } else {
                    KwRes::one("pattern", format!("{} does not match \"{}\"", to_string_compact(instance), raw))
                }
            }
            None => KwRes::ok(),
        },
        Keyword::Format(f) => {
            if !ctx.assert_format {
                return KwRes::ok();
            }
            match instance.as_str() {
                Some(s) => match crate::formats::check(f, s) {
                    Some(true) | None => KwRes::ok(),
                    Some(false) => KwRes::one("format", format!("{} is not a \"{}\"", to_string_compact(instance), f)),
                },
                None => KwRes::ok(),
            }
        }
        Keyword::MaxItems(n) => match instance.as_array() {
            Some(a) => {
                if (a.len() as u64) <= *n {
                    KwRes::ok()
                } else {
                    KwRes::one("maxItems", format!("{} has more than {} item{}", to_string_compact(instance), n, if *n == 1 { "" } else { "s" }))
                }
            }
            None => KwRes::ok(),
        },
        Keyword::MinItems(n) => match instance.as_array() {
            Some(a) => {
                if (a.len() as u64) >= *n {
                    KwRes::ok()
                } else {
                    KwRes::one("minItems", format!("{} has less than {} item{}", to_string_compact(instance), n, if *n == 1 { "" } else { "s" }))
                }
            }
            None => KwRes::ok(),
        },
        Keyword::UniqueItems => match instance.as_array() {
            Some(a) => {
                for i in 0..a.len() {
                    for j in i + 1..a.len() {
                        if value_eq(&a[i], &a[j]) {
                            return KwRes::one("uniqueItems", format!("{} has non-unique elements", to_string_compact(instance)));
                        }
                    }
                }
                KwRes::ok()
            }
            None => KwRes::ok(),
        },
        Keyword::ItemsTuple(subs) => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            for (i, sub) in subs.iter().enumerate() {
                if i >= arr.len() {
                    break;
                }
                let ip = format!("{}/{}", inst_path, i);
                let (u, t, _, it) = validate_sub(sub, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            KwRes {
                valid,
                errors: vec![],
                annotation: if arr.is_empty() { None } else { Some(serde_json::Value::Bool(true)) },
                details,
                text,
                props: vec![],
                items: items_eval,
            }
        }
        Keyword::PrefixItems(subs) => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            let mut count = 0usize;
            for (i, sub) in subs.iter().enumerate() {
                if i >= arr.len() {
                    break;
                }
                let ip = format!("{}/{}", inst_path, i);
                let (u, t, _, it) = validate_sub(sub, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                } else {
                    count += 1;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            let annotation = if count == 0 {
                None
            } else if arr.len() <= subs.len() {
                Some(serde_json::Value::Bool(true))
            } else {
                Some(serde_json::Value::Number(serde_json::Number::from(subs.len().saturating_sub(1))))
            };
            KwRes { valid, errors: vec![], annotation, details, text, props: vec![], items: items_eval }
        }
        Keyword::Items { single, rest_from, fast } => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let single = match single {
                Some(s) => s,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            let mut validated_any = false;
            let mut errors: Vec<String> = Vec::new();
            for i in *rest_from..arr.len() {
                let ip = format!("{}/{}", inst_path, i);
                if let Some(t) = fast {
                    // fast path: only the `type` keyword is checked
                    let ok = type_matches(&arr[i], t, ctx);
                    if ok {
                        validated_any = true;
                        items_eval.push(i);
                    } else {
                        valid = false;
                        text.push(format!("{} is not of type \"{}\"", to_string_compact(&arr[i]), t));
                        errors.push(format!("{} at index {} is not of type \"{}\"", to_string_compact(&arr[i]), i, t));
                    }
                    continue;
                }
                let (u, t, _, it) = validate_sub(single, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                } else {
                    validated_any = true;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            if !errors.is_empty() {
                let ev = if errors.len() == 1 { ErrVal::One(errors[0].clone()) } else { ErrVal::Many(errors) };
                return KwRes {
                    valid,
                    errors: vec![("type".to_string(), ev)],
                    annotation: Some(serde_json::Value::Bool(validated_any)),
                    details: vec![],
                    text,
                    props: vec![],
                    items: items_eval,
                };
            }
            KwRes {
                valid,
                errors: vec![],
                annotation: Some(serde_json::Value::Bool(validated_any)),
                details,
                text,
                props: vec![],
                items: items_eval,
            }
        }
        Keyword::AdditionalItems { single, rest_from } => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let single = match single {
                Some(s) => s,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            let mut unexpected = Vec::new();
            for i in *rest_from..arr.len() {
                let ip = format!("{}/{}", inst_path, i);
                unexpected.push(arr[i].clone());
                let (u, t, _, it) = validate_sub(single, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            if valid {
                KwRes { valid, errors: vec![], annotation: None, details, text, props: vec![], items: items_eval }
            } else {
                let names: Vec<String> = unexpected.iter().map(|v| to_string_compact(v)).collect();
                let msg = format!("Additional items are not allowed ({} were unexpected)", names.join(", "));
                KwRes { valid: false, errors: vec![("additionalItems".to_string(), ErrVal::One(msg.clone()))], annotation: None, details, text: vec![msg], props: vec![], items: items_eval }
            }
        }
        Keyword::Contains { schema, min, max } => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut matches: Vec<usize> = Vec::new();
            for (i, item) in arr.iter().enumerate() {
                let ip = format!("{}/{}", inst_path, i);
                let (u, t, _, _) = validate_sub(schema, item, &ip, ctx);
                if u.valid {
                    matches.push(i);
                    details.push(u);
                }
            }
            let min = min.unwrap_or(1);
            let ok = matches.len() as u64 >= min && max.map(|m| matches.len() as u64 <= m).unwrap_or(true);
