                        text.push(format!("{} is not of type \"{}\"", to_string_compact(&arr[i]), t));
                        errors.push(format!("{} at index {} is not of type \"{}\"", to_string_compact(&arr[i]), i, t));
                    }
                    continue;
                }
                let (u, t, _, it) = validate_sub(single, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                } else {
                    validated_any = true;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            if !errors.is_empty() {
                let ev = if errors.len() == 1 { ErrVal::One(errors[0].clone()) } else { ErrVal::Many(errors) };
                return KwRes {
                    valid,
                    errors: vec![("type".to_string(), ev)],
                    annotation: Some(serde_json::Value::Bool(validated_any)),
                    details: vec![],
                    text,
                    props: vec![],
                    items: items_eval,
                };
            }
            KwRes {
                valid,
                errors: vec![],
                annotation: Some(serde_json::Value::Bool(validated_any)),
                details,
                text,
                props: vec![],
                items: items_eval,
            }
        }
        Keyword::AdditionalItems { single, rest_from } => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let single = match single {
                Some(s) => s,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            let mut unexpected = Vec::new();
            for i in *rest_from..arr.len() {
