                    details,
                    text,
                    props: vec![],
                    items: matches,
                }
            } else {
                let msg = format!("None of {} are valid under the given schema", to_string_compact(instance));
                KwRes { valid: false, errors: vec![("contains".to_string(), ErrVal::One(msg.clone()))], annotation: None, details, text: vec![msg], props: vec![], items: matches }
            }
