                }
            }
            None => KwRes::ok(),
        },
        Keyword::MaxProperties(n) => match instance.as_object() {
            Some(o) => {
                if (o.len() as u64) <= *n {
                    KwRes::ok()
                } else {
                    KwRes::one("maxProperties", format!("{} has more than {} propert{}", to_string_compact(instance), n, if *n == 1 { "y" } else { "ies" }))
                }
            }
            None => KwRes::ok(),
        },
        Keyword::Required(names) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let missing: Vec<String> = names.iter().filter(|n| !obj.contains_key(*n)).cloned().collect();
            if missing.is_empty() {
                KwRes::ok()
            } else {
                let msgs: Vec<String> = missing.iter().map(|n| format!("\"{}\" is a required property", n)).collect();
                let ev = if msgs.len() == 1 { ErrVal::One(msgs[0].clone()) } else { ErrVal::Many(msgs.clone()) };
                KwRes { valid: false, errors: vec![("required".to_string(), ev)], annotation: None, details: vec![], text: msgs, props: vec![], items: vec![] }
            }
        }
        Keyword::DependentRequired(pairs) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let mut msgs = Vec::new();
            for (key, deps) in pairs {
                if obj.contains_key(key) {
                    for d in deps {
                        if !obj.contains_key(d) {
                            msgs.push(format!("\"{}\" is a required property", d));
                        }
                    }
                }
            }
            if msgs.is_empty() {
                KwRes::ok()
            } else {
                let ev = if msgs.len() == 1 { ErrVal::One(msgs[0].clone()) } else { ErrVal::Many(msgs.clone()) };
                KwRes { valid: false, errors: vec![("dependentRequired".to_string(), ev)], annotation: None, details: vec![], text: msgs, props: vec![], items: vec![] }
            }
        }
        Keyword::Properties(props, drop_unit) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes { valid: true, errors: vec![], annotation: None, details: vec![], text: vec![], props: vec![], items: vec![] },
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut names = Vec::new();
            for (name, sub) in props {
                if let Some(v) = obj.get(name) {
                    names.push(name.clone());
                    let ip = format!("{}/{}", inst_path, escape(name));
                    let (u, t, p, _) = validate_sub(sub, v, &ip, ctx);
                    if !u.valid {
                        valid = false;
                    }
                    details.push(u);
                    text.extend(t);
                    props_all_extend(&mut KwRes::ok(), p);
                }
            }
            let _ = names;
            KwRes::ok()
        }
        _ => KwRes::ok(),
    }
}

fn props_all_extend(_r: &mut KwRes, _p: Vec<String>) {}

fn num_str(v: &serde_json::Value) -> String {
    to_string_compact(v)
}

fn type_matches(instance: &Value, t: &str, ctx: &Ctx) -> bool {
    match t {
        "null" => instance.is_null(),
        "boolean" => instance.is_boolean(),
        "string" => instance.is_string(),
        "array" => instance.is_array(),
        "object" => instance.is_object(),
        "number" => instance.is_number(),
        "integer" => instance.is_number() && {
            if ctx.draft.strict_integer() {
                let s = to_string_compact(instance);
                !s.contains('.') && crate::num::Dec::parse(&s).is_integer()
            } else {
                crate::num::Dec::parse(&to_string_compact(instance)).is_integer()
            }
        },
        _ => false,
    }
}

fn is_multiple(instance: &Value, multiple: &Value) -> bool {
    let (ia, ma) = (instance.as_number(), multiple.as_number());
    let (ia, ma) = match (ia, ma) {
        (Some(a), Some(b)) => (a, b),
        _ => return false,
    };
    let si = ia.to_string();
    let sm = ma.to_string();
    let plain = |s: &str| !s.contains('.') && !s.contains('e') && !s.contains('E');
    let as_i64 = |s: &str| -> Option<i64> {
        if plain(s) {
            s.parse::<i64>().ok()
        } else {
            None
        }
    };
    let as_u64 = |s: &str| -> Option<u64> {
        if plain(s) {
            s.parse::<u64>().ok()
        } else {
            None
        }
    };
    if let (Some(a), Some(b)) = (as_i64(&si), as_i64(&sm)) {
        return b != 0 && a % b == 0;
    }
    if let (Some(a), Some(b)) = (as_u64(&si), as_u64(&sm)) {
        return b != 0 && a % b == 0;
    }
    let da = Dec::parse(&si);
    let db = Dec::parse(&sm);
    if !plain(&sm) {
        return da.divisible_by(&db);
    }
    if !plain(&si) {
        if db.cmp(&Dec::parse("9007199254740992")) == std::cmp::Ordering::Greater
            || db.cmp(&Dec::parse("-9007199254740992")) == std::cmp::Ordering::Less
        {
            return da.divisible_by(&db);
        }
        return (da.to_f64() % db.to_f64()) == 0.0;
    }
    da.divisible_by(&db)
}
