//! Validation of compiled schema nodes.

use crate::jsonval::{to_string_compact, value_eq};
use crate::num::Dec;
use crate::output::{ErrVal, Unit};
use crate::schema::*;
use serde_json::{Map, Value};

fn unit(path: String, inst: &str, loc: String, valid: bool) -> Unit {
    Unit {
        valid,
        eval_path: path,
        instance_path: inst.to_string(),
        schema_location: loc,
        errors: vec![],
        annotations: None,
        dropped: None,
        details: vec![],
    }
}

type SubOut = (Unit, Vec<String>, Vec<String>, Vec<usize>);

fn validate_sub(node: &Node, instance: &Value, inst_path: &str, ctx: &mut Ctx) -> SubOut {
    let res = validate_node(node, instance, inst_path, ctx);
    let mut u = unit(node.pointer.clone(), inst_path, format!("{}#{}", node.uri, node.pointer), res.valid);
    u.details = res.units;
    if !res.annotations.is_empty() {
        let mut m = Map::new();
        for (k, v) in &res.annotations {
            m.insert(k.clone(), v.clone());
        }
        u.annotations = Some(Value::Object(m));
    }
    (u, res.text, res.props, res.items)
}

pub fn validate_node(node: &Node, instance: &Value, inst_path: &str, ctx: &mut Ctx) -> NodeRes {
    if node.is_false {
        let msg = format!("False schema does not allow {}", to_string_compact(instance));
        let mut u = unit(node.pointer.clone(), inst_path, format!("{}#{}", node.uri, node.pointer), false);
        u.errors.push(("falseSchema".to_string(), ErrVal::One(msg.clone())));
        return NodeRes { valid: false, units: vec![u], annotations: vec![], text: vec![msg], props: vec![], items: vec![] };
    }
    let mut units: Vec<Unit> = Vec::new();
    let mut annotations: Vec<(String, Value)> = Vec::new();
    let mut text: Vec<String> = Vec::new();
    let mut valid = true;
    let mut props_all: Vec<String> = Vec::new();
    let mut items_all: Vec<usize> = Vec::new();
    let base = node.pointer.clone();
    for kw in &node.keywords {
        match kw {
            Keyword::Annotation { name, value } => annotations.push((name.clone(), value.clone())),
            other => {
                let r = validate_keyword(other, node, instance, inst_path, ctx, &props_all, &items_all);
                if !r.valid {
                    valid = false;
                }
                text.extend(r.text.iter().cloned());
                props_all.extend(r.props.iter().cloned());
                items_all.extend(r.items.iter().cloned());
                if let Some(suffix) = keyword_suffix(other) {
                    let mut u = unit(
                        format!("{}{}", base, suffix),
                        inst_path,
                        format!("{}#{}{}", node.uri, base, suffix),
                        r.valid,
                    );
                    u.errors = r.errors;
                    u.details = r.details;
                    if r.valid {
                        u.annotations = r.annotation;
                    } else {
                        u.dropped = r.annotation;
                    }
                    units.push(u);
                }
            }
        }
    }
    // the `required`/`properties` quirk: with exactly two required properties the
    // check is folded into the `properties` unit
    if let (Some(req), Some(pi)) = (find_required(node), find_properties(node)) {
        if req.len() == 2 {
            if let Some(obj) = instance.as_object() {
                let missing: Vec<String> = req.iter().filter(|n| !obj.contains_key(*n)).cloned().collect();
                if !missing.is_empty() {
                    valid = false;
                    for m in &missing {
                        text.push(format!("\"{}\" is a required property", m));
                    }
                    if let Some(u) = units.iter_mut().find(|u| u.eval_path == format!("{}{}", base, "/properties")) {
                        u.valid = false;
                        u.annotations = None;
                        u.dropped = None;
                    }
                }
            }
        }
        let _ = pi;
    }
    NodeRes { valid, units, annotations, text, props: props_all, items: items_all }
}

fn find_required(node: &Node) -> Option<&Vec<String>> {
    node.keywords.iter().find_map(|k| match k {
        Keyword::Required(v) => Some(v),
        _ => None,
    })
}
fn find_properties(node: &Node) -> Option<()> {
    node.keywords.iter().find_map(|k| match k {
        Keyword::Properties(_, _) => Some(()),
        _ => None,
    })
}

/// Suffix (including the leading slash) appended to the node pointer for the
/// keyword's own output unit.  `None` when the keyword produces no unit.
fn keyword_suffix(kw: &Keyword) -> Option<&'static str> {
    Some(match kw {
        Keyword::Type(_) => "/type",
        Keyword::Const(_) => "/const",
        Keyword::Enum(_) => "/enum",
        Keyword::MultipleOf(_) => "/multipleOf",
        Keyword::Maximum { .. } => "/maximum",
        Keyword::Minimum { .. } => "/minimum",
        Keyword::MaxLength(_) => "/maxLength",
        Keyword::MinLength(_) => "/minLength",
        Keyword::Pattern { .. } => "/pattern",
        Keyword::MaxItems(_) => "/maxItems",
        Keyword::MinItems(_) => "/minItems",
        Keyword::UniqueItems => "/uniqueItems",
        Keyword::ItemsTuple(_) => "/items",
        Keyword::Items { .. } => "/items",
        Keyword::PrefixItems(_) => "/prefixItems",
        Keyword::AdditionalItems { .. } => "/additionalItems",
        Keyword::Contains { .. } => "/contains",
        Keyword::UnevaluatedItems(_) => "/unevaluatedItems",
        Keyword::MinProperties(_) => "/minProperties",
        Keyword::MaxProperties(_) => "/maxProperties",
        Keyword::Required(_) => "/required",
        Keyword::DependentRequired(_) => "/dependentRequired",
        Keyword::Properties(_, drop) => {
            if *drop {
                return None;
            } else {
                "/properties"
            }
        }
        Keyword::PatternProperties(_, _) => "/patternProperties",
        Keyword::AdditionalProperties { .. } => "/additionalProperties",
        Keyword::PropertyNames(_) => "/propertyNames",
        Keyword::Dependencies(_) => "/dependencies",
        Keyword::DependentSchemas(_) => "/dependentSchemas",
        Keyword::UnevaluatedProperties(_) => "/unevaluatedProperties",
        Keyword::AllOf(_) => "/allOf",
        Keyword::AnyOf(_) => "/anyOf",
        Keyword::OneOf(_) => "/oneOf",
        Keyword::Not(_) => "/not",
        Keyword::IfThenElse { .. } => "/if",
        Keyword::Ref(_) => "/$ref",
        Keyword::Format(_) => "/format",
        Keyword::Annotation { .. } => return None,
    })
}

fn keyword_name(kw: &Keyword) -> &'static str {
    match keyword_suffix(kw) {
        Some(s) => s.trim_start_matches('/'),
        None => "",
    }
}

fn plural_unit(n: u64, one: &str, many: &str) -> String {
    if n == 1 {
        one.to_string()
    } else {
        many.to_string()
    }
}

fn many_or_one(msgs: Vec<String>) -> ErrVal {
    if msgs.len() == 1 {
        ErrVal::One(msgs[0].clone())
    } else {
        ErrVal::Many(msgs.clone())
    }
}

fn validate_keyword(
    kw: &Keyword,
    node: &Node,
    instance: &Value,
    inst_path: &str,
    ctx: &mut Ctx,
    evaluated_props: &[String],
    evaluated_items: &[usize],
) -> KwRes {
    match kw {
        Keyword::Type(expected) => {
            if expected.iter().any(|t| type_matches(instance, t, ctx)) {
                KwRes::ok()
            } else {
                let inst = to_string_compact(instance);
                if expected.len() == 1 {
                    KwRes::one("type", format!("{} is not of type \"{}\"", inst, expected[0]))
                } else {
                    let text = expected.iter().map(|t| format!("\"{}\"", t)).collect::<Vec<_>>().join(", ");
                    let mut basic = expected.clone();
                    basic.sort();
                    let basic_list = basic.join(", ");
                    KwRes {
                        valid: false,
                        errors: vec![("type".to_string(), ErrVal::One(format!("{} is not of types ({})", inst, basic_list)))],
                        annotation: None,
                        details: vec![],
                        text: vec![format!("{} is not of types {}", inst, text)],
                        props: vec![],
                        items: vec![],
                    }
                }
            }
        }
        Keyword::Const(expected) => {
            if value_eq(instance, expected) {
                KwRes::ok()
            } else {
                KwRes::one("const", format!("{} was expected", to_string_compact(expected)))
            }
        }
        Keyword::Enum(values) => {
            if values.iter().any(|v| value_eq(instance, v)) {
                KwRes::ok()
            } else {
                let inst = to_string_compact(instance);
                let list = match values.len() {
                    1 => to_string_compact(&values[0]),
                    2 => format!("{} or {}", to_string_compact(&values[0]), to_string_compact(&values[1])),
                    3 => format!(
                        "{}, {} or {}",
                        to_string_compact(&values[0]),
                        to_string_compact(&values[1]),
                        to_string_compact(&values[2])
                    ),
                    _ => format!(
                        "{}, {} or {} other candidates",
                        to_string_compact(&values[0]),
                        to_string_compact(&values[1]),
                        values.len() - 2
                    ),
                };
                KwRes::one("enum", format!("{} is not one of {}", inst, list))
            }
        }
        Keyword::MultipleOf(m) => {
            if !instance.is_number() {
                return KwRes::ok();
            }
            if is_multiple(instance, m) {
                KwRes::ok()
            } else {
                KwRes::one(
                    "multipleOf",
                    format!("{} is not a multiple of {}", to_string_compact(instance), to_string_compact(m)),
                )
            }
        }
        Keyword::Maximum { limit, exclusive } => {
            if !instance.is_number() {
                return KwRes::ok();
            }
            let a = Dec::parse(&to_string_compact(instance));
            let b = Dec::parse(&to_string_compact(limit));
            let ok = if *exclusive {
                a.cmp(&b) == std::cmp::Ordering::Less
            } else {
                a.cmp(&b) != std::cmp::Ordering::Greater
            };
            if ok {
                KwRes::ok()
            } else if *exclusive {
                KwRes::one(
                    "exclusiveMaximum",
                    format!("{} is greater than or equal to the maximum of {}", to_string_compact(instance), to_string_compact(limit)),
                )
            } else {
                KwRes::one(
                    "maximum",
                    format!("{} is greater than the maximum of {}", to_string_compact(instance), to_string_compact(limit)),
                )
            }
        }
        Keyword::Minimum { limit, exclusive } => {
            if !instance.is_number() {
                return KwRes::ok();
            }
            let a = Dec::parse(&to_string_compact(instance));
            let b = Dec::parse(&to_string_compact(limit));
            let ok = if *exclusive {
                a.cmp(&b) == std::cmp::Ordering::Greater
            } else {
                a.cmp(&b) != std::cmp::Ordering::Less
            };
            if ok {
                KwRes::ok()
            } else if *exclusive {
                KwRes::one(
                    "exclusiveMinimum",
                    format!("{} is less than or equal to the minimum of {}", to_string_compact(instance), to_string_compact(limit)),
                )
            } else {
                KwRes::one(
                    "minimum",
                    format!("{} is less than the minimum of {}", to_string_compact(instance), to_string_compact(limit)),
                )
            }
        }
        Keyword::MaxLength(n) => match instance.as_str() {
            Some(s) => {
                let len = s.chars().count() as u64;
                if len <= *n {
                    KwRes::ok()
                } else {
                    KwRes::one(
                        "maxLength",
                        format!(
                            "{} is longer than {} character{}",
                            to_string_compact(instance),
                            n,
                            plural_unit(*n, "", "s")
                        ),
                    )
                }
            }
            None => KwRes::ok(),
        },
        Keyword::MinLength(n) => match instance.as_str() {
            Some(s) => {
                let len = s.chars().count() as u64;
                if len >= *n {
                    KwRes::ok()
                } else {
                    KwRes::one(
                        "minLength",
                        format!(
                            "{} is shorter than {} character{}",
                            to_string_compact(instance),
                            n,
                            plural_unit(*n, "", "s")
                        ),
                    )
                }
            }
            None => KwRes::ok(),
        },
        Keyword::Pattern { re, raw } => match instance.as_str() {
            Some(s) => {
                if re.is_match(s) {
                    KwRes::ok()
                } else {
                    KwRes::one("pattern", format!("{} does not match \"{}\"", to_string_compact(instance), raw))
                }
            }
            None => KwRes::ok(),
        },
        Keyword::Format(f) => {
            if !ctx.assert_format {
                return KwRes::ok();
            }
            match instance.as_str() {
                Some(s) => match crate::formats::check(f, s) {
                    Some(true) | None => KwRes::ok(),
                    Some(false) => KwRes::one("format", format!("{} is not a \"{}\"", to_string_compact(instance), f)),
                },
                None => KwRes::ok(),
            }
        }
        Keyword::MaxItems(n) => match instance.as_array() {
            Some(a) => {
                if (a.len() as u64) <= *n {
                    KwRes::ok()
                } else {
                    KwRes::one(
                        "maxItems",
                        format!("{} has more than {} item{}", to_string_compact(instance), n, plural_unit(*n, "", "s")),
                    )
                }
            }
            None => KwRes::ok(),
        },
        Keyword::MinItems(n) => match instance.as_array() {
            Some(a) => {
                if (a.len() as u64) >= *n {
                    KwRes::ok()
                } else {
                    KwRes::one(
                        "minItems",
                        format!("{} has less than {} item{}", to_string_compact(instance), n, plural_unit(*n, "", "s")),
                    )
                }
            }
            None => KwRes::ok(),
        },
        Keyword::UniqueItems => match instance.as_array() {
            Some(a) => {
                for i in 0..a.len() {
                    for j in i + 1..a.len() {
                        if value_eq(&a[i], &a[j]) {
                            return KwRes::one("uniqueItems", format!("{} has non-unique elements", to_string_compact(instance)));
                        }
                    }
                }
                KwRes::ok()
            }
            None => KwRes::ok(),
        },
        Keyword::ItemsTuple(subs) => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            for (i, sub) in subs.iter().enumerate() {
                if i >= arr.len() {
                    break;
                }
                let ip = format!("{}/{}", inst_path, i);
                let (u, t, _, it) = validate_sub(sub, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            KwRes {
                valid,
                errors: vec![],
                annotation: if arr.is_empty() { None } else { Some(Value::Bool(true)) },
                details,
                text,
                props: vec![],
                items: items_eval,
            }
        }
        Keyword::PrefixItems(subs) => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            let mut count = 0usize;
            for (i, sub) in subs.iter().enumerate() {
                if i >= arr.len() {
                    break;
                }
                let ip = format!("{}/{}", inst_path, i);
                let (u, t, _, it) = validate_sub(sub, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                } else {
                    count += 1;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            let annotation = if count == 0 {
                None
            } else if arr.len() <= subs.len() {
                Some(Value::Bool(true))
            } else {
                Some(Value::Number(crate::serde_json::Number::from(subs.len().saturating_sub(1))))
            };
            KwRes { valid, errors: vec![], annotation, details, text, props: vec![], items: items_eval }
        }
        Keyword::Items { single, rest_from, fast } => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let single = match single {
                Some(s) => s,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            let mut validated_any = false;
            let mut errs: Vec<String> = Vec::new();
            for i in *rest_from..arr.len() {
                let ip = format!("{}/{}", inst_path, i);
                if let Some(t) = fast {
                    if type_matches(&arr[i], t, ctx) {
                        validated_any = true;
                        items_eval.push(i);
                    } else {
                        valid = false;
                        text.push(format!("{} is not of type \"{}\"", to_string_compact(&arr[i]), t));
                        errs.push(format!("{} at index {} is not of type \"{}\"", to_string_compact(&arr[i]), i, t));
                    }
                    continue;
                }
                let (u, t, _, it) = validate_sub(single, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                } else {
                    validated_any = true;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            let annotation = Some(Value::Bool(validated_any));
            if !errs.is_empty() {
                return KwRes {
                    valid,
                    errors: vec![("type".to_string(), many_or_one(errs))],
                    annotation,
                    details: vec![],
                    text,
                    props: vec![],
                    items: items_eval,
                };
            }
            KwRes { valid, errors: vec![], annotation, details, text, props: vec![], items: items_eval }
        }
        Keyword::AdditionalItems { single, rest_from } => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let single = match single {
                Some(s) => s,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut items_eval = Vec::new();
            let mut unexpected = Vec::new();
            for i in *rest_from..arr.len() {
                let ip = format!("{}/{}", inst_path, i);
                unexpected.push(arr[i].clone());
                let (u, t, _, it) = validate_sub(single, &arr[i], &ip, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
                items_eval.extend(it);
                items_eval.push(i);
            }
            if valid {
                KwRes { valid, errors: vec![], annotation: None, details, text, props: vec![], items: items_eval }
            } else {
                let names: Vec<String> = unexpected.iter().map(|v| to_string_compact(v)).collect();
                let msg = format!("Additional items are not allowed ({} were unexpected)", names.join(", "));
                KwRes {
                    valid: false,
                    errors: vec![("additionalItems".to_string(), ErrVal::One(msg.clone()))],
                    annotation: None,
                    details,
                    text: vec![msg],
                    props: vec![],
                    items: items_eval,
                }
            }
        }
        Keyword::Contains { schema, min, max } => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut matches: Vec<usize> = Vec::new();
            for (i, item) in arr.iter().enumerate() {
                let ip = format!("{}/{}", inst_path, i);
                let (u, t, _, _) = validate_sub(schema, item, &ip, ctx);
                if u.valid {
                    matches.push(i);
                    details.push(u);
                }
            }
            let min = min.unwrap_or(1);
            let ok = matches.len() as u64 >= min && max.map(|m| (matches.len() as u64) <= m).unwrap_or(true);
            if ok {
                KwRes {
                    valid: true,
                    errors: vec![],
                    annotation: if matches.is_empty() {
                        None
                    } else {
                        Some(Value::Array(matches.iter().map(|i| Value::from(*i as u64)).collect()))
                    },
                    details,
                    text,
                    props: vec![],
                    items: matches,
                }
            } else {
                let msg = format!("None of {} are valid under the given schema", to_string_compact(instance));
                KwRes {
                    valid: false,
                    errors: vec![("contains".to_string(), ErrVal::One(msg.clone()))],
                    annotation: None,
                    details,
                    text: vec![msg],
                    props: vec![],
                    items: matches,
                }
            }
        }
        Keyword::UnevaluatedItems(_) => {
            let arr = match instance.as_array() {
                Some(a) => a,
                None => return KwRes::ok(),
            };
            let unevaluated: Vec<usize> = (0..arr.len()).filter(|i| !evaluated_items.contains(i)).collect();
            if unevaluated.is_empty() {
                return KwRes::ok();
            }
            let values: Vec<Value> = unevaluated.iter().map(|i| arr[*i].clone()).collect();
            let names: Vec<String> = values.iter().map(|v| to_string_compact(v)).collect();
            let msg = format!("Unevaluated items are not allowed ('{}' were unexpected)", names.join("', '"));
            let mut details = Vec::new();
            for i in &unevaluated {
                let ip = format!("{}/{}", inst_path, i);
                let false_node = Node { pointer: format!("{}unevaluatedItems", node.pointer), uri: node.uri.clone(), keywords: vec![], is_false: true };
                let (u, _, _, _) = validate_sub(&false_node, &arr[*i], &ip, ctx);
                details.push(u);
            }
            KwRes {
                valid: false,
                errors: vec![("unevaluatedItems".to_string(), ErrVal::One(msg.clone()))],
                annotation: None,
                details,
                text: vec![msg],
                props: vec![],
                items: unevaluated,
            }
        }
        Keyword::MinProperties(n) => match instance.as_object() {
            Some(o) => {
                if (o.len() as u64) >= *n {
                    KwRes::ok()
                } else {
                    KwRes::one(
                        "minProperties",
                        format!(
                            "{} has less than {} propert{}",
                            to_string_compact(instance),
                            n,
                            plural_unit(*n, "y", "ies")
                        ),
                    )
                }
            }
            None => KwRes::ok(),
        },
        Keyword::MaxProperties(n) => match instance.as_object() {
            Some(o) => {
                if (o.len() as u64) <= *n {
                    KwRes::ok()
                } else {
                    KwRes::one(
                        "maxProperties",
                        format!(
                            "{} has more than {} propert{}",
                            to_string_compact(instance),
                            n,
                            plural_unit(*n, "y", "ies")
                        ),
                    )
                }
            }
            None => KwRes::ok(),
        },
        Keyword::Required(_) => {
            // handled here too (when the `properties` quirk does not apply)
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let names = match kw {
                Keyword::Required(v) => v,
                _ => unreachable!(),
            };
            let missing: Vec<String> = names.iter().filter(|n| !obj.contains_key(*n)).cloned().collect();
            if missing.is_empty() {
                KwRes::ok()
            } else {
                let msgs: Vec<String> = missing.iter().map(|n| format!("\"{}\" is a required property", n)).collect();
                KwRes {
                    valid: false,
                    errors: vec![("required".to_string(), many_or_one(msgs.clone()))],
                    annotation: None,
                    details: vec![],
                    text: msgs,
                    props: vec![],
                    items: vec![],
                }
            }
        }
        Keyword::DependentRequired(pairs) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut all_msgs: Vec<String> = Vec::new();
            for (key, deps) in pairs {
                if !obj.contains_key(key) {
                    continue;
                }
                let missing: Vec<String> = deps.iter().filter(|d| !obj.contains_key(*d)).cloned().collect();
                if missing.is_empty() {
                    continue;
                }
                valid = false;
                let msgs: Vec<String> = missing.iter().map(|n| format!("\"{}\" is a required property", n)).collect();
                all_msgs.extend(msgs.iter().cloned());
                // child unit mimicking the reference implementation
                let mut child = unit(
                    format!("{}{}", node.pointer, keyword_suffix(kw).unwrap_or("")),
                    inst_path,
                    format!("{}#{}{}", node.uri, node.pointer, keyword_suffix(kw).unwrap_or("")),
                    false,
                );
                let mut grand = unit(
                    format!("{}{}", node.pointer, format!("{}/0", keyword_suffix(kw).unwrap_or(""))),
                    inst_path,
                    format!("{}#{}{}/0", node.uri, node.pointer, keyword_suffix(kw).unwrap_or("")),
                    false,
                );
                grand.errors.push(("required".to_string(), many_or_one(msgs)));
                child.details.push(grand);
                details.push(child);
            }
            if valid {
                let mut details = Vec::new();
                for (key, _) in pairs {
                    if obj.contains_key(key) {
                        let mut child = unit(
                            format!("{}{}", node.pointer, keyword_suffix(kw).unwrap_or("")),
                            inst_path,
                            format!("{}#{}{}", node.uri, node.pointer, keyword_suffix(kw).unwrap_or("")),
                            true,
                        );
                        let grand = unit(
                            format!("{}{}/0", node.pointer, keyword_suffix(kw).unwrap_or("")),
                            inst_path,
                            format!("{}#{}{}/0", node.uri, node.pointer, keyword_suffix(kw).unwrap_or("")),
                            true,
                        );
                        child.details.push(grand);
                        details.push(child);
                    }
                }
                KwRes { valid: true, errors: vec![], annotation: None, details, text: vec![], props: vec![], items: vec![] }
            } else {
                KwRes {
                    valid: false,
                    errors: vec![("dependentRequired".to_string(), many_or_one(all_msgs.clone()))],
                    annotation: None,
                    details,
                    text: all_msgs,
                    props: vec![],
                    items: vec![],
                }
            }
        }
        Keyword::Properties(props, _drop) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => {
                    return KwRes { valid: true, errors: vec![], annotation: None, details: vec![], text: vec![], props: vec![], items: vec![] }
                }
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut names: Vec<String> = Vec::new();
            let mut props_eval: Vec<String> = Vec::new();
            for (name, sub) in props {
                if let Some(v) = obj.get(name) {
                    names.push(name.clone());
                    let ip = format!("{}/{}", inst_path, crate::pointer::build(&[name.clone()]));
                    let (u, t, p, _) = validate_sub(sub, v, &ip, ctx);
                    if !u.valid {
                        valid = false;
                    }
                    details.push(u);
                    text.extend(t);
                    props_eval.extend(p);
                    props_eval.push(name.clone());
                }
            }
            let annotation = Some(Value::Array(names.iter().map(|n| Value::String(n.clone())).collect()));
            KwRes { valid, errors: vec![], annotation, details, text, props: props_eval, items: vec![] }
        }
        Keyword::PatternProperties(pprops, _drop) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => {
                    return KwRes { valid: true, errors: vec![], annotation: None, details: vec![], text: vec![], props: vec![], items: vec![] }
                }
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut names: Vec<String> = Vec::new();
            let mut props_eval: Vec<String> = Vec::new();
            for (pat, re, sub) in pprops {
                for (k, v) in obj {
                    if re.is_match(k) {
                        names.push(k.clone());
                        let ip = format!("{}/{}", inst_path, crate::pointer::build(&[k.clone()]));
                        let (u, t, p, _) = validate_sub(sub, v, &ip, ctx);
                        if !u.valid {
                            valid = false;
                        }
                        details.push(u);
                        text.extend(t);
                        props_eval.extend(p);
                        props_eval.push(k.clone());
                    }
                }
            }
            let annotation = Some(Value::Array(names.iter().map(|n| Value::String(n.clone())).collect()));
            KwRes { valid, errors: vec![], annotation, details, text, props: props_eval, items: vec![] }
        }
        Keyword::AdditionalProperties { schema, has_siblings } => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => {
                    return KwRes { valid: true, errors: vec![], annotation: None, details: vec![], text: vec![], props: vec![], items: vec![] }
                }
            };
            let schema = match schema {
                Some(s) => s,
                None => return KwRes::ok(),
            };
            // determine which properties are "additional"
            let mut extra: Vec<&String> = Vec::new();
            for (k, _) in obj {
                if evaluated_props.contains(k) {
                    continue;
                }
                // also skip properties matched by patternProperties / properties
                extra.push(k);
            }
            let is_false_schema = schema.is_false;
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let names: Vec<String> = extra.iter().map(|k| (*k).clone()).collect();
            if is_false_schema {
                if !extra.is_empty() {
                    valid = false;
                    let msg = if *has_siblings {
                        let list: Vec<String> = names.iter().map(|n| format!("'{}'", n)).collect();
                        format!("Additional properties are not allowed ({} were unexpected)", list.join(", "))
                    } else {
                        format!("False schema does not allow {}", to_string_compact(&obj[&names[0]]))
                    };
                    return KwRes {
                        valid: false,
                        errors: vec![("additionalProperties".to_string(), ErrVal::One(msg.clone()))],
                        annotation: None,
                        details: vec![],
                        text: vec![msg],
                        props: names,
                        items: vec![],
                    };
                }
                return KwRes { valid: true, errors: vec![], annotation: None, details: vec![], text: vec![], props: names, items: vec![] };
            }
            for k in &extra {
                let v = &obj[*k];
                let ip = format!("{}/{}", inst_path, crate::pointer::build(&[(*k).clone()]));
                let (u, t, _, _) = validate_sub(schema, v, &ip, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
            }
            let annotation = if extra.is_empty() { None } else { Some(Value::Array(names.iter().map(|n| Value::String(n.clone())).collect())) };
            KwRes { valid, errors: vec![], annotation, details, text, props: names, items: vec![] }
        }
        Keyword::PropertyNames(sub) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            for (k, _) in obj {
                let (u, t, _, _) = validate_sub(sub, &Value::String(k.clone()), inst_path, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
            }
            KwRes { valid, errors: vec![], annotation: None, details, text, props: vec![], items: vec![] }
        }
        Keyword::Dependencies(pairs) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let base_kw = keyword_suffix(kw).unwrap_or("");
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut msgs: Vec<String> = Vec::new();
            for (key, dep) in pairs {
                if !obj.contains_key(key) {
                    continue;
                }
                match dep {
                    Dependency::Names(names) => {
                        let missing: Vec<String> = names.iter().filter(|n| !obj.contains_key(*n)).cloned().collect();
                        if !missing.is_empty() {
                            valid = false;
                        }
                        let m: Vec<String> = missing.iter().map(|n| format!("\"{}\" is a required property", n)).collect();
                        msgs.extend(m.iter().cloned());
                        let mut child = unit(
                            format!("{}{}", node.pointer, base_kw),
                            inst_path,
                            format!("{}#{}{}", node.uri, node.pointer, base_kw),
                            missing.is_empty(),
                        );
                        let mut grand = unit(
                            format!("{}{}/0", node.pointer, base_kw),
                            inst_path,
                            format!("{}#{}{}/0", node.uri, node.pointer, base_kw),
                            missing.is_empty(),
                        );
                        if !missing.is_empty() {
                            grand.errors.push(("required".to_string(), many_or_one(m.clone())));
                        }
                        child.details.push(grand);
                        details.push(child);
                        text.extend(m);
                    }
                    Dependency::Schema(sub) => {
                        let (u, t, _, _) = validate_sub(sub, instance, inst_path, ctx);
                        if !u.valid {
                            valid = false;
                        }
                        details.push(u);
                        text.extend(t);
                    }
                }
            }
            if msgs.is_empty() {
                KwRes { valid, errors: vec![], annotation: None, details, text, props: vec![], items: vec![] }
            } else {
                KwRes {
                    valid,
                    errors: vec![("dependencies".to_string(), many_or_one(msgs.clone()))],
                    annotation: None,
                    details,
                    text,
                    props: vec![],
                    items: vec![],
                }
            }
        }
        Keyword::DependentSchemas(pairs) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            for (key, sub) in pairs {
                if !obj.contains_key(key) {
                    continue;
                }
                let (u, t, _, _) = validate_sub(sub, instance, inst_path, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
            }
            KwRes { valid, errors: vec![], annotation: None, details, text, props: vec![], items: vec![] }
        }
        Keyword::UnevaluatedProperties(_) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let unevaluated: Vec<&String> = obj.keys().filter(|k| !evaluated_props.contains(*k)).collect();
            if unevaluated.is_empty() {
                return KwRes::ok();
            }
            let names: Vec<String> = unevaluated.iter().map(|k| (*k).clone()).collect();
            let quoted: Vec<String> = names.iter().map(|n| format!("'{}'", n)).collect();
            let msg = format!("Unevaluated properties are not allowed ({} were unexpected)", quoted.join(", "));
            let mut details = Vec::new();
            for k in &unevaluated {
                let ip = format!("{}/{}", inst_path, crate::pointer::build(&[(*k).clone()]));
                let false_node = Node {
                    pointer: format!("{}unevaluatedProperties", node.pointer),
                    uri: node.uri.clone(),
                    keywords: vec![],
                    is_false: true,
                };
                let (u, _, _, _) = validate_sub(&false_node, &obj[*k], &ip, ctx);
                details.push(u);
            }
            KwRes {
                valid: false,
                errors: vec![("unevaluatedProperties".to_string(), ErrVal::One(msg.clone()))],
                annotation: None,
                details,
                text: vec![msg],
                props: names,
                items: vec![],
            }
        }
        Keyword::AllOf(subs) => {
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut valid = true;
            let mut props = Vec::new();
            let mut items = Vec::new();
            for (i, sub) in subs.iter().enumerate() {
                let (u, t, p, it) = validate_sub(sub, instance, inst_path, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
                props.extend(p);
                items.extend(it);
            }
            KwRes { valid, errors: vec![], annotation: None, details, text, props, items }
        }
        Keyword::AnyOf(subs) => {
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut props = Vec::new();
            let mut items = Vec::new();
            let mut ok = false;
            for sub in subs {
                let (u, t, p, it) = validate_sub(sub, instance, inst_path, ctx);
                if u.valid {
                    ok = true;
                    details.push(u);
                    text.extend(t);
                    props.extend(p);
                    items.extend(it);
                }
            }
            if ok {
                KwRes { valid: true, errors: vec![], annotation: None, details, text, props, items }
            } else {
                let msg = format!(
                    "{} is not valid under any of the schemas listed in the 'anyOf' keyword",
                    to_string_compact(instance)
                );
                KwRes { valid: false, errors: vec![("anyOf".to_string(), ErrVal::One(msg.clone()))], annotation: None, details, text: vec![msg], props, items }
            }
        }
        Keyword::OneOf(subs) => {
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut props = Vec::new();
            let mut items = Vec::new();
            let mut count = 0;
            for sub in subs {
                let (u, t, p, it) = validate_sub(sub, instance, inst_path, ctx);
                if u.valid {
                    count += 1;
                    details.push(u);
                    text.extend(t);
                    props.extend(p);
                    items.extend(it);
                }
            }
            if count == 1 {
                KwRes { valid: true, errors: vec![], annotation: None, details, text, props, items }
            } else {
                let msg = if count == 0 {
                    format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", to_string_compact(instance))
                } else {
                    format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", to_string_compact(instance))
                };
                KwRes { valid: false, errors: vec![("oneOf".to_string(), ErrVal::One(msg.clone()))], annotation: None, details, text: vec![msg], props, items }
            }
        }
        Keyword::Not(sub) => {
            let (u, _, _, _) = validate_sub(sub, instance, inst_path, ctx);
            if !u.valid {
                KwRes::ok()
            } else {
                let msg = format!("{} is not allowed for {}", to_string_compact(&sub_to_value(sub)), to_string_compact(instance));
                KwRes {
                    valid: false,
                    errors: vec![("not".to_string(), ErrVal::One(msg.clone()))],
                    annotation: None,
                    details: vec![],
                    text: vec![msg],
                    props: vec![],
                    items: vec![],
                }
            }
        }
        Keyword::IfThenElse { cond, then_, else_ } => {
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut props = Vec::new();
            let mut items = Vec::new();
            let mut valid = true;
            let (cu, _, _, _) = validate_sub(cond, instance, inst_path, ctx);
            if cu.valid {
                details.push(cu);
                if let Some(t) = then_ {
                    let (u, tt, p, it) = validate_sub(t, instance, inst_path, ctx);
                    if !u.valid {
                        valid = false;
                    }
                    details.push(u);
                    text.extend(tt);
                    props.extend(p);
                    items.extend(it);
                }
            } else if let Some(e) = else_ {
                let (u, tt, p, it) = validate_sub(e, instance, inst_path, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(tt);
                props.extend(p);
                items.extend(it);
            }
            KwRes { valid, errors: vec![], annotation: None, details, text, props, items }
        }
        Keyword::Ref(target) => {
            let (u, t, p, it) = validate_sub(&target.node, instance, inst_path, ctx);
            let valid = u.valid;
            let details = vec![u];
            KwRes { valid, errors: vec![], annotation: None, details, text: t, props: p, items: it }
        }
        Keyword::Annotation { .. } => KwRes::ok(),
    }
}

fn sub_to_value(node: &Node) -> Value {
    if node.is_false {
        return Value::Bool(false);
    }
    // rebuild a value representation of the compiled node is not possible in
    // general; the caller keeps the original schema around instead
    Value::Object(Map::new())
}

fn type_matches(instance: &Value, t: &str, ctx: &Ctx) -> bool {
    match t {
        "null" => instance.is_null(),
        "boolean" => instance.is_boolean(),
        "string" => instance.is_string(),
        "array" => instance.is_array(),
        "object" => instance.is_object(),
        "number" => instance.is_number(),
        "integer" => instance.is_number() && {
            let s = to_string_compact(instance);
            if ctx.draft.strict_integer() {
                !s.contains('.') && Dec::parse(&s).is_integer()
            } else {
                Dec::parse(&s).is_integer()
            }
        },
        _ => false,
    }
}

fn is_multiple(instance: &Value, multiple: &Value) -> bool {
    let (ia, ma) = match (instance.as_number(), multiple.as_number()) {
        (Some(a), Some(b)) => (a, b),
        _ => return false,
    };
    let si = ia.to_string();
    let sm = ma.to_string();
    let plain = |s: &str| !s.contains('.') && !s.contains('e') && !s.contains('E');
    let as_i64 = |s: &str| -> Option<i64> { if plain(s) { s.parse::<i64>().ok() } else { None } };
    let as_u64 = |s: &str| -> Option<u64> { if plain(s) { s.parse::<u64>().ok() } else { None } };
    if let (Some(a), Some(b)) = (as_i64(&si), as_i64(&sm)) {
        return b != 0 && a % b == 0;
    }
    if let (Some(a), Some(b)) = (as_u64(&si), as_u64(&sm)) {
        return b != 0 && a % b == 0;
    }
    let da = Dec::parse(&si);
    let db = Dec::parse(&sm);
    if !plain(&sm) {
        return da.divisible_by(&db);
    }
    if !plain(&si) {
        let limit = Dec::parse("9007199254740992");
        if db.cmp(&limit) == std::cmp::Ordering::Greater || db.cmp(&Dec { neg: true, digits: limit.digits.clone(), exp: limit.exp }) == std::cmp::Ordering::Less {
            return da.divisible_by(&db);
        }
        return (da.to_f64() % db.to_f64()) == 0.0;
    }
    da.divisible_by(&db)
}
