            let mut text = Vec::new();
            let mut valid = true;
            for (key, sub) in pairs {
                if !obj.contains_key(key) {
                    continue;
                }
                let (u, t, _, _) = validate_sub(sub, instance, inst_path, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
            }
            KwRes { valid, errors: vec![], annotation: None, details, text, props: vec![], items: vec![] }
        }
        Keyword::UnevaluatedProperties(_) => {
            let obj = match instance.as_object() {
                Some(o) => o,
                None => return KwRes::ok(),
            };
            let unevaluated: Vec<&String> = obj.keys().filter(|k| !evaluated_props.contains(*k)).collect();
            if unevaluated.is_empty() {
                return KwRes::ok();
            }
            let names: Vec<String> = unevaluated.iter().map(|k| (*k).clone()).collect();
            let quoted: Vec<String> = names.iter().map(|n| format!("'{}'", n)).collect();
            let msg = format!("Unevaluated properties are not allowed ({} were unexpected)", quoted.join(", "));
