            let mut text = Vec::new();
            let mut valid = true;
            let mut props = Vec::new();
            let mut items = Vec::new();
            for (i, sub) in subs.iter().enumerate() {
                let (u, t, p, it) = validate_sub(sub, instance, inst_path, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(t);
                props.extend(p);
                items.extend(it);
            }
            KwRes { valid, errors: vec![], annotation: None, details, text, props, items }
        }
        Keyword::AnyOf(subs) => {
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut props = Vec::new();
            let mut items = Vec::new();
            let mut ok = false;
            for sub in subs {
                let (u, t, p, it) = validate_sub(sub, instance, inst_path, ctx);
                if u.valid {
                    ok = true;
                    details.push(u);
                    text.extend(t);
                    props.extend(p);
                    items.extend(it);
