                    "{} is not valid under any of the schemas listed in the 'anyOf' keyword",
                    to_string_compact(instance)
                );
                KwRes { valid: false, errors: vec![("anyOf".to_string(), ErrVal::One(msg.clone()))], annotation: None, details, text: vec![msg], props, items }
            }
        }
        Keyword::OneOf(subs) => {
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut props = Vec::new();
            let mut items = Vec::new();
            let mut count = 0;
            for sub in subs {
                let (u, t, p, it) = validate_sub(sub, instance, inst_path, ctx);
                if u.valid {
                    count += 1;
                    details.push(u);
                    text.extend(t);
                    props.extend(p);
                    items.extend(it);
                }
            }
            if count == 1 {
                KwRes { valid: true, errors: vec![], annotation: None, details, text, props, items }
            } else {
                let msg = if count == 0 {
                    format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", to_string_compact(instance))
                } else {
                    format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", to_string_compact(instance))
                };
                KwRes { valid: false, errors: vec![("oneOf".to_string(), ErrVal::One(msg.clone()))], annotation: None, details, text: vec![msg], props, items }
            }
        }
        Keyword::Not(sub) => {
            let (u, _, _, _) = validate_sub(sub, instance, inst_path, ctx);
            if !u.valid {
                KwRes::ok()
            } else {
                let msg = format!("{} is not allowed for {}", to_string_compact(&sub_to_value(sub)), to_string_compact(instance));
                KwRes {
                    valid: false,
                    errors: vec![("not".to_string(), ErrVal::One(msg.clone()))],
                    annotation: None,
                    details: vec![],
                    text: vec![msg],
                    props: vec![],
                    items: vec![],
                }
            }
        }
        Keyword::IfThenElse { cond, then_, else_ } => {
            let mut details = Vec::new();
            let mut text = Vec::new();
            let mut props = Vec::new();
            let mut items = Vec::new();
            let mut valid = true;
            let (cu, _, _, _) = validate_sub(cond, instance, inst_path, ctx);
            if cu.valid {
                details.push(cu);
                if let Some(t) = then_ {
                    let (u, tt, p, it) = validate_sub(t, instance, inst_path, ctx);
                    if !u.valid {
                        valid = false;
                    }
                    details.push(u);
                    text.extend(tt);
                    props.extend(p);
                    items.extend(it);
                }
            } else if let Some(e) = else_ {
                let (u, tt, p, it) = validate_sub(e, instance, inst_path, ctx);
                if !u.valid {
                    valid = false;
                }
                details.push(u);
                text.extend(tt);
                props.extend(p);
                items.extend(it);
            }
            KwRes { valid, errors: vec![], annotation: None, details, text, props, items }
        }
        Keyword::Ref(target) => {
            let (u, t, p, it) = validate_sub(&target.node, instance, inst_path, ctx);
            let valid = u.valid;
            let details = vec![u];
            KwRes { valid, errors: vec![], annotation: None, details, text: t, props: p, items: it }
        }
        Keyword::Annotation { .. } => KwRes::ok(),
    }
}

fn sub_to_value(node: &Node) -> Value {
    if node.is_false {
        return Value::Bool(false);
    }
    // rebuild a value representation of the compiled node is not possible in
    // general; the caller keeps the original schema around instead
    Value::Object(Map::new())
}

fn type_matches(instance: &Value, t: &str, ctx: &Ctx) -> bool {
    match t {
        "null" => instance.is_null(),
        "boolean" => instance.is_boolean(),
        "string" => instance.is_string(),
        "array" => instance.is_array(),
        "object" => instance.is_object(),
        "number" => instance.is_number(),
        "integer" => instance.is_number() && {
            let s = to_string_compact(instance);
            if ctx.draft.strict_integer() {
                !s.contains('.') && Dec::parse(&s).is_integer()
            } else {
                Dec::parse(&s).is_integer()
            }
        },
        _ => false,
    }
}

fn is_multiple(instance: &Value, multiple: &Value) -> bool {
    let (ia, ma) = match (instance.as_number(), multiple.as_number()) {
        (Some(a), Some(b)) => (a, b),
        _ => return false,
    };
    let si = ia.to_string();
    let sm = ma.to_string();
    let plain = |s: &str| !s.contains('.') && !s.contains('e') && !s.contains('E');
    let as_i64 = |s: &str| -> Option<i64> { if plain(s) { s.parse::<i64>().ok() } else { None } };
    let as_u64 = |s: &str| -> Option<u64> { if plain(s) { s.parse::<u64>().ok() } else { None } };
    if let (Some(a), Some(b)) = (as_i64(&si), as_i64(&sm)) {
        return b != 0 && a % b == 0;
    }
    if let (Some(a), Some(b)) = (as_u64(&si), as_u64(&sm)) {
        return b != 0 && a % b == 0;
    }
    let da = Dec::parse(&si);
    let db = Dec::parse(&sm);
    if !plain(&sm) {
        return da.divisible_by(&db);
    }
    if !plain(&si) {
        let limit = Dec::parse("9007199254740992");
        if db.cmp(&limit) == std::cmp::Ordering::Greater || db.cmp(&Dec { neg: true, digits: limit.digits.clone(), exp: limit.exp }) == std::cmp::Ordering::Less {
            return da.divisible_by(&db);
        }
        return (da.to_f64() % db.to_f64()) == 0.0;
    }
    da.divisible_by(&db)
}
