//! Meta-schema (schema validity) checks.
//!
//! The reference implementation validates a schema against the JSON Schema
//! meta-schema of the selected draft.  The checks below reproduce the
//! constraints enforced there, together with the exact error messages.

use crate::jsonval::to_string_compact;
use crate::schema::Draft;
use serde_json::Value;

const ANCHOR_2020: &str = "^[A-Za-z_][-A-Za-z0-9._]*$";
const ANCHOR_2019: &str = "^[A-Za-z][-A-Za-z0-9.:_]*$";

fn is_schema(v: &Value) -> bool {
    matches!(v, Value::Bool(_) | Value::Object(_))
}

fn err(v: &Value, t: &str) -> String {
    format!("{} is not of type \"{}\"", to_string_compact(v), t)
}

fn err_types(v: &Value, types: &[&str]) -> String {
    let mut t: Vec<&str> = types.to_vec();
    t.sort();
    format!("{} is not of types {}", to_string_compact(v), t.iter().map(|x| format!("\"{}\"", x)).collect::<Vec<_>>().join(", "))
}

fn any_of_err(v: &Value) -> String {
    format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", to_string_compact(v))
}

fn min_items_err(v: &Value, n: usize) -> String {
    format!("{} has less than {} item{}", to_string_compact(v), n, if n == 1 { "" } else { "s" })
}

fn unique_err(v: &Value) -> String {
    format!("{} has non-unique elements", to_string_compact(v))
}

fn regex_err(v: &Value) -> String {
    format!("{} is not a \"regex\"", to_string_compact(v))
}

fn pattern_err(v: &Value, pat: &str) -> String {
    format!("{} does not match \"{}\"", to_string_compact(v), pat)
}

fn is_string_array(v: &Value) -> Option<String> {
    let a = match v.as_array() {
        Some(a) => a,
        None => return Some(err(v, "array")),
    };
    for it in a {
