        }
    }
    for i in 0..a.len() {
        for j in i + 1..a.len() {
            if a[i] == a[j] {
                return Some(unique_err(v));
            }
        }
    }
    None
}

fn check_array_of(v: &Value, min: usize) -> Option<String> {
    let a = match v.as_array() {
        Some(a) => a,
        None => return Some(err(v, "array")),
    };
    if a.len() < min {
        return Some(min_items_err(v, min));
    }
    for it in a {
        if !is_schema(it) {
            return Some(err_types(it, &["boolean", "object"]));
        }
    }
    None
}

fn check_object_of(v: &Value, draft: Draft) -> Option<String> {
    let o = match v.as_object() {
        Some(o) => o,
        None => return Some(err(v, "object")),
    };
    for (_, sub) in o {
        if let Some(e) = check_schema_value(sub, draft) {
