        }
    }
    None
}

/// check a subschema value (used for `additionalProperties` etc.)
fn check_schema_value(v: &Value, draft: Draft) -> Option<String> {
    if !is_schema(v) {
        return Some(err_types(v, &["boolean", "object"]));
    }
    if let Value::Object(o) = v {
        // only a shallow check of the subschema's own keywords is needed here,
        // matching how the meta-schema validates subschemas
        for (k, val) in o {
            if let Some(e) = check_keyword(k, val, draft) {
                return Some(e);
            }
        }
    }
    None
}

fn is_nonneg_int(v: &Value) -> Option<String> {
    if !v.is_number() {
        return Some(err(v, "integer"));
    }
    let s = to_string_compact(v);
    if !crate::num::Dec::parse(&s).is_integer() {
        return Some(err(v, "integer"));
