    if crate::num::Dec::parse(&s).cmp(&crate::num::Dec::parse("0")) == std::cmp::Ordering::Less {
        return Some(format!("{} is less than the minimum of 0", to_string_compact(v)));
    }
    None
}

fn check_number(v: &Value) -> Option<String> {
    if !v.is_number() {
        return Some(err(v, "number"));
    }
    None
