fn check_keyword(k: &str, v: &Value, draft: Draft) -> Option<String> {
    match k {
        "definitions" => check_object_of(v, draft),
        "dependencies" => {
            let o = match v.as_object() {
                Some(o) => o,
                None => return Some(err(v, "object")),
            };
            for (_, val) in o {
                if is_schema(val) {
                    if let Some(e) = check_schema_value(val, draft) {
                        return Some(e);
                    }
                } else if let Some(e) = is_string_array(val) {
                    return Some(e);
                }
            }
            None
        }
        "$comment" | "$id" | "$ref" | "$schema" | "$dynamicAnchor" | "$dynamicRef" | "id" | "title" | "description"
        | "contentEncoding" | "contentMediaType" | "format" => {
            if !v.is_string() {
                Some(err(v, "string"))
            } else {
                None
            }
        }
        "$defs" => check_object_of(v, draft),
        "$vocabulary" => {
            let o = match v.as_object() {
                Some(o) => o,
                None => return Some(err(v, "object")),
            };
            for (_, val) in o {
                if !val.is_boolean() {
                    return Some(err(val, "boolean"));
                }
            }
            None
        }
        "$anchor" => match v.as_str() {
            Some(s) => {
                let pat = if draft == Draft::V2019 { ANCHOR_2019 } else { ANCHOR_2020 };
                if crate::regex_util::full_match(pat, s) {
                    None
                } else {
                    Some(pattern_err(v, pat))
                }
            }
            None => Some(err(v, "string")),
        },
        "additionalProperties" => {
            if draft == Draft::V4 {
                if is_schema(v) {
                    None
                } else {
                    Some(any_of_err(v))
                }
            } else if is_schema(v) {
                None
            } else {
                Some(err_types(v, &["boolean", "object"]))
            }
        }
        "additionalItems" => {
            if draft == Draft::V4 {
                if is_schema(v) {
                    None
                } else {
                    Some(any_of_err(v))
                }
            } else if is_schema(v) {
                None
            } else {
                Some(err_types(v, &["boolean", "object"]))
            }
        }
        "allOf" | "anyOf" | "oneOf" => check_array_of(v, 1),
        "contains" | "propertyNames" | "unevaluatedItems" | "unevaluatedProperties" | "contentSchema" => {
            if is_schema(v) {
                None
            } else {
                Some(err_types(v, &["boolean", "object"]))
            }
        }
        "else" | "if" => {
            if is_schema(v) {
                None
            } else {
                Some(err_types(v, &["boolean", "object"]))
            }
        }
        "not" => {
            if draft == Draft::V4 {
                if v.is_object() {
                    None
                } else {
                    Some(err(v, "object"))
                }
            } else if is_schema(v) {
                None
            } else {
                Some(err_types(v, &["boolean", "object"]))
            }
        }
        "items" => {
            if draft == Draft::V2020 {
                if is_schema(v) {
                    None
                } else {
                    Some(err_types(v, &["boolean", "object"]))
                }
            } else {
                // anyOf[tuple, schema]
                match v {
                    Value::Array(a) => {
                        if a.is_empty() {
                            return Some(any_of_err(v));
                        }
                        for it in a {
                            if !is_schema(it) {
                                return Some(any_of_err(v));
                            }
                        }
                        for i in 0..a.len() {
                            for j in i + 1..a.len() {
                                if a[i] == a[j] {
                                    return Some(any_of_err(v));
                                }
                            }
                        }
                        None
                    }
                    other => {
                        if is_schema(other) {
                            None
                        } else {
                            Some(any_of_err(other))
                        }
                    }
                }
            }
        }
        "patternProperties" | "properties" => check_object_of(v, draft),
        "prefixItems" => check_array_of(v, 1),
        "enum" => {
            if v.is_array() {
                None
            } else {
                Some(err(v, "array"))
            }
        }
        "exclusiveMaximum" | "exclusiveMinimum" => {
            if draft == Draft::V4 {
                match v {
                    Value::Bool(_) => None,
                    _ => Some(err(v, "boolean")),
                }
            } else {
                check_number(v)
            }
        }
        "maximum" | "minimum" | "multipleOf" => check_number(v),
        "maxContains" | "minContains" | "maxItems" | "maxLength" | "maxProperties" | "minItems" | "minLength"
        | "minProperties" => is_nonneg_int(v),
        "multipleOf_zero" => None,
        "pattern" => match v.as_str() {
            Some(s) => {
                if crate::formats::validate_regex(s) {
                    None
                } else {
                    Some(regex_err(v))
                }
            }
            None => Some(err(v, "string")),
        },
        "required" => {
            if let Some(e) = is_string_array(v) {
                return Some(e);
            }
            if draft == Draft::V4 && v.as_array().map(|a| a.is_empty()).unwrap_or(false) {
                return Some(min_items_err(v, 1));
            }
            None
        }
        "type" => {
            let simple = |s: &Value| -> bool {
                matches!(
                    s.as_str(),
                    Some("array") | Some("boolean") | Some("integer") | Some("null") | Some("number") | Some("object") | Some("string")
                )
            };
            match v {
                Value::String(_) if simple(v) => None,
                Value::String(_) => Some(any_of_err(v)),
                Value::Array(a) => {
                    if a.is_empty() {
                        return Some(any_of_err(v));
                    }
                    for it in a {
                        if !simple(it) {
                            return Some(any_of_err(v));
                        }
                    }
                    for i in 0..a.len() {
                        for j in i + 1..a.len() {
                            if a[i] == a[j] {
                                return Some(any_of_err(v));
                            }
                        }
                    }
                    None
                }
                _ => Some(any_of_err(v)),
            }
        }
        "uniqueItems" => {
            if v.is_boolean() {
                None
            } else {
                Some(err(v, "boolean"))
            }
        }
        "deprecated" | "readOnly" | "writeOnly" => {
            if v.is_boolean() {
                None
            } else {
                Some(err(v, "boolean"))
            }
        }
        "examples" => {
            if v.is_array() {
                None
            } else {
                Some(err(v, "array"))
            }
        }
        "dependentRequired" => {
            let o = match v.as_object() {
                Some(o) => o,
                None => return Some(err(v, "object")),
            };
            for (_, val) in o {
                if let Some(e) = is_string_array(val) {
                    return Some(e);
                }
            }
            None
        }
        "dependentSchemas" => check_object_of(v, draft),
        "multipleOf_pos" => None,
        _ => None,
    }
}

/// Returns the first error message when `schema` is not a valid schema.
pub fn check(schema: &Value, draft: Draft) -> Option<String> {
    if !is_schema(schema) {
        return Some(err_types(schema, &["boolean", "object"]));
    }
    let obj = match schema {
        Value::Object(o) => o,
        _ => return None,
    };
    // draft 4: exclusiveMinimum/Maximum require the corresponding keyword
    if draft == Draft::V4 {
        if obj.contains_key("exclusiveMinimum") && !obj.contains_key("minimum") {
            return Some("\"minimum\" is a required property".to_string());
        }
        if obj.contains_key("exclusiveMaximum") && !obj.contains_key("maximum") {
            return Some("\"maximum\" is a required property".to_string());
        }
    }
    if let Some(v) = obj.get("multipleOf") {
        if v.is_number() {
            let d = crate::num::Dec::parse(&to_string_compact(v));
            if d.cmp(&crate::num::Dec::parse("0")) != std::cmp::Ordering::Greater {
                return Some(format!("{} is less than or equal to the minimum of 0", to_string_compact(v)));
            }
        }
    }
    for k in order(draft) {
        if let Some(v) = obj.get(k) {
            if let Some(e) = check_keyword(k, v, draft) {
                return Some(e);
            }
        }
    }
    None
}
