            return Some("\"minimum\" is a required property".to_string());
        }
        if obj.contains_key("exclusiveMaximum") && !obj.contains_key("maximum") {
            return Some("\"maximum\" is a required property".to_string());
        }
    }
    if let Some(v) = obj.get("multipleOf") {
        if v.is_number() {
            let d = crate::num::Dec::parse(&to_string_compact(v));
            if d.cmp(&crate::num::Dec::parse("0")) != std::cmp::Ordering::Greater {
                return Some(format!("{} is less than or equal to the minimum of 0", to_string_compact(v)));
            }
        }
    }
    for k in order(draft) {
        if let Some(v) = obj.get(k) {
            if let Some(e) = check_keyword(k, v, draft) {
                return Some(e);
            }
        }
    }
    None
