//! Small regex helpers.

use regex::Regex;
use std::sync::OnceLock;

fn compiled(pat: &str) -> &'static Regex {
    static CACHE: OnceLock<Vec<(String, Regex)>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Vec::new());
    // note: the cache is only filled once per process; patterns used here are few
    if let Some((_, r)) = cache.iter().find(|(k, _)| k == pat) {
        return unsafe { &*(r as *const Regex) };
    }
    let r = Regex::new(pat).expect("static regex");
    unsafe {
        let mut v = std::mem::ManuallyDrop::new(cache as *const Vec<(String, Regex)> as *mut Vec<(String, Regex)>);
        (*v).push((pat.to_string(), r));
    }
    let v = &*(std::mem::ManuallyDrop::new(cache as *const Vec<(String, Regex)> as *mut Vec<(String, Regex)>));
    let (_, r) = &v[v.len() - 1];
    unsafe { &*(r as *const Regex) }
}

pub fn full_match(pat: &str, s: &str) -> bool {
    let re = Regex::new(pat).ok();
    match re {
        Some(r) => r.is_match(s),
        None => false,
    }
}
