}

fn main() {
    let args = Args::parse();
    run(args);
}

fn run(args: Args) {
    // certificate file is validated eagerly, before anything else
    if let Some(path) = &args.cacert {
        if let Err(e) = std::fs::read_to_string(path) {
            println!("Error: Failed to read certificate file '{}': {}", path, io_err(&e));
            exit(1);
        }
    }

    let schema_path = match &args.schema {
        Some(p) => p.clone(),
        None => {
            // clap already reports the missing argument
            exit(2);
        }
    };
    let text = match std::fs::read_to_string(&schema_path) {
        Ok(t) => t,
        Err(e) => {
            println!("Error: {}", io_err(&e));
            exit(1);
        }
    };
    let schema: Value = match serde_json::from_str(&text) {
        Ok(v) => v,
        Err(e) => {
            println!("Error: {}", e);
            exit(1);
        }
    };

    let assert_format = args.assert_format && !args.no_assert_format;

    // draft selection
    let draft = match &args.draft {
        Some(d) => crate::schema::Draft::from_str(d).unwrap(),
        None => {
            let meta = schema.get("$schema").and_then(|v| v.as_str()).unwrap_or("");
            draft_from_meta(meta)
        }
    };

    let client = crate::http::HttpClient {
        connect_timeout: args.connect_timeout,
        timeout: args.timeout,
        insecure: args.insecure,
        cacert: args.cacert.clone(),
    };
    let mut ctx = crate::schema::Ctx {
        draft,
        assert_format,
        registry: crate::registry::Registry::new(client),
        base_uri: String::new(),
    };

    // meta-schema validation of the schema document itself
    if let Some(msg) = crate::meta::check(&schema, draft) {
        println!("Schema is invalid. Error: {}", msg);
        exit(1);
    }

    let root_uri = format!("file://{}", absolute(&schema_path));
    ctx.base_uri = root_uri.clone();
    let node = match crate::schema::compile(&schema, "", &root_uri, &mut ctx) {
        Ok(n) => n,
        Err(e) => {
            println!("Schema is invalid. Error: {}", e);
            exit(1);
        }
    };

    let output = match args.output.as_str() {
        "flag" => Output::Flag,
        "list" => Output::List,
        "hierarchical" => Output::Hierarchical,
        _ => Output::Text,
    };

    let mut any_invalid = false;
    for inst in &args.instances {
        let text = match std::fs::read_to_string(inst) {
            Ok(t) => t,
            Err(e) => {
                println!("Error: {}", io_err(&e));
                exit(1);
            }
        };
        let value: Value = match serde_json::from_str(&text) {
            Ok(v) => v,
            Err(e) => {
                println!("Error: {}", e);
                exit(1);
            }
        };
        let res = crate::validate::validate_node(&node, &value, "", &mut ctx);
        let valid = res.valid;
        if !valid {
            any_invalid = true;
        }
        match output {
            Output::Text => {
                if valid {
                    if !args.errors_only {
                        println!("{} - VALID", inst);
                    }
                } else {
                    let msgs = crate::output::collect_messages(&res.units);
                    println!("{} - INVALID. Errors:", inst);
                    for (i, m) in msgs.iter().enumerate() {
                        println!("{}. {}", i + 1, m);
                    }
                }
            }
            Output::Flag => {
                let mut payload = serde_json::Map::new();
                payload.insert("valid".to_string(), Value::Bool(valid));
                print_result(inst, "flag", Value::Object(payload));
            }
            Output::List => {
                let mut payload = serde_json::Map::new();
                payload.insert("details".to_string(), Value::Array(res.units.iter().map(|u| u.to_value()).collect()));
                payload.insert("valid".to_string(), Value::Bool(valid));
                print_result(inst, "list", Value::Object(payload));
            }
            Output::Hierarchical => {
                let units = crate::output::hierarchical(res.units);
                let mut payload = serde_json::Map::new();
                payload.insert("details".to_string(), Value::Array(units.iter().map(|u| u.to_value()).collect()));
                payload.insert("valid".to_string(), Value::Bool(valid));
                print_result(inst, "hierarchical", Value::Object(payload));
            }
        }
    }
    if any_invalid {
        exit(1);
    }
}

fn print_result(instance: &str, output: &str, payload: Value) {
    let mut m = serde_json::Map::new();
    m.insert("instance".to_string(), Value::String(instance.to_string()));
    m.insert("output".to_string(), Value::String(output.to_string()));
    m.insert("payload".to_string(), payload);
    m.insert("schema".to_string(), Value::String(instance.to_string()));
    println!("{}", serde_json::to_string(&Value::Object(m)).unwrap());
}

enum Output {
    Text,
    Flag,
    List,
    Hierarchical,
}

fn draft_from_meta(meta: &str) -> crate::schema::Draft {
    match meta {
        "http://json-schema.org/draft-04/schema#" | "http://json-schema.org/draft-04/schema"
        | "https://json-schema.org/draft-04/schema#" | "https://json-schema.org/draft-04/schema" => crate::schema::Draft::V4,
        "http://json-schema.org/draft-06/schema#" | "http://json-schema.org/draft-06/schema"
        | "https://json-schema.org/draft-06/schema#" | "https://json-schema.org/draft-06/schema" => crate::schema::Draft::V6,
        "http://json-schema.org/draft-07/schema#" | "http://json-schema.org/draft-07/schema"
        | "https://json-schema.org/draft-07/schema#" | "https://json-schema.org/draft-07/schema" => crate::schema::Draft::V7,
        "https://json-schema.org/draft/2019-09/schema" | "http://json-schema.org/draft/2019-09/schema" => crate::schema::Draft::V2019,
        "https://json-schema.org/draft/2020-12/schema" | "http://json-schema.org/draft/2020-12/schema" => crate::schema::Draft::V2020,
        _ => crate::schema::Draft::V2020,
    }
}

fn absolute(p: &str) -> String {
    let path = std::path::Path::new(p);
    match std::fs::canonicalize(path) {
        Ok(c) => c.to_string_lossy().to_string(),
        Err(_) => {
            if path.is_absolute() {
                p.to_string()
            } else {
                let cwd = std::env::current_dir().map(|d| d.to_string_lossy().to_string()).unwrap_or_default();
                format!("{}/{}", cwd, p)
            }
        }
    }
}

fn io_err(e: &std::io::Error) -> String {
    e.to_string()
}
