use serde_json::{Map, Value};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Draft {
    V4,
    V6,
    V7,
    V2019,
    V2020,
}

impl Draft {
    pub fn from_str(s: &str) -> Option<Draft> {
        match s {
            "4" => Some(Draft::V4),
            "6" => Some(Draft::V6),
            "7" => Some(Draft::V7),
            "2019" => Some(Draft::V2019),
            "2020" => Some(Draft::V2020),
            _ => None,
        }
    }
    pub fn tuple_items(&self) -> bool {
        !matches!(self, Draft::V2020)
    }
    pub fn strict_integer(&self) -> bool {
        matches!(self, Draft::V4)
    }
}

pub struct Ctx {
    pub draft: Draft,
    pub assert_format: bool,
    pub registry: crate::registry::Registry,
    pub base_uri: String,
}

/// A compiled schema node.
pub struct Node {
    pub pointer: String,
    pub uri: String,
    pub keywords: Vec<Keyword>,
    pub is_false: bool,
}

pub struct RefTarget {
    pub node: Box<Node>,
    /// schema location recorded on the `$ref` keyword unit
    pub location: String,
}

pub enum Keyword {
    Annotation { name: String, value: Value },
    Type(Vec<String>),
    Const(Value),
    Enum(Vec<Value>),
    MultipleOf(Value),
    Maximum { limit: Value, exclusive: bool },
    Minimum { limit: Value, exclusive: bool },
    MaxLength(u64),
    MinLength(u64),
    Pattern { re: Regex, raw: String },
    MaxItems(u64),
    MinItems(u64),
    UniqueItems,
    ItemsTuple(Vec<Box<Node>>),
    Items { single: Option<Box<Node>>, rest_from: usize, fast: Option<String> },
    PrefixItems(Vec<Box<Node>>),
    AdditionalItems { single: Option<Box<Node>>, rest_from: usize },
    Contains { schema: Box<Node>, min: Option<u64>, max: Option<u64> },
    UnevaluatedItems(Value),
    MinProperties(u64),
    MaxProperties(u64),
    Required(Vec<String>),
    DependentRequired(Vec<(String, Vec<String>)>),
    Properties(Vec<(String, Box<Node>)>, bool),
    PatternProperties(Vec<(String, Regex, Box<Node>)>, bool),
    AdditionalProperties {
        schema: Option<Box<Node>>,
        has_siblings: bool,
        props: Vec<String>,
        patterns: Vec<String>,
        is_bool: bool,
    },
    PropertyNames(Box<Node>),
    Dependencies(Vec<(String, Dependency)>),
    DependentSchemas(Vec<(String, Box<Node>)>),
    UnevaluatedProperties(Value),
    AllOf(Vec<Box<Node>>),
    AnyOf(Vec<Box<Node>>),
    OneOf(Vec<Box<Node>>),
    Not { node: Box<Node>, raw: Value },
    IfThenElse { cond: Box<Node>, then_: Option<Box<Node>>, else_: Option<Box<Node>> },
    Ref(Box<RefTarget>),
    Format(String),
}

pub enum Dependency {
    Names(Vec<String>),
    Schema(Box<Node>),
}

/// Result of validating one keyword.
pub struct KwRes {
    pub valid: bool,
    pub errors: Vec<(String, ErrVal)>,
    pub annotation: Option<Value>,
    pub details: Vec<Unit>,
    pub text: Vec<String>,
    pub props: Vec<String>,
    pub items: Vec<usize>,
}

impl KwRes {
    pub fn ok() -> KwRes {
        KwRes {
            valid: true,
            errors: vec![],
            annotation: None,
            details: vec![],
            text: vec![],
            props: vec![],
            items: vec![],
        }
    }
    pub fn one(keyword: &str, msg: String) -> KwRes {
        KwRes {
            valid: false,
            errors: vec![(keyword.to_string(), ErrVal::One(msg.clone()))],
            annotation: None,
            details: vec![],
            text: vec![msg],
            props: vec![],
            items: vec![],
        }
    }
    /// a keyword result with a custom (basic-output) message and text message
    pub fn two(keyword: &str, basic: String, text: String) -> KwRes {
        KwRes {
            valid: false,
            errors: vec![(keyword.to_string(), ErrVal::One(basic))],
            annotation: None,
            details: vec![],
            text: vec![text],
            props: vec![],
            items: vec![],
        }
    }
}

pub struct NodeRes {
    pub valid: bool,
    pub units: Vec<Unit>,
    pub annotations: Vec<(String, Value)>,
    pub text: Vec<String>,
    pub props: Vec<String>,
    pub items: Vec<usize>,
}

pub fn escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn ptr_join(pointer: &str, keyword: &str) -> String {
    format!("{}/{}", pointer, keyword)
}

fn ptr_index(pointer: &str, keyword: &str, index: usize) -> String {
    format!("{}/{}/{}", pointer, keyword, index)
}

// ---------------------------------------------------------------------------
// compilation
// ---------------------------------------------------------------------------

pub fn compile(schema: &Value, pointer: &str, uri: &str, ctx: &mut Ctx) -> Result<Node, String> {
    if let Value::Bool(false) = schema {
        return Ok(Node { pointer: pointer.into(), uri: uri.into(), keywords: vec![], is_false: true });
    }
    let obj: Map<String, Value> = match schema {
        Value::Object(o) => o.clone(),
        Value::Bool(true) => Map::new(),
        _ => {
            return Err(format!(
                "{} is not of types \"boolean\", \"object\"",
                to_string_compact(schema)
            ))
        }
    };
    let mut keywords: Vec<Keyword> = Vec::new();

    // reserved keywords
    for name in ["$id", "$schema"] {
        if let Some(Value::String(s)) = obj.get(name) {
            if let Err(e) = crate::uri::validate_uri_reference(s) {
                return Err(format!("Invalid URI reference '{}': {}", s, e));
            }
        }
    }
    // the base URI for this node (updated by `$id`)
    let uri_here = match obj.get("$id") {
        Some(Value::String(id)) => crate::uri::resolve(uri, id),
        _ => uri.to_string(),
    };
    // compile $defs / definitions so invalid subschemas are reported
    for container in ["$defs", "definitions"] {
        if let Some(Value::Object(defs)) = obj.get(container) {
            for (k, v) in defs {
                compile(v, &ptr_index(pointer, container, 0).replace(&format!("/{}/0", container), &format!("/{}/{}", container, crate::escape(k))), &uri_here, ctx)?;
            }
        }
    }

    // --- type / const / enum ----------------------------------------------
    if let Some(v) = obj.get("type") {
        let expected: Vec<String> = match v {
            Value::String(s) => vec![s.clone()],
            Value::Array(a) => a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect(),
            _ => vec![],
        };
        let mut expected = expected;
        expected.sort();
        keywords.push(Keyword::Type(expected));
    }
    if let Some(v) = obj.get("const") {
        keywords.push(Keyword::Const(v.clone()));
    }
    if let Some(Value::Array(items)) = obj.get("enum") {
        keywords.push(Keyword::Enum(items.clone()));
    }
    // --- numbers ----------------------------------------------------------
    if let Some(v) = obj.get("minimum") {
        keywords.push(Keyword::Minimum { limit: v.clone(), exclusive: false });
    }
    if let Some(v) = obj.get("maximum") {
        keywords.push(Keyword::Maximum { limit: v.clone(), exclusive: false });
    }
    if let Some(v) = obj.get("exclusiveMinimum") {
        match v {
            Value::Bool(true) => {
                if let Some(m) = obj.get("minimum") {
                    keywords.push(Keyword::Minimum { limit: m.clone(), exclusive: true });
                }
            }
            Value::Number(_) => keywords.push(Keyword::Minimum { limit: v.clone(), exclusive: true }),
            _ => {}
        }
    }
    if let Some(v) = obj.get("exclusiveMaximum") {
        match v {
            Value::Bool(true) => {
                if let Some(m) = obj.get("maximum") {
                    keywords.push(Keyword::Maximum { limit: m.clone(), exclusive: true });
                }
            }
            Value::Number(_) => keywords.push(Keyword::Maximum { limit: v.clone(), exclusive: true }),
            _ => {}
        }
    }
    if let Some(v) = obj.get("multipleOf") {
        keywords.push(Keyword::MultipleOf(v.clone()));
    }
    // --- strings ----------------------------------------------------------
    if let Some(v) = obj.get("minLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinLength(n));
        }
    }
    if let Some(v) = obj.get("maxLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxLength(n));
        }
    }
    if let Some(Value::String(p)) = obj.get("pattern") {
        if let Ok(re) = Regex::new(p) {
            keywords.push(Keyword::Pattern { re, raw: p.clone() });
        }
    }
    if let Some(Value::String(f)) = obj.get("format") {
        if known_format(f) {
            keywords.push(Keyword::Format(f.clone()));
        }
    }
    // --- arrays -----------------------------------------------------------
    if let Some(v) = obj.get("minItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinItems(n));
        }
    }
    if let Some(v) = obj.get("maxItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxItems(n));
        }
    }
    if obj.get("uniqueItems").and_then(|v| v.as_bool()) == Some(true) {
        keywords.push(Keyword::UniqueItems);
    }
    let mut prefix_len = 0usize;
    if let Some(Value::Array(a)) = obj.get("prefixItems") {
        let mut v = Vec::new();
        for (i, sub) in a.iter().enumerate() {
            v.push(Box::new(compile(sub, &ptr_index(pointer, "prefixItems", i), &uri_here, ctx)?));
        }
        prefix_len = v.len();
        keywords.push(Keyword::PrefixItems(v));
    }
    match obj.get("items") {
        Some(Value::Array(a)) => {
            let mut v = Vec::new();
            for (i, sub) in a.iter().enumerate() {
                v.push(Box::new(compile(sub, &ptr_index(pointer, "items", i), &uri_here, ctx)?));
            }
            prefix_len = v.len();
            keywords.push(Keyword::ItemsTuple(v));
            if let Some(sub) = obj.get("additionalItems") {
                let single = compile_opt_sub(sub, &ptr_join(pointer, "additionalItems"), &uri_here, ctx);
                keywords.push(Keyword::AdditionalItems { single, rest_from: prefix_len });
            }
        }
        Some(sub) => {
            let fast = match sub {
                Value::Object(o) if o.len() == 1 => o.get("type").and_then(|t| t.as_str()).map(|s| s.to_string()),
                _ => None,
            };
            let single = compile_opt_sub(sub, &ptr_join(pointer, "items"), &uri_here, ctx);
            keywords.push(Keyword::Items { single, rest_from: prefix_len, fast });
        }
        None => {}
    }
    if let Some(v) = obj.get("contains") {
        let single = match v {
            Value::Bool(true) => Box::new(compile(&Value::Bool(true), &ptr_join(pointer, "contains"), &uri_here, ctx)?),
            _ => Box::new(compile(v, &ptr_join(pointer, "contains"), &uri_here, ctx)?),
        };
        let min = obj.get("minContains").and_then(|x| x.as_u64());
        let max = obj.get("maxContains").and_then(|x| x.as_u64());
        keywords.push(Keyword::Contains { schema: single, min, max });
    }
    if let Some(v) = obj.get("unevaluatedItems") {
        if !v.is_boolean() || *v == Value::Bool(false) {
            keywords.push(Keyword::UnevaluatedItems(v.clone()));
        }
    }
    // --- objects ----------------------------------------------------------
    if let Some(v) = obj.get("minProperties") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinProperties(n));
        }
    }
    if let Some(v) = obj.get("maxProperties") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxProperties(n));
        }
    }
    if let Some(Value::Array(a)) = obj.get("required") {
        let names: Vec<String> = a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect();
        keywords.push(Keyword::Required(names));
    }
    if let Some(Value::Object(o)) = obj.get("dependentRequired") {
        let v: Vec<(String, Vec<String>)> = o
            .iter()
            .map(|(k, val)| {
                (
                    k.clone(),
                    val.as_array()
                        .map(|a| a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect())
                        .unwrap_or_default(),
                )
            })
            .collect();
        keywords.push(Keyword::DependentRequired(v));
    }
    let props: Vec<(String, Box<Node>)> = match obj.get("properties") {
        Some(Value::Object(o)) => {
            let mut v = Vec::new();
            for (k, sub) in o {
                v.push((k.clone(), Box::new(compile(sub, &format!("{}/properties/{}", pointer, crate::escape(k)), &uri_here, ctx)?)));
            }
            v
        }
        _ => Vec::new(),
    };
    let pprops: Vec<(String, Regex, Box<Node>)> = match obj.get("patternProperties") {
        Some(Value::Object(o)) => {
            let mut v = Vec::new();
            for (k, sub) in o {
                if let Ok(re) = Regex::new(k) {
                    v.push((
                        k.clone(),
                        re,
                        Box::new(compile(sub, &format!("{}/patternProperties/{}", pointer, crate::escape(k)), &uri_here, ctx)?),
                    ));
                }
            }
            v
        }
        _ => Vec::new(),
    };
    let additional_raw = obj.get("additionalProperties");
    let additional: Option<Box<Node>> = match additional_raw {
        Some(Value::Bool(true)) => None,
        Some(Value::Bool(false)) => Some(Box::new(Node {
            pointer: ptr_join(pointer, "additionalProperties"),
            uri: uri_here.clone(),
            keywords: vec![],
            is_false: true,
        })),
        Some(sub) => Some(Box::new(compile(sub, &ptr_join(pointer, "additionalProperties"), &uri_here, ctx)?)),
        None => None,
    };
    let has_siblings = !props.is_empty() || !pprops.is_empty();
    let merged = matches!(additional_raw, Some(Value::Bool(false))) || (additional_raw.is_some() && !matches!(additional_raw, Some(Value::Bool(true))));
    let is_bool = matches!(additional_raw, Some(Value::Bool(_)));
    let prop_names: Vec<String> = props.iter().map(|(k, _)| k.clone()).collect();
    let pattern_names: Vec<String> = pprops.iter().map(|(k, _, _)| k.clone()).collect();
    if !props.is_empty() {
        keywords.push(Keyword::Properties(props, merged && additional_raw.is_some()));
    }
    if !pprops.is_empty() {
        keywords.push(Keyword::PatternProperties(pprops, merged && additional_raw.is_some()));
    }
    if let Some(schema) = additional {
        keywords.push(Keyword::AdditionalProperties {
            schema: Some(schema),
            has_siblings,
            props: prop_names,
            patterns: pattern_names,
            is_bool,
        });
    }
    if let Some(v) = obj.get("propertyNames") {
        if !v.is_boolean() || *v == Value::Bool(false) {
            let node = match v {
                Value::Boolean(_) => Node { pointer: ptr_join(pointer, "propertyNames"), uri: uri_here.clone(), keywords: vec![], is_false: true },
                _ => compile(v, &ptr_join(pointer, "propertyNames"), &uri_here, ctx)?,
            };
            keywords.push(Keyword::PropertyNames(Box::new(node)));
        }
    }
    if let Some(Value::Object(o)) = obj.get("dependencies") {
        let mut v: Vec<(String, Dependency)> = Vec::new();
        for (k, val) in o {
            match val {
                Value::Array(a) => v.push((
                    k.clone(),
                    Dependency::Names(a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect()),
                )),
                other => v.push((
                    k.clone(),
                    Dependency::Schema(Box::new(compile(other, &format!("{}/dependencies/{}", pointer, crate::escape(k)), &uri_here, ctx)?)),
                )),
            }
        }
        keywords.push(Keyword::Dependencies(v));
    }
    if let Some(Value::Object(o)) = obj.get("dependentSchemas") {
        let mut v: Vec<(String, Box<Node>)> = Vec::new();
        for (k, val) in o {
            v.push((k.clone(), Box::new(compile(val, &format!("{}/dependentSchemas/{}", pointer, crate::escape(k)), &uri_here, ctx)?)));
        }
        keywords.push(Keyword::DependentSchemas(v));
    }
    if let Some(v) = obj.get("unevaluatedProperties") {
        if !v.is_boolean() || *v == Value::Bool(false) {
            keywords.push(Keyword::UnevaluatedProperties(v.clone()));
        }
    }
    // --- applicators ------------------------------------------------------
    if let Some(Value::Array(a)) = obj.get("allOf") {
        let mut v = Vec::new();
        for (i, sub) in a.iter().enumerate() {
            v.push(Box::new(compile(sub, &ptr_index(pointer, "allOf", i), &uri_here, ctx)?));
        }
        keywords.push(Keyword::AllOf(v));
    }
    if let Some(Value::Array(a)) = obj.get("anyOf") {
        let mut v = Vec::new();
        for (i, sub) in a.iter().enumerate() {
            v.push(Box::new(compile(sub, &ptr_index(pointer, "anyOf", i), &uri_here, ctx)?));
        }
        keywords.push(Keyword::AnyOf(v));
    }
    if let Some(Value::Array(a)) = obj.get("oneOf") {
        let mut v = Vec::new();
        for (i, sub) in a.iter().enumerate() {
            v.push(Box::new(compile(sub, &ptr_index(pointer, "oneOf", i), &uri_here, ctx)?));
        }
        keywords.push(Keyword::OneOf(v));
    }
    if let Some(v) = obj.get("not") {
        let node = match v {
            Value::Boolean(_) => Node { pointer: ptr_join(pointer, "not"), uri: uri_here.clone(), keywords: vec![], is_false: *v == Value::Bool(false) },
            _ => compile(v, &ptr_join(pointer, "not"), &uri_here, ctx)?,
        };
        keywords.push(Keyword::Not { node: Box::new(node), raw: v.clone() });
    }
    if obj.contains_key("if") || obj.contains_key("then") || obj.contains_key("else") {
        let cond = match obj.get("if") {
            Some(v) => match v {
                Value::Boolean(_) => Node { pointer: ptr_join(pointer, "if"), uri: uri_here.clone(), keywords: vec![], is_false: *v == Value::Bool(false) },
                _ => compile(v, &ptr_join(pointer, "if"), &uri_here, ctx)?,
            },
            None => Node { pointer: ptr_join(pointer, "if"), uri: uri_here.clone(), keywords: vec![], is_false: false },
        };
        let then_ = match obj.get("then") {
            Some(v) => Some(match v {
                Value::Boolean(_) => Node { pointer: ptr_join(pointer, "then"), uri: uri_here.clone(), keywords: vec![], is_false: *v == Value::Bool(false) },
                _ => compile(v, &ptr_join(pointer, "then"), &uri_here, ctx)?,
            }),
            None => None,
        };
        let else_ = match obj.get("else") {
            Some(v) => Some(match v {
                Value::Boolean(_) => Node { pointer: ptr_join(pointer, "else"), uri: uri_here.clone(), keywords: vec![], is_false: *v == Value::Bool(false) },
                _ => compile(v, &ptr_join(pointer, "else"), &uri_here, ctx)?,
            }),
            None => None,
        };
        keywords.push(Keyword::IfThenElse { cond: Box::new(cond), then_: then_.map(Box::new), else_: else_.map(Box::new) });
    }
    // --- $ref -------------------------------------------------------------
    if let Some(Value::String(r)) = obj.get("$ref") {
        if let Err(e) = crate::uri::validate_uri_reference(r) {
            return Err(format!("Invalid URI reference '{}': {}", r, e));
        }
        let resolved = crate::uri::resolve(&uri_here, r);
        let (target_uri, fragment) = crate::uri::split_fragment(&resolved);
        let target = ctx.registry.get(target_uri)?;
        let sub_pointer = fragment.map(|f| unescape_pointer(f).unwrap_or_default()).unwrap_or_default();
        let sub = match fragment {
            Some(f) if !f.is_empty() => {
                let p = unescape_pointer(f)?;
                match crate::pointer::get(&target, &p) {
                    Some(v) => v.clone(),
                    None => return Err(format!("Pointer '{}' does not exist", p)),
                }
            }
            _ => target.clone(),
        };
        let node = Box::new(compile(&sub, &sub_pointer, target_uri, ctx)?);
        keywords.push(Keyword::Ref(Box::new(RefTarget {
            node,
            location: format!("{}#{}", uri_here, fragment.unwrap_or("")),
        })));
    }
    // --- annotations (unknown keywords) -----------------------------------
    for (k, v) in &obj {
        if is_reserved(k) || is_known(k) {
            continue;
        }
        keywords.push(Keyword::Annotation { name: k.clone(), value: v.clone() });
    }
    Ok(Node { pointer: pointer.into(), uri: uri_here.into(), keywords, is_false: false })
}

fn compile_opt_sub(sub: &Value, pointer: &str, uri: &str, ctx: &mut Ctx) -> Option<Box<Node>> {
    match sub {
        Value::Bool(true) => None,
        _ => Some(Box::new(compile(sub, pointer, uri, ctx).ok()?)),
    }
}

fn known_format(f: &str) -> bool {
    matches!(
        f,
        "date" | "date-time" | "time" | "duration" | "email" | "hostname" | "idn-hostname" | "ipv4" | "ipv6"
            | "iri" | "iri-reference" | "json-pointer" | "regex" | "relative-json-pointer" | "uri"
            | "uri-reference" | "uri-template" | "uuid"
    )
}

fn is_reserved(k: &str) -> bool {
    matches!(k, "$schema" | "$id" | "$defs" | "$anchor" | "$dynamicAnchor")
}

fn is_known(k: &str) -> bool {
    matches!(
        k,
        "type" | "const" | "enum" | "minimum" | "maximum" | "exclusiveMinimum" | "exclusiveMaximum"
            | "multipleOf" | "minLength" | "maxLength" | "pattern" | "format" | "minItems" | "maxItems"
            | "uniqueItems" | "items" | "prefixItems" | "additionalItems" | "contains" | "minContains"
            | "maxContains" | "unevaluatedItems" | "minProperties" | "maxProperties" | "required"
            | "dependentRequired" | "properties" | "patternProperties" | "additionalProperties"
            | "propertyNames" | "dependencies" | "dependentSchemas" | "unevaluatedProperties"
            | "allOf" | "anyOf" | "oneOf" | "not" | "if" | "then" | "else" | "$ref"
    )
}

fn unescape_pointer(f: &str) -> Result<String, String> {
    if !f.starts_with('/') {
        return Ok(f.to_string());
    }
    Ok(f.replace("~1", "/").replace("~0", "~"))
}
