{"command": "cd /workspace && cat > src/schema.rs <<'RSEOF'
//! Schema compilation.

use crate::output::{ErrVal, Unit};
use regex::Regex;
use serde_json::{Map, Value};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Draft {
    V4,
    V6,
    V7,
    V2019,
    V2020,
}

impl Draft {
    pub fn from_str(s: &str) -> Option<Draft> {
        match s {
            "4" => Some(Draft::V4),
            "6" => Some(Draft::V6),
            "7" => Some(Draft::V7),
            "2019" => Some(Draft::V2019),
            "2020" => Some(Draft::V2020),
            _ => None,
        }
    }
    pub fn tuple_items(&self) -> bool {
        !matches!(self, Draft::V2020)
    }
    pub fn strict_integer(&self) -> bool {
        matches!(self, Draft::V4)
    }
}

pub struct Ctx {
    pub draft: Draft,
    pub assert_format: bool,
    pub registry: crate::registry::Registry,
    pub base_uri: String,
}

/// A compiled schema node.
pub struct Node {
    /// pointer used for the evaluation path
    pub pointer: String,
    /// pointer used to build the schemaLocation
    pub loc_pointer: String,
    pub uri: String,
    pub keywords: Vec<Keyword>,
    pub is_false: bool,
}

pub struct RefTarget {
    pub node: Box<Node>,
}

pub enum Keyword {
    Annotation { name: String, value: Value },
    Type(Vec<String>),
    Const(Value),
    Enum(Vec<Value>),
    MultipleOf(Value),
    Maximum { limit: Value, exclusive: bool, name: &'static str },
    Minimum { limit: Value, exclusive: bool, name: &'static str },
    MaxLength(u64),
    MinLength(u64),
    Pattern { re: Regex, raw: String },
    MaxItems(u64),
    MinItems(u64),
    UniqueItems,
    ItemsTuple(Vec<Box<Node>>),
    Items { single: Option<Box<Node>>, rest_from: usize, fast: Option<String> },
    PrefixItems(Vec<Box<Node>>),
    AdditionalItems { single: Option<Box<Node>>, rest_from: usize },
    Contains { schema: Box<Node>, min: Option<u64>, max: Option<u64> },
    UnevaluatedItems(Value),
    MinProperties(u64),
    MaxProperties(u64),
    Required(Vec<String>),
    DependentRequired(Vec<(String, Vec<String>)>),
    Properties(Vec<(String, Box<Node>)>, bool),
    PatternProperties(Vec<(String, Regex, Box<Node>)>, bool),
    AdditionalProperties {
        schema: Option<Box<Node>>,
        has_siblings: bool,
        props: Vec<String>,
        patterns: Vec<String>,
        is_bool: bool,
    },
    PropertyNames(Box<Node>),
    Dependencies(Vec<(String, Dependency)>),
    DependentSchemas(Vec<(String, Box<Node>)>),
    UnevaluatedProperties(Value),
    AllOf(Vec<Box<Node>>),
    AnyOf(Vec<Box<Node>>),
    OneOf(Vec<Box<Node>>),
    Not { node: Box<Node>, raw: Value },
    IfThenElse { cond: Box<Node>, then_: Option<Box<Node>>, else_: Option<Box<Node>> },
    Ref(Box<RefTarget>),
    Format(String),
}

pub enum Dependency {
    Names(Vec<String>),
    Schema(Box<Node>),
}

/// Result of validating one keyword.
pub struct KwRes {
    pub valid: bool,
    pub errors: Vec<(String, ErrVal)>,
    pub annotation: Option<Value>,
    pub details: Vec<Unit>,
    pub text: Vec<String>,
    pub props: Vec<String>,
    pub items: Vec<usize>,
}

impl KwRes {
    pub fn ok() -> KwRes {
        KwRes { valid: true, errors: vec![], annotation: None, details: vec![], text: vec![], props: vec![], items: vec![] }
    }
    pub fn one(keyword: &str, msg: String) -> KwRes {
        KwRes {
            valid: false,
            errors: vec![(keyword.to_string(), ErrVal::One(msg.clone()))],
            annotation: None,
            details: vec![],
            text: vec![msg],
            props: vec![],
            items: vec![],
        }
    }
    pub fn many(keyword: &str, msgs: Vec<String>) -> KwRes {
        let ev = if msgs.len() == 1 { ErrVal::One(msgs[0].clone()) } else { ErrVal::Many(msgs.clone()) };
        KwRes { valid: false, errors: vec![(keyword.to_string(), ev)], annotation: None, details: vec![], text: msgs, props: vec![], items: vec![] }
    }
    pub fn two(keyword: &str, basic: String, text: String) -> KwRes {
        KwRes {
            valid: false,
            errors: vec![(keyword.to_string(), ErrVal::One(basic))],
            annotation: None,
            details: vec![],
            text: vec![text],
            props: vec![],
            items: vec![],
        }
    }
}

pub struct NodeRes {
    pub valid: bool,
    pub units: Vec<Unit>,
    pub annotations: Vec<(String, Value)>,
    pub text: Vec<String>,
    pub props: Vec<String>,
    pub items: Vec<usize>,
}

pub fn escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn ptr_join(pointer: &str, keyword: &str) -> String {
    format!("{}/{}", pointer, keyword)
}

fn ptr_index(pointer: &str, keyword: &str, index: usize) -> String {
    format!("{}/{}/{}", pointer, keyword, index)
}

fn compile_sub(
    schema: &Value,
    pointer: &str,
    loc_pointer: &str,
    kw: &str,
    idx: Option<usize>,
    uri: &str,
    ctx: &mut Ctx,
) -> Result<Node, String> {
    let (p, lp) = match idx {
        Some(i) => (ptr_index(pointer, kw, i), ptr_index(loc_pointer, kw, i)),
        None => (ptr_join(pointer, kw), ptr_join(loc_pointer, kw)),
    };
    compile(schema, &p, &lp, uri, ctx)
}

fn compile_opt_sub(
    sub: &Value,
    pointer: &str,
    loc_pointer: &str,
    kw: &str,
    uri: &str,
    ctx: &mut Ctx,
) -> Option<Box<Node>> {
    match sub {
        Value::Bool(true) => None,
        _ => Some(Box::new(compile_sub(sub, pointer, loc_pointer, kw, None, uri, ctx).ok()?)),
    }
}

pub fn compile(schema: &Value, pointer: &str, loc_pointer: &str, uri: &str, ctx: &mut Ctx) -> Result<Node, String> {
    if let Value::Bool(false) = schema {
        return Ok(Node { pointer: pointer.into(), loc_pointer: loc_pointer.into(), uri: uri.into(), keywords: vec![], is_false: true });
    }
    let obj: Map<String, Value> = match schema {
        Value::Object(o) => o.clone(),
        Value::Bool(true) => Map::new(),
        _ => return Err(format!("{} is not of types \"boolean\", \"object\"", crate::jsonval::to_string_compact(schema))),
    };
    let mut keywords: Vec<Keyword> = Vec::new();

    for name in ["$id", "$schema"] {
        if let Some(Value::String(s)) = obj.get(name) {
            if let Err(e) = crate::uri::validate_uri_reference(s) {
                return Err(format!("Invalid URI reference '{}': {}", s, e));
            }
        }
    }
    let uri_here = match obj.get("$id") {
        Some(Value::String(id)) => crate::uri::resolve(uri, id),
        _ => uri.to_string(),
    };
    for container in ["$defs", "definitions"] {
        if let Some(Value::Object(defs)) = obj.get(container) {
            for (k, v) in defs {
                compile_sub(v, pointer, loc_pointer, container, None, &uri_here, ctx)
                    .map_err(|_| ())?;
                // recompile with the proper pointer so errors point at the item
                let p = format!("{}/{}/{}", pointer, container, escape(k));
                let lp = format!("{}/{}/{}", loc_pointer, container, escape(k));
                compile(v, &p, &lp, &uri_here, ctx)?;
            }
        }
    }

    if let Some(v) = obj.get("type") {
        let expected: Vec<String> = match v {
            Value::String(s) => vec![s.clone()],
            Value::Array(a) => a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect(),
            _ => vec![],
        };
        let mut expected = expected;
        expected.sort();
        keywords.push(Keyword::Type(expected));
    }
    if let Some(v) = obj.get("const") {
        keywords.push(Keyword::Const(v.clone()));
    }
    if let Some(Value::Array(items)) = obj.get("enum") {
        keywords.push(Keyword::Enum(items.clone()));
    }
    if let Some(v) = obj.get("minimum") {
        keywords.push(Keyword::Minimum { limit: v.clone(), exclusive: false, name: "minimum" });
    }
    if let Some(v) = obj.get("maximum") {
        keywords.push(Keyword::Maximum { limit: v.clone(), exclusive: false, name: "maximum" });
    }
    if let Some(v) = obj.get("exclusiveMinimum") {
        match v {
            Value::Bool(true) => {
                if let Some(m) = obj.get("minimum") {
                    keywords.push(Keyword::Minimum { limit: m.clone(), exclusive: true, name: "exclusiveMinimum" });
                }
            }
            Value::Number(_) => keywords.push(Keyword::Minimum { limit: v.clone(), exclusive: true, name: "exclusiveMinimum" }),
            _ => {}
        }
    }
    if let Some(v) = obj.get("exclusiveMaximum") {
        match v {
            Value::Bool(true) => {
                if let Some(m) = obj.get("maximum") {
                    keywords.push(Keyword::Maximum { limit: m.clone(), exclusive: true, name: "exclusiveMaximum" });
                }
            }
            Value::Number(_) => keywords.push(Keyword::Maximum { limit: v.clone(), exclusive: true, name: "exclusiveMaximum" }),
            _ => {}
        }
    }
    if let Some(v) = obj.get("multipleOf") {
        keywords.push(Keyword::MultipleOf(v.clone()));
    }
    if let Some(v) = obj.get("minLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinLength(n));
        }
    }
    if let Some(v) = obj.get("maxLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxLength(n));
        }
    }
    if let Some(Value::String(p)) = obj.get("pattern") {
        if let Ok(re) = Regex::new(p) {
            keywords.push(Keyword::Pattern { re, raw: p.clone() });
        }
    }
    if let Some(Value::String(f)) = obj.get("format") {
        if known_format(f) {
            keywords.push(Keyword::Format(f.clone()));
        }
    }
    if let Some(v) = obj.get("minItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinItems(n));
        }
    }
    if let Some(v) = obj.get("maxItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxItems(n));
        }
    }
    if obj.get("uniqueItems").and_then(|v| v.as_bool()) == Some(true) {
        keywords.push(Keyword::UniqueItems);
    }
    let mut prefix_len = 0usize;
    let mut prefix_nodes: Option<Vec<Box<Node>>> = None;
    if let Some(Value::Array(a)) = obj.get("prefixItems") {
        let mut v = Vec::new();
        for (i, sub) in a.iter().enumerate() {
            v.push(Box::new(compile_sub(sub, pointer, loc_pointer, "prefixItems", Some(i), &uri_here, ctx)?));
        }
        prefix_len = v.len();
        prefix_nodes = Some(v);
    }
    match obj.get("items") {
        Some(Value::Array(a)) => {
            let mut v = Vec::new();
            for (i, sub) in a.iter().enumerate() {
                v.push(Box::new(compile_sub(sub, pointer, loc_pointer, "items", Some(i), &uri_here, ctx)?));
            }
            prefix_len = v.len();
            keywords.push(Keyword::ItemsTuple(v));
            if let Some(sub) = obj.get("additionalItems") {
                let single = compile_opt_sub(sub, pointer, loc_pointer, "additionalItems", &uri_here, ctx);
                keywords.push(Keyword::AdditionalItems { single, rest_from: prefix_len });
            }
        }
        Some(sub) => {
            let fast = if prefix_nodes.is_some() {
                None
            } else {
                match sub {
                    Value::Object(o) if o.len() == 1 => o.get("type").and_then(|t| t.as_str()).map(|s| s.to_string()),
                    _ => None,
                }
            };
            let single = compile_opt_sub(sub, pointer, loc_pointer, "items", &uri_here, ctx);
            keywords.push(Keyword::Items { single, rest_from: prefix_len, fast });
            if let Some(pn) = prefix_nodes.take() {
                keywords.push(Keyword::PrefixItems(pn));
            }
        }
        None => {}
    }
    if let Some(pn) = prefix_nodes.take() {
        keywords.push(Keyword::PrefixItems(pn));
    }
    if let Some(v) = obj.get("contains") {
        let single = Box::new(compile_sub(v, pointer, loc_pointer, "contains", None, &uri_here, ctx)?);
        let min = obj.get("minContains").and_then(|x| x.as_u64());
        let max = obj.get("maxContains").and_then(|x| x.as_u64());
        keywords.push(Keyword::Contains { schema: single, min, max });
    }
    if let Some(v) = obj.get("unevaluatedItems") {
        if !v.is_boolean() || *v == Value::Bool(false) {
            keywords.push(Keyword::UnevaluatedItems(v.clone()));
        }
    }
    if let Some(v) = obj.get("minProperties") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinProperties(n));
        }
    }
    if let Some(v) = obj.get("maxProperties") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxProperties(n));
        }
    }
    if let Some(Value::Array(a)) = obj.get("required") {
        keywords.push(Keyword::Required(a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect()));
    }
    if let Some(Value::Object(o)) = obj.get("dependentRequired") {
        keywords.push(Keyword::DependentRequired(
            o.iter()
                .map(|(k, val)| {
                    (
                        k.clone(),
                        val.as_array()
                            .map(|a| a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect())
                            .unwrap_or_default(),
                    )
                })
                .collect(),
        ));
    }
    let props: Vec<(String, Box<Node>)> = match obj.get("properties") {
        Some(Value::Object(o)) => {
            let mut v = Vec::new();
            for (k, sub) in o {
                let (p, lp) = (format!("{}/properties/{}", pointer, escape(k)), format!("{}/properties/{}", loc_pointer, escape(k)));
                v.push((k.clone(), Box::new(compile(sub, &p, &lp, &uri_here, ctx)?)));
            }
            v
        }
        _ => Vec::new(),
    };
    let pprops: Vec<(String, Regex, Box<Node>)> = match obj.get("patternProperties") {
        Some(Value::Object(o)) => {
            let mut v = Vec::new();
            for (k, sub) in o {
                if let Ok(re) = Regex::new(k) {
                    let (p, lp) = (
                        format!("{}/patternProperties/{}", pointer, escape(k)),
                        format!("{}/patternProperties/{}", loc_pointer, escape(k)),
                    );
                    v.push((k.clone(), re, Box::new(compile(sub, &p, &lp, &uri_here, ctx)?)));
                }
            }
            v
        }
        _ => Vec::new(),
    };
    let additional_raw = obj.get("additionalProperties");
    let additional: Option<Box<Node>> = match additional_raw {
        Some(Value::Bool(true)) => None,
        Some(Value::Bool(false)) => Some(Box::new(Node {
            pointer: ptr_join(pointer, "additionalProperties"),
            loc_pointer: ptr_join(loc_pointer, "additionalProperties"),
            uri: uri_here.clone(),
            keywords: vec![],
            is_false: true,
        })),
        Some(sub) => Some(Box::new(compile_sub(sub, pointer, loc_pointer, "additionalProperties", None, &uri_here, ctx)?)),
        None => None,
    };
