        let mut expected = expected;
        expected.sort();
        keywords.push(Keyword::Type(expected));
    }
    if let Some(v) = obj.get("const") {
        keywords.push(Keyword::Const(v.clone()));
    }
    if let Some(Value::Array(items)) = obj.get("enum") {
        keywords.push(Keyword::Enum(items.clone()));
    }
    if let Some(v) = obj.get("minimum") {
