                if let Some(m) = obj.get("minimum") {
                    keywords.push(Keyword::Minimum { limit: m.clone(), exclusive: true, name: "exclusiveMinimum" });
                }
            }
            Value::Number(_) => keywords.push(Keyword::Minimum { limit: v.clone(), exclusive: true, name: "exclusiveMinimum" }),
            _ => {}
        }
    }
    if let Some(v) = obj.get("exclusiveMaximum") {
        match v {
            Value::Bool(true) => {
                if let Some(m) = obj.get("maximum") {
                    keywords.push(Keyword::Maximum { limit: m.clone(), exclusive: true, name: "exclusiveMaximum" });
                }
            }
            Value::Number(_) => keywords.push(Keyword::Maximum { limit: v.clone(), exclusive: true, name: "exclusiveMaximum" }),
            _ => {}
        }
    }
    if let Some(v) = obj.get("multipleOf") {
        keywords.push(Keyword::MultipleOf(v.clone()));
    }
    if let Some(v) = obj.get("minLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinLength(n));
        }
    }
    if let Some(v) = obj.get("maxLength") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxLength(n));
        }
    }
    if let Some(Value::String(p)) = obj.get("pattern") {
        if let Ok(re) = Regex::new(p) {
            keywords.push(Keyword::Pattern { re, raw: p.clone() });
        }
    }
    if let Some(Value::String(f)) = obj.get("format") {
