    }
    if let Some(v) = obj.get("minItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MinItems(n));
        }
    }
    if let Some(v) = obj.get("maxItems") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxItems(n));
        }
    }
    if obj.get("uniqueItems").and_then(|v| v.as_bool()) == Some(true) {
        keywords.push(Keyword::UniqueItems);
    }
    let mut prefix_len = 0usize;
    let mut prefix_nodes: Option<Vec<Box<Node>>> = None;
