    if let Some(v) = obj.get("maxProperties") {
        if let Some(n) = v.as_u64() {
            keywords.push(Keyword::MaxProperties(n));
        }
    }
    if let Some(Value::Array(a)) = obj.get("required") {
        keywords.push(Keyword::Required(a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect()));
    }
    if let Some(Value::Object(o)) = obj.get("dependentRequired") {
        keywords.push(Keyword::DependentRequired(
            o.iter()
                .map(|(k, val)| {
                    (
                        k.clone(),
                        val.as_array()
                            .map(|a| a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect())
                            .unwrap_or_default(),
                    )
                })
                .collect(),
        ));
    }
    let props: Vec<(String, Box<Node>)> = match obj.get("properties") {
        Some(Value::Object(o)) => {
            let mut v = Vec::new();
            for (k, sub) in o {
                let (p, lp) = (format!("{}/properties/{}", pointer, escape(k)), format!("{}/properties/{}", loc_pointer, escape(k)));
                v.push((k.clone(), Box::new(compile(sub, &p, &lp, &uri_here, ctx)?)));
            }
            v
        }
        _ => Vec::new(),
    };
    let pprops: Vec<(String, Regex, Box<Node>)> = match obj.get("patternProperties") {
        Some(Value::Object(o)) => {
            let mut v = Vec::new();
            for (k, sub) in o {
                if let Ok(re) = Regex::new(k) {
                    let (p, lp) = (
                        format!("{}/patternProperties/{}", pointer, escape(k)),
                        format!("{}/patternProperties/{}", loc_pointer, escape(k)),
                    );
                    v.push((k.clone(), re, Box::new(compile(sub, &p, &lp, &uri_here, ctx)?)));
                }
            }
            v
        }
        _ => Vec::new(),
    };
    let additional_raw = obj.get("additionalProperties");
    let additional: Option<Box<Node>> = match additional_raw {
        Some(Value::Bool(true)) => None,
        Some(Value::Bool(false)) => Some(Box::new(Node {
            pointer: ptr_join(pointer, "additionalProperties"),
            loc_pointer: ptr_join(loc_pointer, "additionalProperties"),
            uri: uri_here.clone(),
            keywords: vec![],
            is_false: true,
        })),
        Some(sub) => Some(Box::new(compile_sub(sub, pointer, loc_pointer, "additionalProperties", None, &uri_here, ctx)?)),
        None => None,
    };
    let has_siblings = !props.is_empty() || !pprops.is_empty();
    let merged = matches!(additional_raw, Some(Value::Bool(false)))
        || (additional_raw.is_some() && !matches!(additional_raw, Some(Value::Bool(true))));
    let prop_names: Vec<String> = props.iter().map(|(k, _)| k.clone()).collect();
    let pattern_names: Vec<String> = pprops.iter().map(|(k, _, _)| k.clone()).collect();
    if !props.is_empty() {
        keywords.push(Keyword::Properties(props, merged));
    }
    if !pprops.is_empty() {
        keywords.push(Keyword::PatternProperties(pprops, merged));
    }
    if let Some(schema) = additional {
        keywords.push(Keyword::AdditionalProperties {
            schema: Some(schema),
            has_siblings,
            props: prop_names,
            patterns: pattern_names,
            is_bool: matches!(additional_raw, Some(Value::Bool(_))),
        });
    }
    if let Some(v) = obj.get("propertyNames") {
        if !v.is_boolean() || *v == Value::Bool(false) {
            let node = match v {
                Value::Bool(_) => Node {
                    pointer: ptr_join(pointer, "propertyNames"),
                    loc_pointer: ptr_join(loc_pointer, "propertyNames"),
                    uri: uri_here.clone(),
                    keywords: vec![],
                    is_false: true,
                },
                _ => compile_sub(v, pointer, loc_pointer, "propertyNames", None, &uri_here, ctx)?,
            };
            keywords.push(Keyword::PropertyNames(Box::new(node)));
        }
    }
    if let Some(Value::Object(o)) = obj.get("dependencies") {
        let mut v: Vec<(String, Dependency)> = Vec::new();
        for (k, val) in o {
            match val {
                Value::Array(a) => v.push((k.clone(), Dependency::Names(a.iter().filter_map(|x| x.as_str()).map(|s| s.to_string()).collect()))),
                other => v.push((k.clone(), Dependency::Schema(Box::new(compile_sub(other, pointer, loc_pointer, "dependencies", None, &uri_here, ctx)?)))),
            }
        }
        keywords.push(Keyword::Dependencies(v));
    }
    if let Some(Value::Object(o)) = obj.get("dependentSchemas") {
        keywords.push(Keyword::DependentSchemas(
            o.iter()
                .map(|(k, val)| Ok((k.clone(), Box::new(compile_sub(val, pointer, loc_pointer, "dependentSchemas", None, &uri_here, ctx)?))))
                .collect::<Result<Vec<_>, String>>()?,
        ));
    }
    if let Some(v) = obj.get("unevaluatedProperties") {
        if !v.is_boolean() || *v == Value::Bool(false) {
            keywords.push(Keyword::UnevaluatedProperties(v.clone()));
        }
    }
    for (kw, var) in [("allOf", 0u8), ("anyOf", 1), ("oneOf", 2)] {
        if let Some(Value::Array(a)) = obj.get(kw) {
            let mut v = Vec::new();
            for (i, sub) in a.iter().enumerate() {
                v.push(Box::new(compile_sub(sub, pointer, loc_pointer, kw, Some(i), &uri_here, ctx)?));
            }
            match var {
                0 => keywords.push(Keyword::AllOf(v)),
                1 => keywords.push(Keyword::AnyOf(v)),
                _ => keywords.push(Keyword::OneOf(v)),
            }
        }
    }
    if let Some(v) = obj.get("not") {
        let node = match v {
            Value::Bool(_) => Node {
                pointer: ptr_join(pointer, "not"),
                loc_pointer: ptr_join(loc_pointer, "not"),
                uri: uri_here.clone(),
                keywords: vec![],
                is_false: *v == Value::Bool(false),
            },
            _ => compile_sub(v, pointer, loc_pointer, "not", None, &uri_here, ctx)?,
        };
        keywords.push(Keyword::Not { node: Box::new(node), raw: v.clone() });
    }
    if obj.contains_key("if") || obj.contains_key("then") || obj.contains_key("else") {
        let cond = match obj.get("if") {
            Some(v) => match v {
                Value::Bool(_) => Node { pointer: ptr_join(pointer, "if"), loc_pointer: ptr_join(loc_pointer, "if"), uri: uri_here.clone(), keywords: vec![], is_false: *v == Value::Bool(false) },
                _ => compile_sub(v, pointer, loc_pointer, "if", None, &uri_here, ctx)?,
            },
            None => Node { pointer: ptr_join(pointer, "if"), loc_pointer: ptr_join(loc_pointer, "if"), uri: uri_here.clone(), keywords: vec![], is_false: false },
        };
        let then_ = match obj.get("then") {
            Some(v) => Some(match v {
                Value::Bool(_) => Node { pointer: ptr_join(pointer, "then"), loc_pointer: ptr_join(loc_pointer, "then"), uri: uri_here.clone(), keywords: vec![], is_false: *v == Value::Bool(false) },
                _ => compile_sub(v, pointer, loc_pointer, "then", None, &uri_here, ctx)?,
            }),
            None => None,
        };
        let else_ = match obj.get("else") {
            Some(v) => Some(match v {
                Value::Bool(_) => Node { pointer: ptr_join(pointer, "else"), loc_pointer: ptr_join(loc_pointer, "else"), uri: uri_here.clone(), keywords: vec![], is_false: *v == Value::Bool(false) },
                _ => compile_sub(v, pointer, loc_pointer, "else", None, &uri_here, ctx)?,
            }),
            None => None,
        };
        keywords.push(Keyword::IfThenElse { cond: Box::new(cond), then_: then_.map(Box::new), else_: else_.map(Box::new) });
    }
    if let Some(Value::String(r)) = obj.get("$ref") {
        if let Err(e) = crate::uri::validate_uri_reference(r) {
            return Err(format!("Invalid URI reference '{}': {}", r, e));
        }
        let resolved = crate::uri::resolve(&uri_here, r);
        let (target_uri, fragment) = crate::uri::split_fragment(&resolved);
        let target = ctx.registry.get(target_uri)?;
        let sub_pointer = fragment.map(|f| unescape_pointer(f).unwrap_or_default()).unwrap_or_default();
        let sub = match fragment {
            Some(f) if !f.is_empty() => {
                let p = unescape_pointer(f)?;
                match crate::pointer::get(&target, &p) {
                    Some(v) => v.clone(),
                    None => return Err(format!("Pointer '{}' does not exist", p)),
                }
            }
            _ => target.clone(),
        };
        let node = Box::new(compile(&sub, &ptr_join(pointer, "$ref"), &sub_pointer, target_uri, ctx)?);
        keywords.push(Keyword::Ref(Box::new(RefTarget { node })));
    }
    for (k, v) in &obj {
        if is_reserved(k) || is_known(k) {
            continue;
        }
        keywords.push(Keyword::Annotation { name: k.clone(), value: v.clone() });
    }
    Ok(Node { pointer: pointer.into(), loc_pointer: loc_pointer.into(), uri: uri_here.into(), keywords, is_false: false })
}

fn known_format(f: &str) -> bool {
    matches!(
        f,
        "date" | "date-time" | "time" | "duration" | "email" | "hostname" | "idn-hostname" | "ipv4" | "ipv6"
            | "iri" | "iri-reference" | "json-pointer" | "regex" | "relative-json-pointer" | "uri"
            | "uri-reference" | "uri-template" | "uuid"
    )
}

fn is_reserved(k: &str) -> bool {
    matches!(k, "$schema" | "$id" | "$defs" | "$anchor" | "$dynamicAnchor")
}

fn is_known(k: &str) -> bool {
    matches!(
        k,
        "type" | "const" | "enum" | "minimum" | "maximum" | "exclusiveMinimum" | "exclusiveMaximum"
            | "multipleOf" | "minLength" | "maxLength" | "pattern" | "format" | "minItems" | "maxItems"
            | "uniqueItems" | "items" | "prefixItems" | "additionalItems" | "contains" | "minContains"
            | "maxContains" | "unevaluatedItems" | "minProperties" | "maxProperties" | "required"
            | "dependentRequired" | "properties" | "patternProperties" | "additionalProperties"
            | "propertyNames" | "dependencies" | "dependentSchemas" | "unevaluatedProperties"
            | "allOf" | "anyOf" | "oneOf" | "not" | "if" | "then" | "else" | "$ref"
    )
}

fn unescape_pointer(f: &str) -> Result<String, String> {
    if !f.starts_with('/') {
        return Ok(f.to_string());
    }
    Ok(f.replace("~1", "/").replace("~0", "~"))
}
