        if line[:2].isdigit() or (len(line)>2 and line[0].isdigit() and line[1]=='.'):
            errs.add(line.split('. ',1)[1])
    keys=set()
    for k in props:
        pass
    ob,rb=run(B,["one.json","-i","one.json.i","--assert-format"])
