/// Simplified punycode decoder: returns true when the input decodes and the
/// result looks like a valid IDNA label.
fn punycode_decode_ok(input: &str) -> bool {
    let chars: Vec<char> = input.chars().collect();
    if chars.is_empty() {
        return false;
    }
    let mut basic_end = chars.len();
    for (i, c) in chars.iter().enumerate() {
        if *c == '-' {
            if i > 0 {
                basic_end = i;
            }
            break;
        }
    }
    let mut output: Vec<char> = chars[..basic_end].to_vec();
    let mut i = basic_end;
    if i < chars.len() && chars[i] == '-' {
        i += 1;
    }
    let mut n: u32 = 128;
    let mut delta: u32 = 0;
    let mut bias: u32 = 72;
    let mut tmax: u32 = 26;
    let mut done = false;
    while i < chars.len() {
        let oldi = delta;
        let mut w: u32 = 1;
        let mut k = 1u32;
        loop {
            if i >= chars.len() {
                return false;
            }
            let digit = match digit_value(chars[i]) {
                Some(d) => d,
                None => return false,
            };
            i += 1;
            delta = delta.checked_add(digit.checked_mul(w)?)?;
            let t = if k <= bias { 1 } else if k >= bias + tmax { tmax } else { k - bias };
            if digit < t {
                break;
            }
            w = w.checked_mul(36 - t)?;
            k += 36;
        }
        let len = output.len() as u32 + 1;
        bias = adapt(delta.checked_sub(oldi)?, len, oldi == 0);
        n = n.checked_add(delta / len)?;
        delta = delta % len;
        output.insert(delta as usize, char::from_u32(n)?);
        delta += 1;
        done = true;
    }
    if !done && basic_end == chars.len() {
        return false;
    }
    let text: String = output.iter().collect();
    if text.is_empty() {
        return false;
    }
    if text.starts_with('-') || text.ends_with('-') {
        return false;
    }
    true
}

fn digit_value(c: char) -> Option<u32> {
    match c {
        'a'..='z' => Some(c as u32 - 'a' as u32),
        'A'..='Z' => Some(c as u32 - 'A' as u32),
        '0'..='9' => Some(c as u32 - '0' as u32 + 26),
        _ => None,
    }
}

fn adapt(delta: u32, numpoints: u32, firsttime: bool) -> u32 {
    let mut delta = if firsttime { delta / 700 } else { delta / 2 };
    delta += delta / numpoints;
    let mut k = 0;
    while delta > 455 {
        delta /= 35;
        k += 36;
    }
    k + (36 * delta) / (delta + 38)
}

