use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub struct UriError {
    pub message: String,
}

impl fmt::Display for UriError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

fn is_unreserved(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~')
}

fn is_sub_delim(b: u8) -> bool {
    matches!(b, b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';' | b'=')
}

fn is_pchar(b: u8) -> bool {
    is_unreserved(b) || is_sub_delim(b) || b == b':' || b == b'@'
}

fn is_scheme_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'+' || b == b'-' || b == b'.'
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
    unicode: bool,
}

impl<'a> Parser<'a> {
    fn err_unexpected(&self) -> UriError {
        UriError { message: format!("unexpected character at index {}", self.pos) }
    }
    fn err_pct(&self) -> UriError {
        UriError { message: format!("invalid percent-encoded octet at index {}", self.pos) }
    }

    fn allowed(&self, b: u8) -> bool {
        if self.unicode && b >= 0x80 {
            return true;
        }
        is_pchar(b)
    }

    /// consume a percent encoded triplet or a single allowed byte
    fn pchar(&mut self) -> Result<(), UriError> {
        let b = self.bytes[self.pos];
        if b == b'%' {
