fn punycode_decode_ok(input: &str) -> bool {
    let chars: Vec<char> = input.chars().collect();
    if chars.is_empty() {
        return false;
    }
    let (basic, extended): (Vec<char>, Vec<char>) = match chars.iter().rposition(|c| *c == '-') {
        Some(i) => (chars[..i].to_vec(), chars[i + 1..].to_vec()),
        None => (Vec::new(), chars.clone()),
