    let mut output: Vec<char> = basic.clone();
    let mut n: u64 = 128;
    let mut i: u64 = 0;
    let mut bias: u64 = 72;
    let mut pos = 0usize;
    if extended.is_empty() {
        // a label consisting only of basic characters is a valid punycode label
        return !output.is_empty();
    }
    while pos < extended.len() {
        let oldi = i;
        let mut w: u64 = 1;
        let mut k: u64 = 1;
