{"command": "cd /workspace && cat > src/registry.rs <<'RSEOF'
//! Resource registry: resolves `$ref` targets from files and HTTP.

use crate::http::HttpClient;
use serde_json::Value;
use std::collections::HashMap;
use std::sync::Mutex;

pub struct Registry {
    cache: Mutex<HashMap<String, Value>>,
    client: HttpClient,
}

impl Registry {
    pub fn new(client: HttpClient) -> Self {
        Registry { cache: Mutex::new(HashMap::new()), client }
    }

    pub fn get(&self, uri: &str) -> Result<Value, String> {
        let key = normalize_uri(uri);
        if let Some(v) = self.cache.lock().unwrap().get(&key) {
            return Ok(v.clone());
        }
        match self.fetch(&key) {
            Ok(v) => {
                self.cache.lock().unwrap().insert(key, v.clone());
                Ok(v)
            }
            Err(cause) => Err(format!(
                "Resource '{}' is not present in a registry and retrieving it failed: {}",
                key, cause
            )),
        }
    }

    fn fetch(&self, uri: &str) -> Result<Value, String> {
        let (without_fragment, _) = crate::uri::split_fragment(uri);
        if let Some(path) = without_fragment.strip_prefix("file://") {
            let data = std::fs::read(path).map_err(|e| e.to_string())?;
            let text = String::from_utf8_lossy(&data).to_string();
            return serde_json::from_str(&text).map_err(|e| e.to_string());
        }
        if let Some(rest) = without_fragment.strip_prefix("http://") {
            return self.fetch_http(format!("http://{}", rest));
        }
        if let Some(rest) = without_fragment.strip_prefix("https://") {
            return self.fetch_http(format!("https://{}", rest));
        }
        let scheme = without_fragment.split(':').next().unwrap_or("");
        Err(format!("Unknown scheme {}", scheme))
    }

    fn fetch_http(&self, url: &str) -> Result<Value, String> {
        let norm = normalize_http(url);
        match self.client.get(&norm) {
            Ok(body) => serde_json::from_str(&body).map_err(|_| format!("error decoding response body for url ({})", norm)),
            Err(e) => Err(e),
        }
    }
}

/// Normalize a URI the way a URL parser would (lower-case scheme/host, empty
/// path becomes "/").
pub fn normalize_uri(uri: &str) -> String {
    if uri.starts_with("http://") || uri.starts_with("https://") {
        normalize_http(uri)
    } else {
        uri.to_string()
    }
}

fn normalize_http(url: &str) -> String {
    let (scheme, rest) = match url.find("://") {
        Some(i) => (&url[..i], &url[i + 3..]),
        None => return url.to_string(),
    };
    let scheme = scheme.to_lowercase();
    let (authority, path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, "/"),
    };
    let authority = authority.to_lowercase();
    let authority = match authority.rfind('@') {
        Some(i) => format!("{}{}", &authority[..i], &authority[i..].to_lowercase()),
        None => authority,
    };
    format!("{}://{}{}", scheme, authority, path)
}
