{"command": "cd /workspace && python3 - <<'PY'
p='src/cli.rs'
s=open(p).read()
s=s.replace('''    // URI-reference errors and the meta-schema check
    if args.output == "text" {
    if let Some(msg) = crate::meta::check(&schema, draft) {
        match args.output.as_str() {
            "text" | "flag" | "flag2" => {
                if args.output == "text" {
                    println!("Schema is invalid. Error: {}", msg);
                } else {
                    let mut payload = serde_json::Map::new();
                    payload.insert("valid".to_string(), Value::Bool(false));
                    print_result_schema("flag", Value::Object(payload), &schema_path);
                }
                exit(1);
            }
            _ => {
                let mut payload = serde_json::Map::new();
                payload.insert("details".to_string(), Value::Array(vec![crate::meta::error_unit(msg, draft)]));
                payload.insert("valid".to_string(), Value::Bool(false));
                if args.output == "hierarchical" {
                    print_result_schema("hierarchical", Value::Object(payload), &schema_path);
                } else {
                    print_result_schema("list", Value::Object(payload), &schema_path);
                }
                exit(1);
            }
        }
    }''','''    // URI-reference errors and the meta-schema check
    if args.output == "text" {
        if let Some(msg) = crate::meta::check(&schema, draft) {
            report(&msg, "text");
            exit(1);
        }
    }''')
open(p,'w').write(s)
PY
