import sys, json, glob, os; sys.path.insert(0,'/tmp/t')
exec(open('/tmp/t/batch.py').read())
ok=0;bad=0;fails=[]
names=sorted(set(glob.glob('/tmp/t/*.json')) - set(glob.glob('/tmp/t/*.json.i')))
for f in names:
    base=f[:-5]; inst=f+'.i'
    if not os.path.exists(inst): continue
    for out in ["text","list","hierarchical","flag"]:
        oa,ra=run(A,[base,"-i",base+".json.i","--output",out]); ob,rb=run(B,[base,"-i",base+".json.i","--output",out])
